window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s5-294","number":294,"surah":5,"verses":[51],"references":[{"surah":5,"verses":[51]}],"verseLabel":"المائدة: 51","question":"ما دلالة التوكيد في قوله تعالى: ﴿ومن يتولهم منكم فإنه منهم﴾؟","answer":"جاءت الجملة شرطية للتغليظ والتهديد؛ فمن تولاهم بالولاية الكاملة التي تبلغ الرضا بدينهم والطعن في الإسلام صار منهم، ولا تدخل فيها المعاملة المجردة من المصافاة","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص298–299، تحت «الجناس الناقص في قوله ومن يتولهم منكم فإنه منهم»","url":""}]},{"id":"s5-295","number":295,"surah":5,"verses":[51],"references":[{"surah":5,"verses":[51]}],"verseLabel":"المائدة: 51","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله لا يهدي القوم الظالمين﴾؟","answer":"جاءت الخاتمة تذييلًا للنهي وتهديدًا لمن يتولى تلك الموالاة، وتأكيدًا لوصف الظلم. وهي بمثابة تعليل للتحذير بما يترتب على الفعل من الضرر؛ ومن توجيهات المصدر أن الله يترك من اختار هذا المسلك في غيه وضلاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص299–300، تحت عنوان «دلالة تذييل الآية بقوله: ﴿إن الله لا يهدي القوم الظالمين﴾»","url":""}]},{"id":"s5-296","number":296,"surah":5,"verses":[52],"references":[{"surah":5,"verses":[52]}],"verseLabel":"المائدة: 52","question":"ما سر التعبير عن المنافقين بقوله تعالى: ﴿في قلوبهم مرض﴾؟","answer":"صار هذا الوصف علامة على المنافقين، فذكره يستدعي صفاتهم في الذهن في إيجاز بليغ. وسُمي النفاق مرضًا لأنه مفسد للإيمان، كما يفسد المرض صحة البدن.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص304، تحت عنوان «سر التعبير بقوله: ﴿في قلوبهم مرض﴾»","url":""}]},{"id":"s5-661","number":661,"surah":5,"verses":[52],"references":[{"surah":5,"verses":[52]}],"verseLabel":"المائدة: 52","question":"لماذا قيل ﴿يسارعون فيهم﴾ بدل «يسارعون إليهم»؟","answer":"تفيد ﴿في﴾ أنهم مستقرون في الموالاة، وإنما ينتقلون مسرعين من بعض مراتبها إلى بعض. وفي تصوير المسارعة داخلهم مبالغة في شدة تعلقهم بالموالاة ورغبتهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص303–304، تحت عنوان «إيثار اسم الموصول (الذين) على ضمير القوم، وإيثار كلمة (في) على كلمة (إلى)»","url":""}]},{"id":"s5-297","number":297,"surah":5,"verses":[52],"references":[{"surah":5,"verses":[52]}],"verseLabel":"المائدة: 52","question":"ما دلالة قولهم: ﴿نخشى أن تصيبنا دائرة﴾؟","answer":"الدائرة ما تدور به الأيام من تحول الغلبة والرخاء إلى ضدّهما؛ فاتخذ المنافقون خوفهم من انقلاب الأحوال ذريعة لموالاة الفريق الذي ظنوا أن القوة قد تصير إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص304–305، تحت «دلالة القيد بالحال وتضمنه استعارة وكناية»","url":""}]},{"id":"s5-298","number":298,"surah":5,"verses":[52],"references":[{"surah":5,"verses":[52]}],"verseLabel":"المائدة: 52","question":"ما دلالة ﴿عسى﴾ في قوله تعالى: ﴿فعسى الله أن يأتي بالفتح أو أمر من عنده﴾؟","answer":"أُبرز اليقين في صورة الرجاء؛ فعسى من الله وعد محقق، وفي هذا الأسلوب بشارة للمؤمنين بالنصر، وبث للسكينة في قلوبهم وترقب الخير الموعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص306، تحت عنوان «ذكر الرجاء في موضع التأكيد في قوله: ﴿فعسى الله أن يأتي بالفتح أو أمر من عنده﴾»","url":""}]},{"id":"s5-662","number":662,"surah":5,"verses":[52],"references":[{"surah":5,"verses":[52]}],"verseLabel":"المائدة: 52","question":"ما دلالة ﴿أو﴾ في قوله تعالى: ﴿بالفتح أو أمر من عنده﴾؟","answer":"جاءت للتقسيم؛ فمن توجيهات المصدر أن الفتح يكون بسبب سعي النبي ﷺ وأصحابه، وأن الأمر الآخر يأتي من عند الله من غير تسبب البشر فيه. وتنوع التفسير يبين أن النصر الموعود لا ينحصر في صورة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص306–307، تحت عنوان «دلالة (أو) على التقسيم في قوله: ﴿أو أمر من عنده﴾»","url":""}]},{"id":"s5-299","number":299,"surah":5,"verses":[52],"references":[{"surah":5,"verses":[52]}],"verseLabel":"المائدة: 52","question":"ما الكناية في قوله تعالى: ﴿فيصبحوا على ما أسروا في أنفسهم نادمين﴾؟","answer":"فيه كناية عن انكشاف النفاق الذي أخفوه؛ فبعد ظهور نصر الله يندمون على ما أسرّوه من الكفر والشك، وهو الأصل الذي حملهم على تلك الموالاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص307، تحت عنوان «الكناية عن إظهار النفاق وكشفه: ﴿فيصبحوا على ما أسروا في أنفسهم نادمين﴾»","url":""}]},{"id":"s5-663","number":663,"surah":5,"verses":[52],"references":[{"surah":5,"verses":[52]}],"verseLabel":"المائدة: 52","question":"ما وجه الطباق الخفي بين ﴿يصبحوا﴾ و﴿أسروا﴾؟","answer":"الإسرار يلائم المساء والستر، فجاء الإصباح في مقابلته بطباق خفي، وإن كان الطباق الظاهر بين الصباح والمساء. وفيه تصوير لكشف خبايا النفوس وظهور ما يسترونه سريعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص308، تحت عنوان «دلالة الطباق الخفي بين (يصبحوا) و(أسروا)»","url":""}]},{"id":"s5-300","number":300,"surah":5,"verses":[53],"references":[{"surah":5,"verses":[53]}],"verseLabel":"المائدة: 53","question":"ما دلالة تعجب المؤمنين بقولهم: ﴿أهؤلاء الذين أقسموا بالله جهد أيمانهم إنهم لمعكم﴾؟","answer":"الاستفهام للتعجب من نفاق الذين أقسموا أنهم مع المؤمنين يقاتلون معهم وينصرونهم؛ فعند إتيان الفتح ظهر من حالهم ما فضحهم وكشف كذب حلفهم على الإخلاص للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص311، تحت عنوان «خروج الاستفهام إلى معنى التعجب في قوله: ﴿أهؤلاء الذين أقسموا﴾»","url":""}]},{"id":"s5-301","number":301,"surah":5,"verses":[53],"references":[{"surah":5,"verses":[53]}],"verseLabel":"المائدة: 53","question":"ما دلالة قوله تعالى: ﴿جهد أيمانهم﴾؟","answer":"أي أقصى ما يستطيعونه من توكيد الحلف؛ فالإضافة تبين أنهم استفرغوا طاقتهم في تثبيت دعوى النصرة، وبذلك يشتد التناقض بين ظاهر أيمانهم وحقيقة ولائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص312، تحت عنوان «الاستعارة في قوله: ﴿أهؤلاء الذين أقسموا بالله جهد أيمانهم﴾»","url":""}]},{"id":"s5-302","number":302,"surah":5,"verses":[53],"references":[{"surah":5,"verses":[53]}],"verseLabel":"المائدة: 53","question":"ما مناسبة قوله تعالى بعد أيمانهم: ﴿حبطت أعمالهم فأصبحوا خاسرين﴾؟","answer":"تقرر الجملة بطلان أعمالهم وما انتهوا إليه من خسران بعد دعوى الولاء وتوكيدها بالأيمان. ومن توجيهاتها أن الخبر خرج إلى التعجيب من شدة حبوط أعمالهم وخسارتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص313، تحت عنوان «الجملة بين الخبر والإنشاء»","url":""}]},{"id":"s5-303","number":303,"surah":5,"verses":[54],"references":[{"surah":5,"verses":[54]}],"verseLabel":"المائدة: 54","question":"كيف يجتمع الوعد والوعيد في قوله تعالى: ﴿فسوف يأتي الله بقوم يحبهم ويحبونه﴾؟","answer":"فيه وعد للمؤمنين ببقاء من ينصر الدين ويقوم بحقه، ووعيد للمرتدين؛ فالدين لا يعدم المخلصين ولا يتوقف نصره على من أعرض عنه. وقد جمع التعبير المعنيين في إيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص318–319، تحت عنوان «تضمن الوعد والوعيد في قوله: ﴿فسوف يأتي﴾ معاني كثيرة»","url":""}]},{"id":"s5-664","number":664,"surah":5,"verses":[54],"references":[{"surah":5,"verses":[54]}],"verseLabel":"المائدة: 54","question":"ما فائدة ﴿سوف﴾ في قوله تعالى: ﴿فسوف يأتي الله بقوم﴾؟","answer":"تفيد استقبالًا مع تراخٍ، فيستدعي الوعد صبر المؤمنين وبذل الجهد والثبات. ويشمل ذلك أن يأتي النصر على أيدي أجيال لاحقة، فلا يدل التعبير على استبدال فوري بكل فرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص317، تحت عنوان «فائدة حرف التسويف (سوف)»","url":""}]},{"id":"s5-304","number":304,"surah":5,"verses":[54],"references":[{"surah":5,"verses":[54]}],"verseLabel":"المائدة: 54","question":"لماذا قُدمت محبة الله لهم في قوله تعالى: ﴿يحبهم ويحبونه﴾؟","answer":"قُدمت محبته لهم لأنها أشرف وأسبق؛ ومن آثارها توفيقهم للإيمان والطاعة وإثابتهم عليها. ثم ذُكرت محبتهم له، وما تقتضيه من امتثال أمره واجتناب نهيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص319–320، تحت عنوان «الكناية والمشاكلة والمجاز في قوله: ﴿بقوم يحبهم ويحبونه﴾»","url":""}]},{"id":"s5-305","number":305,"surah":5,"verses":[54],"references":[{"surah":5,"verses":[54]}],"verseLabel":"المائدة: 54","question":"ما دلالة المقابلة في قوله تعالى: ﴿أذلة على المؤمنين أعزة على الكافرين﴾؟","answer":"قابل بين لين الجانب والتواضع للمؤمنين وبين الشدة والامتناع عن الخضوع للكافرين؛ وهما وصفان متقابلان يجتمعان لاختلاف متعلقهما. فالذلة هنا تواضع ورحمة، وليست مهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص321–322، تحت «بلاغة المقابلة والمجاز في قوله أذلة على المؤمنين أعزة على الكافرين»","url":""}]},{"id":"s5-306","number":306,"surah":5,"verses":[54],"references":[{"surah":5,"verses":[54]}],"verseLabel":"المائدة: 54","question":"ما مناسبة ذكر الجهاد قبل قوله تعالى: ﴿ولا يخافون لومة لائم﴾؟","answer":"ذُكر الجهاد ثم عدم خوف اللوم على سبيل الترقي؛ فالجهاد من أكبر دلائل صدق الإيمان، والثبات أمام لوم المجتمع أرفع، إذ يمضون في أمر الدين راسخي التوجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص323، تحت عنوان «الترقي في قوله: ﴿يحبهم ويحبونه﴾؛ ﴿أذلة على المؤمنين أعزة على الكافرين﴾؛ ﴿يجاهدون في سبيل الله﴾؛ ﴿ولا يخافون لومة لائم﴾»","url":""}]},{"id":"s5-307","number":307,"surah":5,"verses":[54],"references":[{"surah":5,"verses":[54]}],"verseLabel":"المائدة: 54","question":"ما مناسبة ختم الصفات بقوله تعالى: ﴿ذلك فضل الله يؤتيه من يشاء﴾؟","answer":"الإشارة إلى مجموع صفات الكمال السابقة، وكلها فضل من الله وإحسان وتوفيق يؤتيه من يشاء ممن يعلم أهليته له","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص324، تحت «بلاغة التذييل في قوله ذلك فضل الله يؤتيه من يشاء والله واسع عليم»","url":""}]},{"id":"s5-308","number":308,"surah":5,"verses":[55],"references":[{"surah":5,"verses":[55]}],"verseLabel":"المائدة: 55","question":"ما دلالة القصر في قوله تعالى: ﴿إنما وليكم الله ورسوله والذين آمنوا﴾؟","answer":"بعد النهي عن ولاية من يعادون جماعة المؤمنين، حصر السياق ولاية النصرة والانتماء في الله ورسوله والمؤمنين؛ فحدد مركز ولاء الجماعة الذي تستمد منه هويتها وقوتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص326–327، تحت «بلاغة أسلوب القصر في قوله إنما وليكم الله ورسوله والذين آمنوا»","url":""}]},{"id":"s5-309","number":309,"surah":5,"verses":[55],"references":[{"surah":5,"verses":[55]}],"verseLabel":"المائدة: 55","question":"ما سرّ إفراد ﴿وليكم﴾ مع تعدد المذكورين بعده؟","answer":"أفرد ﴿وليكم﴾ لأنه اسم جنس، وللدلالة على أن أصل الولاية لله، ثم ولاية الرسول والمؤمنين تابعة لها","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص328، تحت «وليكم وأولياؤكم»","url":""}]},{"id":"s5-310","number":310,"surah":5,"verses":[55],"references":[{"surah":5,"verses":[55]}],"verseLabel":"المائدة: 55","question":"ما دلالة وصف المؤمنين بقوله تعالى: ﴿يؤتون الزكاة وهم راكعون﴾؟","answer":"الجملة حالية، والركوع كناية عن الخشوع والتواضع لله، ولا سيما عند إيتاء الزكاة لما في العطاء من داعي الاستعلاء؛ فجمعت إقامة الصلاة وإيتاء الزكاة والخضوع","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص327–328، تحت «بلاغة الكناية في قوله وهم راكعون»","url":""}]},{"id":"s5-311","number":311,"surah":5,"verses":[56],"references":[{"surah":5,"verses":[56]}],"verseLabel":"المائدة: 56","question":"ما دلالة التعبير بالمضارع في قوله تعالى: ﴿ومن يتول الله ورسوله والذين آمنوا﴾؟","answer":"يدل المضارع على تجدد هذه الولاية واستمرارها، حتى لا يطول العهد فتفتر القلوب وتنحرف الولاءات؛ ففيه حث على دوام التمسك بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص330، تحت عنوان «دلالة جملة الشرط في قوله: ﴿ومن يتول الله﴾»","url":""}]},{"id":"s5-312","number":312,"surah":5,"verses":[56],"references":[{"surah":5,"verses":[56]}],"verseLabel":"المائدة: 56","question":"ما سرّ إظهار اسم الله في قوله تعالى: ﴿حزب الله﴾ بدل الإضمار؟","answer":"في إضافة «حزب» إلى الاسم الظاهر «الله» تشريف لهم، وتقرير أن من نصرهم الله لا يغلبهم أحد؛ كما يجعل التعبير بالحزب مثلًا لجماعة المؤمنين في كل زمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص330–331، تحت «وضع الظاهر موضع المضمر في قوله: ومن يتول الله ورسوله، وقوله: فإن حزب الله»","url":""}]},{"id":"s5-313","number":313,"surah":5,"verses":[56],"references":[{"surah":5,"verses":[56]}],"verseLabel":"المائدة: 56","question":"ما دلالة قوله ﴿فإن حزب الله هم الغالبون﴾ في جواب الشرط؟","answer":"الجملة دليل على جواب شرط محذوف، والتقدير: من يتول الله ورسوله والذين آمنوا فهو من حزب الله، وحزب الله هم الغالبون. ففي حذف الجواب إيجاز، وإضافة الحزب إلى الله تعليل للغلبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص330–331، تحت «وضع الظاهر موضع المضمر في قوله: ومن يتول الله ورسوله، وقوله: فإن حزب الله»","url":""}]},{"id":"s5-314","number":314,"surah":5,"verses":[57],"references":[{"surah":5,"verses":[57]}],"verseLabel":"المائدة: 57","question":"ما مناسبة الجمع في النهي بين المستهزئين بالدين من أهل الكتاب والكفار؟","answer":"جمعهم اشتراكهم في اتخاذ الدين هزوًا ولعبًا وإن اختلفت أسماؤهم ومعتقداتهم؛ فهذا الموقف يجعل ولايتهم خطرًا على حرمة الدين وجماعة المؤمنين، فدار النهي مع الوصف الجامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص332–333، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-315","number":315,"surah":5,"verses":[57],"references":[{"surah":5,"verses":[57]}],"verseLabel":"المائدة: 57","question":"ما أثر وصف معاملتهم للدين بأنها ﴿هزوًا ولعبًا﴾؟","answer":"يجمع الوصف بين الاستخفاف بالدين والاسترسال في العبث بأمره، وهو أشد من مجرد عدم الإيمان به؛ لذلك جاء تعليلًا للتحذير من موالاتهم، لما يتضمنه من امتهان الدين وانتهاك حرمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص334–335، تحت «دلالة قوله هزوًا ولعبًا»","url":""}]},{"id":"s5-316","number":316,"surah":5,"verses":[57],"references":[{"surah":5,"verses":[57]}],"verseLabel":"المائدة: 57","question":"ما دلالة قوله تعالى: ﴿واتقوا الله إن كنتم مؤمنين﴾ بعد النهي عن تلك الولاية؟","answer":"الشرط يهيج الإيمان الكامن في المخاطبين: إن كان إيمانكم صادقًا فثمرته تقوى الله وامتثال نهيه عن ولاية المستهزئين بدينه. فليس المعنى الشك في كل مخاطب، بل إلزام الإيمان بمقتضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص335–336، تحت «بلاغة تذييل الآية بقوله واتقوا الله إن كنتم مؤمنين»","url":""}]},{"id":"s5-317","number":317,"surah":5,"verses":[58],"references":[{"surah":5,"verses":[58]}],"verseLabel":"المائدة: 58","question":"ما دلالة قوله تعالى: ﴿وإذا ناديتم إلى الصلاة اتخذوها هزوًا ولعبًا﴾؟","answer":"الضمير في ﴿اتخذوها﴾ يعود إلى الصلاة أو إلى المناداة المفهومة من ﴿ناديتم﴾؛ وفي الحالين تجاوز استهزاؤهم المؤذن إلى الشعيرة التي يدعو إليها، فكشف التعبير أن موضع سخريتهم هو عبادة المؤمنين نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص339، تحت «مرجع الضمير»","url":""}]},{"id":"s5-318","number":318,"surah":5,"verses":[58],"references":[{"surah":5,"verses":[58]}],"verseLabel":"المائدة: 58","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿ذلك بأنهم قوم لا يعقلون﴾ دون: لا يعلمون؟","answer":"لأن الاستهزاء بالصلاة والنداء إليها فعل سفيه لا يصدر عن تعقل؛ فناسب السياق نفي العقل، لا مجرد نفي العلم. واختيار الخاتمة مرتبط بالفعل الذي وصفته الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص341، تحت عنوان «في نفي العقل ونفي العلم»","url":""}]},{"id":"s5-319","number":319,"surah":5,"verses":[59],"references":[{"surah":5,"verses":[59]}],"verseLabel":"المائدة: 59","question":"ما دلالة قوله تعالى: ﴿هل تنقمون منا إلا أن آمنا بالله﴾، فجعل الإيمان محل نقمتهم؟","answer":"جاء الاستثناء بعد نفي ما يستوجب النقمة، فيوهم أولًا أن بعده عيبًا، ثم يذكر الإيمان بالله والكتب المنزلة، وهو مما يمدح به ولا يعاب. فهذا تأكيد للمدح بما يشبه الذم، ينبه الناقم إلى فساد نقمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص345–346، تحت عنوان «المدح بما يشبه الذم»","url":""}]},{"id":"s5-320","number":320,"surah":5,"verses":[59],"references":[{"surah":5,"verses":[59]}],"verseLabel":"المائدة: 59","question":"لماذا حُكي الإيمان بصيغة المتكلمين في قوله تعالى: ﴿آمنا بالله وما أنزل إلينا﴾؟","answer":"لأن النبي ﷺ يتكلم ومعه المؤمنون؛ فالذي نقمه المخاطبون هو إيمان المسلمين جميعًا، وقد اشتركوا في هذا الإيمان، فناسبت حكايتَه صيغةُ الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص344، تحت عنوان «السر بحكاية القول بصيغة المتكلمين»","url":""}]},{"id":"s5-321","number":321,"surah":5,"verses":[59],"references":[{"surah":5,"verses":[59]}],"verseLabel":"المائدة: 59","question":"ما دلالة عطف ﴿وأن أكثركم فاسقون﴾ على ﴿أن آمنا﴾؟","answer":"من توجيهات العطف أنهم لا ينقمون إيمان المسلمين منفردًا، بل اجتماع إيمان المسلمين مع تمرد المخاطبين وخروجهم عن الإيمان؛ فكأن المعنى: لا تنقمون منا إلا أننا مؤمنون وأنتم فاسقون.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص346، تحت عنوان «دلالة العطف»","url":""}]},{"id":"s5-665","number":665,"surah":5,"verses":[59],"references":[{"surah":5,"verses":[59]}],"verseLabel":"المائدة: 59","question":"لماذا قيل ﴿وأن أكثركم فاسقون﴾ ولم يعمم الوصف على جميعهم؟","answer":"لأن قليلًا منهم آمن واهتدى؛ فذِكر الأكثر يدفع توهم دخول هؤلاء المؤمنين في وصف الفسق، ويقصره على من استحقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص346–347، تحت عنوان «العلة من ذكر صفة الأكثر دون الجميع»","url":""}]},{"id":"s5-322","number":322,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"ما مناسبة الاستفهام بـ﴿هل﴾ في قوله تعالى: ﴿هل أنبئكم بشر من ذلك مثوبة عند الله﴾؟","answer":"جاء السياق بعد الحديث عن الإيمان والفسق، وفي المفاضلة بين طريقين ومنهجين؛ فناسبته هل الداعية إلى التصديق عن تفكر ونظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص357، تحت عنوان «التشابه اللفظي: الاستفهام بـ(هل) وبـ(أ)»","url":""}]},{"id":"s5-666","number":666,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"لماذا جاء الخبر بصيغة ﴿هل أنبئكم بشر من ذلك﴾ بدل الإخبار المباشر؟","answer":"الاستفهام يوقظ انتباه المخاطبين ويستجلب سماعهم؛ لأن الإنسان يتشوق إلى معرفة ما يجهله، فإذا جاء الخبر بعد السؤال تلقاه بحضور وإدراك أكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص350، تحت عنوان «الفرق بين الخطاب بالاستفهام دون الإخبار المباشر»","url":""}]},{"id":"s5-323","number":323,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"ما سرّ تسمية العقوبة ﴿مثوبة﴾ في قوله تعالى: ﴿بشر من ذلك مثوبة عند الله﴾؟","answer":"عُبّر عن جزاء العقوبة بلفظ المثوبة على سبيل التهكم؛ فالمثوبة جارية على ما ينتظر من جزاء حسن، ثم جاء بيان اللعن والغضب دالًا على أن المراد هنا العذاب، فاشتد التقريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص352، تحت «الاستعارة التهكمية بالتعبير عن الإساءة بالمثوبة»","url":""}]},{"id":"s5-324","number":324,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"لماذا ذُكرت عبادة الطاغوت بعد العقوبات في قوله تعالى: ﴿وعبد الطاغوت﴾؟","answer":"لأنها عقوبة أخرى تمثلت في خذلانهم عن الهدى بسبب تمردهم وكثرة معاصيهم؛ فخُلّوا لأنفسهم ولم يوفقوا للإيمان، فضلوا وعبدوا الطاغوت. فناسب ذكرها في سياق العقوبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص354–355، تحت عنوان «دلالة الإخبار بعبادتهم الطاغوت بعد العقوبات المذكورة»","url":""}]},{"id":"s5-325","number":325,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"ما فائدة ﴿منهم﴾ في قوله تعالى: ﴿وجعل منهم القردة والخنازير﴾؟","answer":"تفيد من التبعيض، فتدل على أن المسخ نال بعضهم لا جميعهم؛ وقد خص المصدر ذلك بأصحاب السبت.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص354، تحت عنوان «فائدة التبعيض في دلالة (من)»","url":""}]},{"id":"s5-326","number":326,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"ما الحكمة من اسم الإشارة ﴿أولئك﴾ في قوله تعالى: ﴿أولئك شر مكانًا﴾؟","answer":"يستحضر اسم الإشارة الصفات التي ذكرت قبلها، وينبه إلى أنها سبب سوء منزلتهم؛ ولو عُبر عنهم بالضمير لم يستحضر تلك الصفات بهذا الوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص355–356، تحت عنوان «الحكمة من تعريف المسند إليه بالإشارة»","url":""}]},{"id":"s5-667","number":667,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"لماذا نُسب الشر إلى المكان في قوله تعالى: ﴿شر مكانًا﴾؟","answer":"المكان في الأصل لا يوصف بالشر من جهة نفسه، وإنما الشر لأهله؛ فنسبته إلى المكان كناية عن سوء حال من حل فيه، ومبالغة في وصف حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص356، تحت عنوان «الكناية بنسبة الشر إلى المكان»","url":""}]},{"id":"s5-668","number":668,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"هل يفيد ﴿شر مكانًا وأضل عن سواء السبيل﴾ مشاركة المؤمنين لهم في الشر والضلال؟","answer":"لا؛ اسم التفضيل هنا لزيادة المعنى والمبالغة في شر حالهم وضلالهم، لا لإثبات مشاركة طرف آخر لهم في هاتين الصفتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص356، تحت عنوان «دلالة اسم التفضيل على زيادة المعنى دون المشاركة»","url":""}]},{"id":"s5-327","number":327,"surah":5,"verses":[61],"references":[{"surah":5,"verses":[61]}],"verseLabel":"المائدة: 61","question":"ما دلالة الباء في قوله تعالى: ﴿وقد دخلوا بالكفر وهم قد خرجوا به﴾؟","answer":"تفيد الإلصاق، فتصور الكفر باقيًا معهم متلبسًا بهم في حالتي الدخول والخروج، من غير نقصان ولا تغير؛ كأنه شيء ملازم لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص361، تحت عنوان «فائدة الإلصاق المدلول عليه بالباء»","url":""}]},{"id":"s5-328","number":328,"surah":5,"verses":[61],"references":[{"surah":5,"verses":[61]}],"verseLabel":"المائدة: 61","question":"ما دلالة تكرار ﴿قد﴾ مع الدخول والخروج؟","answer":"دخلت ﴿قد﴾ على فعلي الدخول والخروج الماضيين لتصح مجيء الجملتين حالًا، وأفادت التوقع والتأكيد؛ فدل السياق على ظهور أمارات النفاق عليهم وثبوت تلبسهم بالكفر في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص360–361، تحت «دلالة قد»","url":""}]},{"id":"s5-329","number":329,"surah":5,"verses":[61],"references":[{"surah":5,"verses":[61]}],"verseLabel":"المائدة: 61","question":"ما دلالة الجمع بين دخولهم بالكفر وخروجهم به؟","answer":"ذكر الطرفين يحيط بالمجلس كله، ويثبت أن حالهم لم تتغير بسماعهم: ابتدؤوه بالكفر وختموه به. كما تكشف المقابلة كذب قولهم عند المجيء: ﴿آمنا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص362، تحت عنوان «الحكمة من الإخبار عن كفرهم في حالتي الدخول والخروج»","url":""}]},{"id":"s5-330","number":330,"surah":5,"verses":[61],"references":[{"surah":5,"verses":[61]}],"verseLabel":"المائدة: 61","question":"ما الذي كانوا يكتمونه في قوله ﴿والله أعلم بما كانوا يكتمون﴾؟","answer":"كانوا يضمرون الكفر في صدورهم مع إظهار الإيمان بألسنتهم، والله أعلم بسرائرهم","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص362، تحت عنوان «فائدة الإخبار بعلم الله تعالى بعد بيان كفرهم ونفاقهم»","url":""}]},{"id":"s5-331","number":331,"surah":5,"verses":[61],"references":[{"surah":3,"verses":[167]},{"surah":5,"verses":[61]}],"verseLabel":"آل عمران: 167؛ المائدة: 61","question":"ما دلالة زيادة ﴿كانوا﴾ في قوله تعالى في المائدة: ﴿والله أعلم بما كانوا يكتمون﴾، وعدم ذكرها في نظيره بآل عمران؟","answer":"يربط الموضع المقارن الفرق بدرجة رسوخ النفاق: فالمذكورون في آل عمران وُصفوا بأنهم يومئذ أقرب إلى الكفر، أما المذكورون في المائدة فقد غرقوا فيه، ودل عليه دخولهم وخروجهم بالكفر. فناسب المائدة «كانوا يكتمون» الدالة على استقرار الكتمان واستمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص295، تحت عنوان «توجيه التشابه اللفظي»","url":""}]},{"id":"s5-332","number":332,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"ما دلالة الإخبار عن رؤية مسارعتهم في قوله تعالى: ﴿وترى كثيرًا منهم يسارعون في الإثم﴾؟","answer":"الإخبار برؤية مسارعتهم يدل على أن انهماكهم في الإثم ظاهر مشهود لا يخفى على أحد؛ فلم تكن معاصيهم أمرًا مستترًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص367، تحت عنوان «الغرض من الإخبار عن رؤيتهم مسارعين في ذلك»","url":""}]},{"id":"s5-669","number":669,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"لماذا قُيدت الرؤية بـ﴿كثيرًا منهم﴾ في قوله تعالى: ﴿وترى كثيرًا منهم يسارعون في الإثم﴾؟","answer":"لأن بعضهم لم يكن مسارعًا في تلك المعاصي؛ فجاء التقييد منصفًا دقيقًا، فلم يعمم الذم على الجميع في مقام يقتضي التخصيص.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص367، تحت عنوان «الغرض من تقييد الرؤية بالكثرة»","url":""}]},{"id":"s5-670","number":670,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"لماذا عُبر بالمسارعة دون العجلة في قوله تعالى: ﴿يسارعون في الإثم﴾؟","answer":"مع أن المسارعة أكثر استعمالًا في الخير، صُوّرت بها مبادرتهم إلى الآثام كأنهم محقون فيها، وكأنها عندهم من الطاعات؛ فتكشف الصورة فساد موقفهم من تلك المعاصي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص367، تحت عنوان «إيثار التعبير بالمسارعة دون العجلة»","url":""}]},{"id":"s5-671","number":671,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"ما فائدة الجمع بين ﴿الإثم والعدوان﴾ في وصف مسارعتهم؟","answer":"جمعهما ليشمل معاصيهم في حق الله وتعديهم على حقوق الناس، ويظهر كثرتها وشمولها؛ فالإثم أعم، والعدوان خاص بالظلم والتعدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص367–368، تحت عنوان «الجمع بين الإثم والعدوان»","url":""}]},{"id":"s5-333","number":333,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"لماذا خُص العدوان وأكل السحت بالذكر مع دخولهما في الإثم؟","answer":"لأن لفظ الإثم يتناول المعاصي جميعًا، فخُص العدوان وأكل السحت بعده للدلالة على أنهما من أعظمها، وللمبالغة في بيان خطرهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص368، تحت عنوان «علة تخصيص العدوان والسحت بالذكر وهما مضمنان في الإثم»","url":""}]},{"id":"s5-672","number":672,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"ما الحكمة من ترتيب ﴿الإثم والعدوان وأكلهم السحت﴾؟","answer":"رُتبت من الأعم إلى الأخص: الإثم أعم من العدوان، والعدوان أعم من أكل السحت؛ فكل أكل للسحت إثم وعدوان، وليس كل إثم عدوانًا ولا كل عدوان أكلًا للسحت.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص368، تحت عنوان «الحكمة في ترتيب المذكورات من معاصيهم»","url":""}]},{"id":"s5-334","number":334,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"ما فائدة اللام في قوله تعالى: ﴿لبئس ما كانوا يعملون﴾؟","answer":"اللام موطئة للقسم، والتقدير: والله لبئس ما كانوا يعملون. والتوكيد هنا للمبالغة في قبح أعمالهم وعظم إساءتهم، مع أن سوءها ظاهر لا يحتاج إلى توكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص368، تحت عنوان «فائدة التعبير باللام»","url":""}]},{"id":"s5-673","number":673,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"ما دلالة الجمع بين الماضي والمضارع في ﴿كانوا يعملون﴾؟","answer":"يدل على أنهم فعلوا تلك الأعمال السيئة من قبل، وأنهم مستمرون عليها؛ وفيه إشارة إلى إصرارهم، فلا يصورها فعلًا عارضًا انقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص368، تحت عنوان «فائدة الجمع بين الفعل الماضي والمضارع»","url":""}]},{"id":"s5-335","number":335,"surah":5,"verses":[63],"references":[{"surah":5,"verses":[63]}],"verseLabel":"المائدة: 63","question":"ما دلالة ﴿لولا﴾ في قوله تعالى: ﴿لولا ينهاهم الربانيون والأحبار﴾؟","answer":"دخلت لولا على المضارع فأفادت التحضيض، أي: هلا ينهاهم علماؤهم؟ وتضمن التحضيض هنا توبيخهم على السكوت عن نهي العامة عن تلك المعاصي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص371، تحت عنوان «فائدة دلالة (لولا) التحضيض»","url":""}]},{"id":"s5-674","number":674,"surah":5,"verses":[63],"references":[{"surah":5,"verses":[63]}],"verseLabel":"المائدة: 63","question":"لماذا خُص الربانيون والأحبار بالذكر في ﴿لولا ينهاهم الربانيون والأحبار﴾؟","answer":"لأن النهي عن المنكر ألزم في حقهم؛ فتوبيخهم على تركه يبين أن سكوتهم جعلهم مشاركين للعامة في إثم تلك المعاصي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص371، تحت عنوان «العلة بتخصيص الأحبار والرهبان بالذكر»","url":""}]},{"id":"s5-336","number":336,"surah":5,"verses":[63],"references":[{"surah":5,"verses":[63]}],"verseLabel":"المائدة: 63","question":"ما سر تخصيص الإثم بالقول في ﴿عن قولهم الإثم﴾ بعد إطلاقه في الآية السابقة؟","answer":"أُطلق الإثم في ﴿يسارعون في الإثم﴾، ثم خُص النهي عن قوله هنا بالذكر؛ للإيذان بأن قول الكذب وافتراءه من أفحش الإثم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص371، تحت عنوان «إطلاق الإثم وتخصيصه بالقول»","url":""}]},{"id":"s5-675","number":675,"surah":5,"verses":[63],"references":[{"surah":5,"verses":[63]}],"verseLabel":"المائدة: 63","question":"لماذا جاء ﴿عن قولهم الإثم﴾ عامًا ولم يُخص قول واحد من أقوالهم؟","answer":"ليشمل جميع أقوالهم المنكرة في حق الله والنبي والمؤمنين، وما اتخذوه هزوًا ولعبًا من شرائع الإسلام؛ فلا ينحصر التوبيخ في مقالة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص372، تحت عنوان «خصوص مقولهم وعمومه»","url":""}]},{"id":"s5-337","number":337,"surah":5,"verses":[62,63],"references":[{"surah":5,"verses":[62,63]}],"verseLabel":"المائدة: 62–63","question":"ما الفرق بين ختم فعل العامة بقوله تعالى: ﴿لبئس ما كانوا يعملون﴾، وختم تقصير العلماء بقوله: ﴿لبئس ما كانوا يصنعون﴾؟","answer":"الصنع أخص من العمل، إذ يقتضي العلم بالفعل وإحكامه؛ فناسب العلماء الذين يعلمون أن تقصيرهم يخالف تعاليم دينهم. وفي وصف تقصيرهم بالصنع مبالغة في سوء فعلهم وبيان أن جرمهم أكبر لمخالفتهم علمهم، بينما جاء في عامة مرتكبي الآثام لفظ العمل الأعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص374، تحت عنوان «(صنع) و(عمل)»","url":""}]},{"id":"s5-338","number":338,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما الصورة البلاغية في التعبير عن البخل والجود بقبض اليد وبسطها في آية ﴿وقالت اليهود يد الله مغلولة﴾؟","answer":"توضح الموسوعة أن المعنيين المجردين، البخل والجود، صُورا بصورة حسية تلازمهما غالبًا: غل اليد للإمساك، وبسطها للعطاء. والصورة الحسية أثبت في الذهن من المعنى المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص380، تحت عنوان «فائدة التعبير عن البخل والجود بقبض اليد وبسطها»","url":""}]},{"id":"s5-339","number":339,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"كيف جاء الرد بقوله تعالى: ﴿غلت أيديهم﴾ من جنس مقالتهم؟","answer":"لما عبروا بغل اليد عن البخل في مقالتهم، جاء الرد من لفظهم نفسه دعاءً عليهم بالبخل والنكد. وقيل: المراد غل حقيقي، فيؤسرون في الدنيا ويعذبون بالأغلال في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص378، تحت عنوان «الدعاء بغل أيديهم»","url":""}]},{"id":"s5-676","number":676,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما جمال الجناس بين ﴿مغلولة﴾ و﴿غلت﴾ في آية ﴿وقالت اليهود يد الله مغلولة غلت أيديهم﴾؟","answer":"اللفظان من جذر واحد، فبينهما جناس اشتقاقي يجمع الجمال اللفظي والفائدة المعنوية؛ إذ ينبه السامع إلى رد الغل على قائليه، وأنهم أحق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص379، تحت عنوان «جمال الجناس الاشتقاقي»","url":""}]},{"id":"s5-340","number":340,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما دلالة التثنية في قوله تعالى: ﴿بل يداه مبسوطتان﴾؟","answer":"جاءت التثنية ردًا على مقالتهم المفردة ومبالغة في إبطالها، وهي أبلغ في إثبات غاية السخاء ونفي البخل، فعبّرت عن كثرة الجود والإنعام وسعة الإنفاق","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص380، تحت «إيثار تثنية اليد على إفرادها»","url":""}]},{"id":"s5-341","number":341,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما مناسبة قوله تعالى: ﴿ينفق كيف يشاء﴾ بعد قوله: ﴿بل يداه مبسوطتان﴾؟","answer":"أثبت بسط الجود ثم بيّن أن العطاء والمنع يجريان وفق مشيئته وحكمته، لا لعجز ولا لبخل؛ فليس تفاوت الأرزاق دليلًا على ضيق خزائنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص381، تحت عنوان «فائدة تقييد الإنفاق بعد إطلاقه»","url":""}]},{"id":"s5-342","number":342,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"كيف نفهم قوله تعالى: ﴿وليزيدن كثيرًا منهم ما أنزل إليك من ربك طغيانًا وكفرًا﴾ مع أن الوحي هدى؟","answer":"تبين الموسوعة أن الزيادة تكون في شدة الكفر أو كثرته؛ فكلما نزلت آية أو حجة جددوا الكفر بها. وليس الإخبار بأن النزول نفسه سبب ذلك، بل بأن إصرارهم على الكفر يتجدد مع نزول القرآن، فيزدادون به طغيانًا وكفرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص382، تحت عنوان «كيفية زيادة كفرهم»","url":""}]},{"id":"s5-343","number":343,"surah":5,"verses":[14,64],"references":[{"surah":5,"verses":[14,64]}],"verseLabel":"المائدة: 14، 64","question":"ما الفرق بين قوله تعالى: ﴿فأغرينا بينهم العداوة والبغضاء﴾ وقوله: ﴿وألقينا بينهم العداوة والبغضاء﴾؟","answer":"تعلل الموسوعة اختيار الإغراء مع النصارى بأنه أدل على شدة التصاق العداوة والبغضاء بهم؛ إذ تصف تفرقهم بأنه تضاعف بما أدخلوه من التحريف على ما سبق من تحريف التوراة. فجاء الإغراء مناسبًا لهذه الشدة، والإلقاء في الموضع الآخر مع اليهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص703، تحت عنوان «بلاغة توجيه التشابه اللفظي في استعمال كلمة الإغراء مع النصارى والإلقاء مع اليهود»","url":""}]},{"id":"s5-344","number":344,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما الصورة في قوله تعالى: ﴿أوقدوا نارًا للحرب﴾؟","answer":"استعير إيقاد النار لجمعهم وإعدادهم للحرب وإهاجة الشر؛ فكما يجمع موقد النار الحطب ويهيئه، يحشد مريد الحرب الناس ويهيئ السلاح، والجامع بين الصورتين الإعداد والتهيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص385–386، تحت عنوان «استعارة إيقاد النار للشر»","url":""}]},{"id":"s5-677","number":677,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما الصورة في قوله تعالى: ﴿أطفأها الله﴾ بعد ﴿أوقدوا نارًا للحرب﴾؟","answer":"استعير إطفاء النار لخذلانهم وفض جموعهم وتشتتهم وانحلال عزمهم؛ فكما ينطفئ ما أوقد، تبطل فائدة جمعهم ولا يبلغون غرضهم من الحرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص386، تحت عنوان «استعارة إطفاء النار لفض الجموع وانحلال عزمهم»","url":""}]},{"id":"s5-678","number":678,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما دلالة ﴿كلما﴾ في قوله تعالى: ﴿كلما أوقدوا نارًا للحرب أطفأها الله﴾؟","answer":"تفيد تكرر إحباط محاولاتهم: كلما جمعوا وأعدوا شتت الله جمعهم. وفيها أيضًا تصوير لتكرر إصرارهم على إثارة الحروب والتحريش بين الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص385، تحت عنوان «الدلالة على الظرفية والتكرار في (كلما)»","url":""}]},{"id":"s5-345","number":345,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما مناسبة قوله تعالى: ﴿ويسعون في الأرض فسادًا﴾ بعد ذكر إيقاد الحرب؟","answer":"يبين أنهم بعد خذلانهم في إثارة الحروب لم يتركوا البغي؛ فاستعاضوا عنها بخداع الضعفاء والمكر والكيد خفية، فاستمر سعيهم إلى الإفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص387، تحت عنوان «دلالة ذكر سعيهم بالإفساد بعد ذكر الحرب»","url":""}]},{"id":"s5-679","number":679,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"لماذا قيل ﴿ويسعون في الأرض فسادًا﴾ ولم يقل: ويفسدون في الأرض؟","answer":"التعبير بالسعي يدل على أن الإفساد مقصد يجتهدون فيه بحرص، وليس فعلًا عارضًا أو مجرد معصية وقع بها فساد؛ فهم يتعمدونه ويسعون إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص387، تحت عنوان «التعبير بالسعي دون الإفساد المباشر»","url":""}]},{"id":"s5-346","number":346,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما دلالة نفي المحبة في قوله تعالى: ﴿والله لا يحب المفسدين﴾؟","answer":"يتضمن نفي لوازم المحبة وآثارها عنهم، فلا يظهر عليهم ما يشعر بها؛ وفيه وعيد بأن يجازيهم على إفسادهم ويعاقبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص388، تحت عنوان «دلالة نفي المحبة عن المفسدين»","url":""}]},{"id":"s5-680","number":680,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"لماذا قيل ﴿والله لا يحب المفسدين﴾ ولم يُكتف بضميرهم؟","answer":"إظهار وصف المفسدين يبين شدة فسادهم واتصافهم به، ويكشف علة انتفاء المحبة: وهي ما ارتكبوه من الإفساد، لا ذواتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص388، تحت عنوان «وضع الظاهر موضع المضمر»","url":""}]},{"id":"s5-348","number":348,"surah":5,"verses":[65],"references":[{"surah":5,"verses":[65]}],"verseLabel":"المائدة: 65","question":"ما سرّ تقديم تكفير السيئات على إدخال جنات النعيم؟","answer":"تكفير السيئات إزالة لما يمنع النجاة، وإدخال الجنة تحصيل للنعيم؛ فقدم التطهير من الذنب والعقوبة على التحلية بالثواب، على ترتيب التخلية ثم التحلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص391–392، تحت «دلالة قرن تكفير السيئات بإدخال الجنة»","url":""}]},{"id":"s5-349","number":349,"surah":5,"verses":[65],"references":[{"surah":5,"verses":[65]}],"verseLabel":"المائدة: 65","question":"ما دلالة التعبير بقوله تعالى: ﴿جنات النعيم﴾؟","answer":"أضيفت الجنات إلى النعيم للدلالة على ما أُعد للمؤمن المتقي من النعيم، وفي الإضافة مقابلة ضمنية: من آمن واتقى فله جنات النعيم، ومن لم يؤمن ويتق فله عذاب الجحيم","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص393–394، تحت «دلالة إضافة الجنات إلى النعيم»","url":""}]},{"id":"s5-350","number":350,"surah":5,"verses":[66],"references":[{"surah":5,"verses":[66]}],"verseLabel":"المائدة: 66","question":"ما معنى إقامة الكتاب في قوله تعالى: ﴿ولو أنهم أقاموا التوراة والإنجيل﴾؟","answer":"إقامة الكتاب إظهار أحكامه والعمل بما فيه حتى تكون قائمة في حياة أهله؛ وشُبه إظهار أحكام التوراة والإنجيل بإقامة شخص يبرز أثره. فهي أوسع من مجرد تداول ألفاظ الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص396، تحت «الاستعارة في أقاموا التوراة والإنجيل»","url":""}]},{"id":"s5-351","number":351,"surah":5,"verses":[66],"references":[{"surah":5,"verses":[66]}],"verseLabel":"المائدة: 66","question":"ما دلالة ﴿إليهم﴾ في قوله تعالى: ﴿وما أنزل إليهم﴾ بعد ذكر التوراة والإنجيل؟","answer":"على تفسير المنزل بالقرآن، يبين هذا القيد أن أهل الكتاب مخاطبون به، فتجب عليهم إقامته والعمل به حين يصل إليهم؛ وفيه رد دعوى اختصاص القرآن بالعرب وعدم تعلق أحكامه بغيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص396، تحت عنوان «دلالة الجار والمجرور في: ﴿وما أنزل إليهم﴾»","url":""}]},{"id":"s5-681","number":681,"surah":5,"verses":[66],"references":[{"surah":5,"verses":[66]}],"verseLabel":"المائدة: 66","question":"ما دلالة إضافة الرب إلى ضميرهم في قوله تعالى: ﴿من ربهم﴾؟","answer":"في التعبير بالرب وإضافته إليهم مزيد تلطف في دعوتهم؛ لما في الربوبية من معاني الإحسان، ولما تفيده الإضافة من تشريف المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص397، تحت عنوان «دلالة الإضافة في: ﴿ربهم﴾»","url":""}]},{"id":"s5-352","number":352,"surah":5,"verses":[66],"references":[{"surah":5,"verses":[66]}],"verseLabel":"المائدة: 66","question":"كيف فُسرت جهتا الرزق في قوله تعالى: ﴿لأكلوا من فوقهم ومن تحت أرجلهم﴾؟","answer":"من توجيهات الآية أن فوقهم يشير إلى المطر، وتحت أرجلهم إلى الزروع والثمار؛ لأن السماء والأرض مصدر ما ينتفعون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص398، تحت عنوان «دلالة تخصيص جهات الأكل في: ﴿من فوقهم ومن تحت أرجلهم﴾»","url":""}]},{"id":"s5-682","number":682,"surah":5,"verses":[66],"references":[{"surah":5,"verses":[66]}],"verseLabel":"المائدة: 66","question":"ما وجه الكناية في قوله تعالى: ﴿لأكلوا من فوقهم ومن تحت أرجلهم﴾؟","answer":"على وجه الكناية، المراد تعميم جهات الرزق والسعة والخصب، لا حصر الرزق في جهتين؛ أي لو أقاموا ما أنزل إليهم لساق الله إليهم رزقًا كثيرًا متصلًا من كل سبيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص399، تحت عنوان «بلاغة الكناية في: ﴿لأكلوا من فوقهم ومن تحت أرجلهم﴾»","url":""}]},{"id":"s5-353","number":353,"surah":5,"verses":[66],"references":[{"surah":5,"verses":[66]}],"verseLabel":"المائدة: 66","question":"ما دلالة تنكير ﴿أمة﴾ في قوله تعالى: ﴿منهم أمة مقتصدة وكثير منهم ساء ما يعملون﴾؟","answer":"يفيد التنكير التقليل؛ فالجماعة المعتدلة أو الداخلة في الإسلام قليلة، ولذلك قابلها بقوله ﴿وكثير منهم ساء ما يعملون﴾. فلا يعمم سوء العمل على جميع أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص401، تحت عنوان «دلالة تنكير: ﴿أمة﴾»","url":""}]},{"id":"s5-354","number":354,"surah":5,"verses":[66],"references":[{"surah":5,"verses":[66]}],"verseLabel":"المائدة: 66","question":"ما دلالة صيغة الافتعال في وصف الأمة بأنها ﴿مقتصدة﴾؟","answer":"القصد هو العدل، ومن معاني صيغة الافتعال التصرف لتحصيل الفعل. وتذكر الموسوعة أن اختيار هذه الصيغة يشير إلى أن هذه الأمة كانت جائرة، ثم اقتصدت وعدلت بعد ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص400، تحت عنوان «دلالة الافتعال في: ﴿أمة مقتصدة﴾»","url":""}]},{"id":"s5-355","number":355,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"ما دلالة نداء النبي ﷺ بصفة الرسالة في قوله تعالى: ﴿يا أيها الرسول﴾؟","answer":"في ندائه بصفة الرسالة تشريف له وتعظيم لقدره؛ إذ الرسالة من أشرف أوصاف الإنسان، وقد خُص بهذا النداء، بينما نودي غيره من الأنبياء بأسمائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص403–404، تحت عنوان «النداء في: ﴿يا أيها الرسول﴾»","url":""}]},{"id":"s5-683","number":683,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"لماذا قيل ﴿يا أيها الرسول﴾ دون: يا أيها النبي، عند الأمر بالتبليغ؟","answer":"وصف الرسالة يمهد لما بعده من الأمر؛ لأن تبليغ جميع الوحي من واجبات الرسالة، والرسول أخص من النبي بكونه مأمورًا بتبليغ ما أنزل إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص404، تحت عنوان «لم عبر بالرسول دون النبي في هذا الموضع؟»","url":""}]},{"id":"s5-684","number":684,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"ما دلالة الربوبية في ﴿بلغ ما أنزل إليك من ربك﴾؟","answer":"لفظ الرب بما يتضمنه من الإحسان والرعاية يحمل وعدًا ضمنيًا بحفظ النبي ﷺ وحمايته؛ فيطمئن إلى تبليغ الوحي دون خوف من مكروه يلحقه بسبب التبليغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص405، تحت عنوان «دلالة الربوبية والإضافة في: ﴿من ربك﴾»","url":""}]},{"id":"s5-356","number":356,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"ما دلالة قوله تعالى: ﴿وإن لم تفعل فما بلغت رسالته﴾ مع سبق تبليغ النبي ﷺ للوحي؟","answer":"المعنى أن كتمان أي جزء مما أُمر بتبليغه يخل بحقيقة أداء الرسالة كاملة؛ لأن المبلّغ لا يختار من الوحي ما يظهر وما يترك. وليس المراد نفي ما وقع من تبليغ سابق، بل بيان أن كمال المهمة لا يتجزأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص406–407، تحت «اتحاد الشرط والجزاء في وإن لم تفعل فما بلغت رسالته»","url":""}]},{"id":"s5-357","number":357,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"ما دلالة إفراد ﴿رسالته﴾ في قوله تعالى: ﴿فما بلغت رسالته﴾؟","answer":"الإفراد ينظر إلى الشرع كله بوصفه شيئًا واحدًا؛ فعقائده وأحكامه جملة يعضد بعضها بعضًا. واللفظ المفرد هنا شامل لجميع ما أنزله الله، وقد يدل اسم الواحد على الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص408، تحت عنوان «دلالة الإفراد في: ﴿رسالته﴾»","url":""}]},{"id":"s5-685","number":685,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"ما وجه قراءة ﴿رسالاته﴾ بالجمع في قوله تعالى: ﴿فما بلغت رسالته﴾؟","answer":"الجمع ينظر إلى كثرة معاني الشرع وتعدد أزمنة نزوله؛ فكل آية أنزلت على النبي ﷺ تعد، على هذه القراءة، رسالة مستقلة من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص407–408، تحت عنوان «دلالة الجمع في: ﴿رسالته﴾»","url":""}]},{"id":"s5-358","number":358,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"ما دلالة إظهار اسم الله في قوله تعالى: ﴿والله يعصمك﴾ عقب الأمر بالتبليغ؟","answer":"لفظ الجلالة متضمن لمعاني العزة والمنعة؛ فافتتاح الوعد به تطمين للنبي ﷺ واهتمام به وتثبيت لقلبه، عند تبليغ ما قد يلقى بسببه أذى ومحاولة إضرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص408، تحت عنوان «دلالة الاسم العظيم في: ﴿والله يعصمك﴾»","url":""}]},{"id":"s5-359","number":359,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله لا يهدي القوم الكافرين﴾؟","answer":"الخاتمة تعليل للعصمة: فلا يهدي الله الكافرين إلى ما يريدونه من إطفاء نور الرسالة أو إيقاع ضرر يمنع النبي ﷺ من تبليغها","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص409، تحت «دلالة وضع الظاهر موضع المضمر في إن الله لا يهدي القوم الكافرين»","url":""}]},{"id":"s5-360","number":360,"surah":5,"verses":[68],"references":[{"surah":5,"verses":[68]}],"verseLabel":"المائدة: 68","question":"ما دلالة التنكير في قوله تعالى: ﴿لستم على شيء﴾؟","answer":"يفيد التحقير والتصغير لما هم عليه من دعوى الدين مع ترك اتباع النبي ﷺ والإذعان لرسالته؛ أي ليسوا على دين يعتد به حتى يسمى شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص411، تحت عنوان «دلالة التنكير في: ﴿لستم على شيء﴾»","url":""}]},{"id":"s5-361","number":361,"surah":5,"verses":[68],"references":[{"surah":5,"verses":[68]}],"verseLabel":"المائدة: 68","question":"لماذا ذُكرت التوراة والإنجيل قبل ﴿وما أنزل إليكم من ربكم﴾؟","answer":"من توجيهات هذا التقديم تأليف أهل الكتاب بذكر كتابيهم أولًا، ثم تمهيد دعوتهم إلى إقامة القرآن المصدق لما قبله والمهيمن عليه؛ فينتقل الخطاب بهم من ضيق الشقاق إلى سعة الوفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص411–412، تحت عنوان «لم أفردت التوراة والإنجيل بالذكر قبل العموم في: ﴿وما أنزل إليكم من ربكم﴾؟»","url":""}]},{"id":"s5-362","number":362,"surah":5,"verses":[64,68],"references":[{"surah":5,"verses":[64,68]}],"verseLabel":"المائدة: 64، 68","question":"ما دلالة القسم في قوله تعالى: ﴿وليزيدن كثيرًا منهم ما أنزل إليك من ربك طغيانًا وكفرًا﴾؟","answer":"اللام موطئة للقسم، فتؤكد مضمون الخبر وتحققه؛ وفي هذا إعلام للنبي ﷺ بما سيظهر من كفر كثير من المخاطبين وعنادهم، حتى تخف عليه وطأة ذلك إذا وقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص413–414، تحت عنوان «دلالة القسم في: ﴿وليزيدن كثيرا منهم﴾ الآية»","url":""}]},{"id":"s5-363","number":363,"surah":5,"verses":[68],"references":[{"surah":5,"verses":[68]}],"verseLabel":"المائدة: 68","question":"لماذا قيل ﴿فلا تأس على القوم الكافرين﴾ بدل: فلا تأس عليهم؟","answer":"إظهار وصف الكفر ينبه إلى علة عدم التأسف عليهم، وهي كفرهم وعنادهم؛ وفيه أيضًا تسجيل لرسوخهم في الكفر حتى صار وصفًا ملازمًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص414، تحت عنوان «دلالة إقامة الظاهر مقام المضمر في: ﴿فلا تأس على القوم الكافرين﴾»","url":""}]},{"id":"s5-364","number":364,"surah":5,"verses":[69],"references":[{"surah":5,"verses":[69]}],"verseLabel":"المائدة: 69","question":"ما سرّ رفع ﴿الصابئون﴾ في قوله تعالى: ﴿إن الذين آمنوا والذين هادوا والصابئون والنصارى﴾؟","answer":"على توجيه جمهور المفسرين والمعربين، الصابئون مبتدأ وخبره محذوف، والتقدير: والصابئون كذلك؛ والجملة مقدمة لفظًا مؤخرة تقديرًا. وفي ذلك تنبيه إلى أن هذه الفرقة، مع شدة ضلالها في السياق، تقبل توبتها إن آمنت وعملت الصالحات، فغيرها أولى بقبول التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص418، تحت عنوان «دلالة كون ﴿والصابئون﴾ على نية التأخير»","url":""}]},{"id":"s5-365","number":365,"surah":5,"verses":[69],"references":[{"surah":2,"verses":[62]},{"surah":5,"verses":[69]}],"verseLabel":"البقرة: 62؛ المائدة: 69","question":"ما سرّ تقديم ﴿الصابئون﴾ على ﴿النصارى﴾ في المائدة، وتأخيرهم عنهم في البقرة؟","answer":"من توجيهات الموسوعة أن ترتيب البقرة راعى أحوال الطوائف في الدنيا، فقدم أهل الكتاب وأخر الصابئين؛ أما تقديم الصابئين في المائدة فينبه إلى أن الغاية الأخروية لا تتبع هذا الترتيب الدنيوي، وإنما يكون التفاضل فيها بالإيمان والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص536–537، تحت عنوان «سر التقديم والتأخير بين الأصناف»","url":""}]},{"id":"s5-366","number":366,"surah":5,"verses":[69],"references":[{"surah":5,"verses":[69]}],"verseLabel":"المائدة: 69","question":"ما دلالة إعادة قوله تعالى: ﴿من آمن بالله واليوم الآخر وعمل صالحًا﴾ بعد ذكر ﴿الذين آمنوا﴾؟","answer":"على توجيه من آمن بدلًا من اسم إن وما عطف عليه، تخص الإعادة الوعد بمن حقق الإيمان بالله واليوم الآخر؛ فلا يشمل الوعد من انتسب إلى الإيمان أو نطق به دون أن يؤمن قلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص419، تحت عنوان «لم جاء البدل في: ﴿من آمن بالله﴾ والمبدل منه على لفظ واحد؟»","url":""}]},{"id":"s5-367","number":367,"surah":5,"verses":[69],"references":[{"surah":5,"verses":[69]}],"verseLabel":"المائدة: 69","question":"ما دلالة الجمع بين نفي الخوف ونفي الحزن في قوله تعالى: ﴿فلا خوف عليهم ولا هم يحزنون﴾؟","answer":"جمع أمن المستقبل وذهاب الحزن على الماضي؛ فلا يخافون أهوال يوم القيامة، ولا يحزنون على ما فاتهم من طيبات الدنيا، لما يجدونه من الكرامة والتشريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص420، تحت عنوان «دلالة الجمع بين الخوف والحزن في الآية»","url":""}]},{"id":"s5-686","number":686,"surah":5,"verses":[69],"references":[{"surah":5,"verses":[69]}],"verseLabel":"المائدة: 69","question":"ما الذي تؤكده قراءة ﴿فلا خوف عليهم﴾ بفتح خوف دون تنوين؟","answer":"تنص قراءة الفتح على نفي جميع أنواع الخوف عن أهل الإيمان؛ ولذلك يبين المصدر أنها آكد في استغراق النفي من قراءة الرفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص421، تحت عنوان «دلالة الفتح في: ﴿فلا خوف عليهم﴾»","url":""}]},{"id":"s5-368","number":368,"surah":5,"verses":[69],"references":[{"surah":2,"verses":[62]},{"surah":5,"verses":[69]}],"verseLabel":"البقرة: 62؛ المائدة: 69","question":"ما سرّ ذكر ﴿فلهم أجرهم عند ربهم﴾ في البقرة، وعدم ذكره في نظيرتها من المائدة؟","answer":"صُرّح في البقرة بـ﴿فلهم أجرهم عند ربهم﴾، أما المائدة فقد سبق فيها تفصيل الأجر بقوله ﴿لكفّرنا عنهم سيئاتهم ولأدخلناهم جنات النعيم﴾؛ فكان ذكر الأجر بعدها تكرارًا ورجوعًا من التفصيل إلى الإجمال، فاكتُفي بذكره في البقرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص538، تحت «تخصيص آية البقرة بقوله تعالى فلهم أجرهم عند ربهم»","url":""}]},{"id":"s5-369","number":369,"surah":5,"verses":[12,70],"references":[{"surah":5,"verses":[12,70]}],"verseLabel":"المائدة: 12، 70","question":"ما مناسبة إعادة ذكر ميثاق بني إسرائيل بعد وروده في الآية 12؟","answer":"أعيد الميثاق بصيغة مؤكدة تفخيمًا لأمره، ثم بُيّن ما قابل به بنو إسرائيل رسلهم من التكذيب والقتل. وفي هذا تسلية للنبي ﷺ بذكر ما وقع لرسل سابقين؛ فلا يحزنه تكذيب المعاندين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص422، تحت عنوان «دلالة التأكيد في: ﴿لقد أخذنا ميثاق بني إسرائيل﴾»","url":""}]},{"id":"s5-370","number":370,"surah":5,"verses":[70],"references":[{"surah":5,"verses":[70]}],"verseLabel":"المائدة: 70","question":"ما دلالة تنكير ﴿رسلًا﴾ وجمعها في قوله تعالى: ﴿وأرسلنا إليهم رسلًا﴾؟","answer":"جمعُ ﴿رسلًا﴾ وتنكيرها يفيدان كثرتهم وتفخيم أمرهم: أي أرسلنا إليهم رسلًا ذوي عدد كثير وشأن خطير","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص423، تحت «دلالة التنكير في وأرسلنا إليهم رسلًا»","url":""}]},{"id":"s5-371","number":371,"surah":5,"verses":[70],"references":[{"surah":5,"verses":[70]}],"verseLabel":"المائدة: 70","question":"لماذا عُبر بالهوى في قوله تعالى: ﴿بما لا تهوى أنفسهم﴾؟","answer":"لأن الهوى ميل النفس إلى الشهوة، فالتعبير به بدل ما تكرهه أنفسهم أبلغ في ذمهم؛ إذ يبين أنهم قابلوا أحكام الرسل بميل النفس وشهوتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص423–424، تحت عنوان «فائدة التعبير بالهوى في: ﴿بما لا تهوى أنفسهم﴾»","url":""}]},{"id":"s5-687","number":687,"surah":5,"verses":[70],"references":[{"surah":5,"verses":[70]}],"verseLabel":"المائدة: 70","question":"ما دلالة حذف جواب الشرط في قوله تعالى: ﴿كلما جاءهم رسول﴾؟","answer":"حذف اختصارًا لدلالة السياق عليه من تكذيب الرسل وقتلهم؛ وقدره بعضهم: ناصبوه، وبعضهم: استكبروا، استنادًا إلى نظير الآية في البقرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص425، تحت عنوان «دلالة حذف جواب الشرط في: ﴿كلما جاءهم رسول﴾»","url":""}]},{"id":"s5-372","number":372,"surah":5,"verses":[70],"references":[{"surah":5,"verses":[70]}],"verseLabel":"المائدة: 70","question":"ما أثر المضارع في تصوير القتل في قوله تعالى: ﴿وفريقًا يقتلون﴾؟","answer":"يحكي المضارع الحال الماضية باستحضار صورة قتل الرسل الشنيعة كأنها تحدث وقت الخطاب؛ وفي ذلك استفظاع لها وتعجيب منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص425، تحت عنوان «بلاغة الفعل المضارع في: ﴿وفريقا يقتلون﴾»","url":""}]},{"id":"s5-688","number":688,"surah":5,"verses":[70],"references":[{"surah":5,"verses":[70]}],"verseLabel":"المائدة: 70","question":"ما دلالة عطف المضارع على الماضي في ﴿فريقًا كذبوا وفريقًا يقتلون﴾؟","answer":"يذكر المصدر أن المغايرة بين زمنَي الفعلين تدل على أن تكذيب الرسل وقتلهم كان ديدنًا لبني إسرائيل في الماضي والحاضر، فتبرز امتداد هذه الجناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص426، تحت عنوان «دلالة عطف المضارع على الماضي في: ﴿فريقا كذبوا وفريقا يقتلون﴾»","url":""}]},{"id":"s5-373","number":373,"surah":5,"verses":[71],"references":[{"surah":5,"verses":[71]}],"verseLabel":"المائدة: 71","question":"ما نكتة التعبير بـ﴿وحسبوا﴾ في قوله تعالى: ﴿وحسبوا ألا تكون فتنة﴾؟","answer":"يشعر اللفظ بظنهم الخائب، وأنهم لم يعتمدوا الأدلة الصحيحة لمعرفة الحق، ففيه توبيخ لهم. وجاء الماضي ليقرر أن هذا الحسبان وقع منهم واستقر، مع أن ما حسبوه متعلق بما يستقبلونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص429، تحت عنوان «نكتة التعبير بقوله: ﴿وحسبوا﴾»","url":""}]},{"id":"s5-374","number":374,"surah":5,"verses":[71],"references":[{"surah":5,"verses":[71]}],"verseLabel":"المائدة: 71","question":"ما الصورة في قوله تعالى: ﴿فعموا وصموا﴾؟","answer":"استعار العمى لامتناعهم عن رؤية دلائل الحق، والصمم لامتناعهم عن سماعها سماع قبول؛ فصوّر التعطيل الإرادي للبصيرة والسمع كأنه فقد للحاستين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص431–432، تحت «بلاغة الاستعارة في فعموا وصموا»","url":""}]},{"id":"s5-375","number":375,"surah":5,"verses":[71],"references":[{"surah":5,"verses":[71]}],"verseLabel":"المائدة: 71","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم تاب الله عليهم﴾؟","answer":"تفيد التراخي الزمني؛ أي إنهم تمادوا في العمى عن رؤية الهدى وأدلته، والصمم عن سماع الحق، إلى أن تاب الله عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص433، تحت عنوان «دلالة حرف العطف ﴿ثم﴾ في قوله تعالى: ﴿ثم تاب الله عليهم﴾»","url":""}]},{"id":"s5-689","number":689,"surah":5,"verses":[71],"references":[{"surah":5,"verses":[71]}],"verseLabel":"المائدة: 71","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم عموا وصموا﴾ بعد ذكر التوبة؟","answer":"من توجيهاتها الدلالة على استبعاد عودتهم إلى مزيد من العمى والصمم بعد التوبة وتكرر جناياتهم؛ ويحتمل أن تكون للتراخي الزمني، فتشير إلى حال من جاء بعد أسلافهم ورضي بفعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص433–434، تحت عنوان «دلالة حرف العطف ﴿ثم﴾ في قوله تعالى: ﴿ثم عموا وصموا﴾»","url":""}]},{"id":"s5-376","number":376,"surah":5,"verses":[71],"references":[{"surah":5,"verses":[71]}],"verseLabel":"المائدة: 71","question":"ما دلالة تقييد العمى والصمم في المرة الثانية بقوله تعالى: ﴿كثير منهم﴾؟","answer":"في أحد التوجيهات احتراز من توهم شمول العمى والصمم للجميع؛ فذِكر الكثير يثبت وقوع ذلك في الأكثر، وينصف من بقي على الحق. كما يفيد تفصيلًا بعد إجمال وتوكيدًا للحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص434–435، تحت «براعة التعبير بكثير في ثم عموا وصموا كثير منهم»","url":""}]},{"id":"s5-377","number":377,"surah":5,"verses":[71],"references":[{"surah":5,"verses":[71]}],"verseLabel":"المائدة: 71","question":"ما مناسبة قوله تعالى: ﴿والله بصير بما يعملون﴾ بعد وصفهم بالعمى والصمم؟","answer":"الخاتمة تهديد لهم؛ فالله بصير بأعمالهم وبما يظهر من آثارها. وفي وصفه بالبصر مناسبة لما سبق من عماهم، وفي عموم العمل دلالة على إحاطة علمه بما يفعلونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص435، تحت «حسن التذييل في والله بصير بما يعملون»","url":""}]},{"id":"s5-379","number":379,"surah":5,"verses":[72],"references":[{"surah":5,"verses":[72]}],"verseLabel":"المائدة: 72","question":"ما دلالة الواو الحالية في قوله تعالى: ﴿وقال المسيح يا بني إسرائيل اعبدوا الله ربي وربكم﴾؟","answer":"تبين الجملة الحالية أنهم قالوا مقالتهم مع أن المسيح يأمرهم بعبادة الله وحده؛ فتبرز تناقض قولهم مع قوله، وتجعله حجة ظاهرة على بطلان دعواهم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص439–440، تحت عنوان «دلالة الواو في قوله: ﴿وقال المسيح﴾»","url":""}]},{"id":"s5-380","number":380,"surah":5,"verses":[72],"references":[{"surah":5,"verses":[72]}],"verseLabel":"المائدة: 72","question":"ما فائدة مجيء ﴿ربي وربكم﴾ بدلًا في قوله تعالى: ﴿اعبدوا الله ربي وربكم﴾؟","answer":"يجمع البدل مع المبدل منه الإيضاح والبيان في تعيين المستحق للعبادة؛ وذكر الربوبية ينبه إلى الوصف الموجب لعبادته وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص440، تحت عنوان «نكتة مجيء البدل في قوله: ﴿اعبدوا الله ربي وربكم﴾»","url":""}]},{"id":"s5-690","number":690,"surah":5,"verses":[72],"references":[{"surah":5,"verses":[72]}],"verseLabel":"المائدة: 72","question":"ما دلالة الإضافة في قول المسيح عليه السلام: ﴿ربي وربكم﴾؟","answer":"تدل على أن الله رب له ورب لهم؛ ففيها إشعار بأن المسيح مخلوق مربوب مثل المخاطبين، مع ما أنعم الله عليه به من الرسالة والفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص440، تحت عنوان «دلالة الإضافة في قوله تعالى: ﴿ربي وربكم﴾»","url":""}]},{"id":"s5-381","number":381,"surah":5,"verses":[72],"references":[{"surah":5,"verses":[72]}],"verseLabel":"المائدة: 72","question":"ما دلالة الجمع بين قوله تعالى: ﴿حرم الله عليه الجنة﴾ وقوله: ﴿ومأواه النار﴾؟","answer":"في الجمع بين الجنة والنار طباق وتكميل للمعنى؛ فالاقتصار على تحريم الجنة يذكر حرمان الثواب دون التصريح بالعقاب، فجاء ﴿ومأواه النار﴾ ليجمع الحرمان والعذاب، زيادة في التبكيت والحسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص444، تحت عنوان «بديع الطباق وبراعة العطف في قوله: ﴿حرم الله عليه الجنة ومأواه النار﴾»","url":""}]},{"id":"s5-383","number":383,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]}],"verseLabel":"المائدة: 73","question":"ما الدلالة اللغوية لتركيب ﴿ثالث ثلاثة﴾؟","answer":"معناه واحد من الثلاثة؛ فصيغة فاعل المأخوذة من العدد والمضافة إلى العدد نفسه تدل على أنه جزء منه. أما إذا أضيفت إلى العدد الذي دونها، نحو رابع ثلاثة، دلت على الذي أكمل ذلك العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص451، تحت عنوان «دلالة التركيب في قوله: ﴿ثالث ثلاثة﴾»","url":""}]},{"id":"s5-384","number":384,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]}],"verseLabel":"المائدة: 73","question":"ما دلالة المؤكدات في قوله تعالى: ﴿وما من إله إلا إله واحد﴾؟","answer":"اجتمع النفي بـ﴿ما﴾ والحصر بـ﴿إلا﴾، وتأكد النفي بـ﴿من﴾ المفيدة للاستغراق. واختيار ما بدل لا النافية للجنس يبرز حرف من صريحًا، فيزيد العناية بتأكيد نفي التعدد وحصر الألوهية في واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص452، تحت عنوان «علة إيثار النفي بـ(ما) على (لا)»","url":""}]},{"id":"s5-385","number":385,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]}],"verseLabel":"المائدة: 73","question":"ما الكناية في التعبير عن الاعتقاد بلفظ القول في قوله تعالى: ﴿عما يقولون﴾؟","answer":"جاء القول كناية عن الاعتقاد؛ لأن القول ترجمان لما يؤمن به الإنسان، ولأن شأنه أن يصدر عن اعتقاد. فالمعنى: عما يعتقدون من مقالة التثليث.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص450، تحت عنوان «بلاغة الكناية في لفظ القول»","url":""}]},{"id":"s5-691","number":691,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]}],"verseLabel":"المائدة: 73","question":"لماذا جاء قولهم بصيغة المضارع في ﴿عما يقولون﴾؟","answer":"ناسب المضارع معنى الانتهاء؛ لأن الانتهاء يكون عن أمر مستمر، فدل على استمرارهم في تلك المقالة إلى أن يُطلب منهم الإقلاع عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص453، تحت عنوان «علة التعبير عن القول بالفعل المضارع»","url":""}]},{"id":"s5-692","number":692,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]}],"verseLabel":"المائدة: 73","question":"ما دلالة اختيار لفظ الانتهاء في قوله تعالى: ﴿وإن لم ينتهوا عما يقولون﴾؟","answer":"الانتهاء يحتمل العدول عن التلفظ بالمقالة وعن اعتقادها معًا؛ فاختياره ينبه إلى أن مجرد ترك القول لا يكفي ما بقي الاعتقاد الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص455، تحت عنوان «علة إيثار لفظ الانتهاء»","url":""}]},{"id":"s5-386","number":386,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]}],"verseLabel":"المائدة: 73","question":"ما دلالة ﴿منهم﴾ في قوله تعالى: ﴿ليمسن الذين كفروا منهم عذاب أليم﴾؟","answer":"على أحد توجيهات «من» تكون للتبعيض؛ فيتوجه الوعيد إلى من استمر على الكفر ولم يقلع عنه، لا إلى من تاب. وهذا يناسب ما يلي من دعوتهم إلى التوبة والاستغفار.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص457–458، تحت «توجيه الوعيد على من دام به الكفر وأصر على فعله»","url":""}]},{"id":"s5-387","number":387,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]},{"surah":9,"verses":[90]}],"verseLabel":"المائدة: 73؛ التوبة: 90","question":"ما الفرق بين قوله تعالى في المائدة: ﴿ليمسن الذين كفروا منهم عذاب أليم﴾، وقوله في التوبة: ﴿سيصيب الذين كفروا منهم عذاب أليم﴾؟","answer":"توضح الموسوعة أن المس أدل على شدة العذاب من الإصابة؛ فناسب المائدة بعد الكلام على مقالة التثليث وشدة الكفر، وجاء مؤكدًا بلام القسم والنون. أما آية التوبة فسبقها جرم أخف، فجاء التعبير بالإصابة والسين لإعطائهم مهلة يتوبون فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص456، تحت عنوان «توجيه المتشابه اللفظي بين (المس) و(الإصابة)»","url":""}]},{"id":"s5-388","number":388,"surah":5,"verses":[74],"references":[{"surah":5,"verses":[74]}],"verseLabel":"المائدة: 74","question":"ما دلالة عرض التوبة بقوله تعالى: ﴿أفلا يتوبون إلى الله ويستغفرونه﴾ بدل الأمر المباشر؟","answer":"الاستفهام يفيد توبيخهم على ترك التوبة، والتعجيب من بقائهم على الإفك بعد وضوح بطلانه، وتحريضهم على الرجوع؛ فهي معان يجمعها العنوان المطبوع نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص461، تحت عنوان «بلاغة الاستفهام في الآية»","url":""}]},{"id":"s5-389","number":389,"surah":5,"verses":[74],"references":[{"surah":5,"verses":[74]}],"verseLabel":"المائدة: 74","question":"ما دلالة الجمع بين التوبة والاستغفار؟","answer":"التوبة رجوع عن الاعتقاد والقول الباطل وندم وعزم على عدم العودة، والاستغفار طلب محو ما سلف وستره؛ فالأولى إصلاح للموقف من الذنب، والثاني سؤال لرفع أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص464–465، تحت «التوبة والاستغفار»","url":""}]},{"id":"s5-390","number":390,"surah":5,"verses":[74],"references":[{"surah":5,"verses":[74]}],"verseLabel":"المائدة: 74","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله غفور رحيم﴾ بعد ذكر مقالة التثليث؟","answer":"جملة ﴿والله غفور رحيم﴾ حالية مؤكدة للإنكار والتعجيب من إصرارهم؛ فالله بالغ في مغفرة من استغفره ورحمته، ومع ذلك لا يسارعون إلى الاستغفار. وفي الخاتمة فتح لباب التوبة رغم عظم مقالتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص464، تحت عنوان «توجيه حالية جملة الفاصلة»","url":""}]},{"id":"s5-391","number":391,"surah":5,"verses":[75],"references":[{"surah":5,"verses":[75]}],"verseLabel":"المائدة: 75","question":"ما دلالة القصر في قوله تعالى: ﴿ما المسيح ابن مريم إلا رسول﴾؟","answer":"قصر المسيح عليه السلام على صفة الرسالة، ردًا على دعوى ألوهيته؛ فهو رسول من جنس الرسل الذين سبقوه، لا إله ولا واحد من ثلاثة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص468، تحت عنوان «بلاغة القصر في قوله: ﴿ما المسيح ابن مريم إلا رسول﴾»","url":""}]},{"id":"s5-693","number":693,"surah":5,"verses":[75],"references":[{"surah":5,"verses":[75]}],"verseLabel":"المائدة: 75","question":"ما دلالة وصف المسيح بقوله تعالى: ﴿قد خلت من قبله الرسل﴾؟","answer":"يبين اشتراكه مع سائر الرسل في الموت والحياة والرسالة وما أيدهم الله به من المعجزات؛ فلا يدل ما ظهر على يده على الألوهية، كما لم يدل عند غيره من الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص469، تحت عنوان «دلالة وصف (المسيح) بجملة: ﴿قد خلت من قبله الرسل﴾»","url":""}]},{"id":"s5-392","number":392,"surah":5,"verses":[75],"references":[{"surah":5,"verses":[75]}],"verseLabel":"المائدة: 75","question":"ما دلالة وصف مريم عليها السلام بأنها ﴿صديقة﴾ في هذا المقام؟","answer":"وصفها بالصديقية، أي المبالغة في الصدق والتصديق، رد على من غلا فيها؛ فهو يثبت لها منزلة بشرية رفيعة تلي منزلة الأنبياء، ولا يثبت ألوهيتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص469، تحت عنوان «نكتة الوصف في قوله تعالى: ﴿وأمه صديقة﴾»","url":""}]},{"id":"s5-393","number":393,"surah":5,"verses":[75],"references":[{"surah":5,"verses":[75]}],"verseLabel":"المائدة: 75","question":"كيف يحتج قوله تعالى: ﴿كانا يأكلان الطعام﴾ على بشرية المسيح وأمه؟","answer":"من وجوهه أنه كناية عن حاجتهما إلى الطعام وما يتبعه من لوازم البشر، أو تقرير لحقيقة أكلهما الدالة على الافتقار. وعلى الوجهين، المحتاج المخلوق لا يكون إلهًا غنيًا عن كل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص471، تحت عنوان «دلالة قوله تعالى: ﴿كانا يأكلان الطعام﴾ بين الكناية والحقيقة»","url":""}]},{"id":"s5-394","number":394,"surah":5,"verses":[75],"references":[{"surah":5,"verses":[75]}],"verseLabel":"المائدة: 75","question":"ما دلالة العطف بـ﴿ثم﴾ في قوله تعالى: ﴿ثم انظر أنى يؤفكون﴾؟","answer":"تفيد الترتيب الرتبي والتفاوت بين الحالين: وضوح الحجج أولًا، ثم عجب انصرافهم عنها بعد هذا البيان. ويحتمل أن تدل على استمرار البيان وامتداده مع استمرار إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص474، تحت عنوان «دلالة العطف بـ﴿ثم﴾ في قوله تعالى: ﴿ثم انظر أنى يؤفكون﴾»","url":""}]},{"id":"s5-694","number":694,"surah":5,"verses":[75],"references":[{"surah":5,"verses":[75]}],"verseLabel":"المائدة: 75","question":"لماذا تكرر الأمر بالنظر في قوله تعالى: ﴿انظر كيف نبين لهم الآيات ثم انظر أنى يؤفكون﴾؟","answer":"تكرر لاختلاف المتعلق؛ فالنظر الأول إلى كيفية إيضاح الآيات، والآخر إلى حال انصرافهم عن الحق بعد ظهوره. وفي التكرار عناية بالنظر وتدبر وتعجيب من الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص474، تحت عنوان «سر تكرار الأمر بالنظر في قوله تعالى: ﴿انظر كيف نبين﴾ و﴿ثم انظر أنى﴾»","url":""}]},{"id":"s5-395","number":395,"surah":5,"verses":[75],"references":[{"surah":5,"verses":[75]}],"verseLabel":"المائدة: 75","question":"لماذا عُدل من ﴿كيف﴾ إلى ﴿أنى﴾ في قوله تعالى: ﴿ثم انظر أنى يؤفكون﴾؟","answer":"﴿أنى﴾ اسم استفهام أصله السؤال: من أين، ويستعمل بمعنى كيف. وعدل إليه عن تكرار ﴿كيف﴾ للتفنن والتوسيع، وللتعجب من أي جهة صُرفوا عن الحق بعد بلوغ البيان غاية الوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص475، تحت عنوان «دلالة الاستفهام بـ(أنى) في قوله تعالى: ﴿ثم انظر أنى يؤفكون﴾»","url":""}]},{"id":"s5-396","number":396,"surah":5,"verses":[76],"references":[{"surah":5,"verses":[76]}],"verseLabel":"المائدة: 76","question":"ما سرّ تقديم الضر على النفع في قوله تعالى: ﴿ما لا يملك لكم ضرًا ولا نفعًا﴾؟","answer":"قُدّم الضر لأن دفعه أهم من جلب النفع؛ فالإنسان يطلب سلامته أولًا، ثم يطلب ما ينفعه. وفي مقام نفي قدرة المعبودات كان البدء بما يخافه الناس أوقع في إقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص481، تحت عنوان «نكتة تقديم الضر على النفع»","url":""}]},{"id":"s5-397","number":397,"surah":5,"verses":[76],"references":[{"surah":5,"verses":[76]}],"verseLabel":"المائدة: 76","question":"ما دلالة التعبير عن المعبودات بـ﴿ما﴾ في قوله تعالى: ﴿أتعبدون من دون الله ما لا يملك لكم ضرًا ولا نفعًا﴾؟","answer":"جيء بـ﴿ما﴾ لأنها تعم كل ما عُبد من دون الله بالنظر إلى وصفه لا إلى شخصه، ولأن سلب القدرة عن المعبود ينزله منزلة ما لا يعقل ولا يملك تصرفًا؛ فناسبها مقام إبطال الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص480، تحت «نكتة التعبير بالاسم الموصول لما لا يعقل ما»","url":""}]},{"id":"s5-398","number":398,"surah":5,"verses":[76],"references":[{"surah":5,"verses":[76]}],"verseLabel":"المائدة: 76","question":"ما دلالة ضمير الفصل في قوله تعالى: ﴿والله هو السميع العليم﴾؟","answer":"يفيد ﴿هو﴾ قصر كمال السمع والعلم على الله؛ فهو يسمع أقوال العابدين ودعاءهم، ويعلم عقائدهم وحاجاتهم، بخلاف ما عُبد من دونه مما لا يملك ضرًا ولا نفعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص483–484، تحت «بلاغة القصر بتعريف الجزأين مع تأكيده بضمير الفصل والحال»","url":""}]},{"id":"s5-399","number":399,"surah":5,"verses":[77],"references":[{"surah":5,"verses":[77]}],"verseLabel":"المائدة: 77","question":"ما الأوجه النحوية في نصب ﴿غير الحق﴾، وكيف يتغير المعنى بها؟","answer":"يجوز نصب ﴿غير﴾ على الحال، أي: لا تغلوا غلوًا باطلًا مخالفًا للحق، ويجوز حملها على الاستثناء، أي لا تتجاوزوا الحد في دينكم إلا الحق الذي دلت عليه النصوص. ويجوز أيضًا إضمار فعل يناسب السياق؛ فتعدد الوجه النحوي يوسع دلالة التحذير من الغلو الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص489، تحت عنوان «تعدد المعاني باختلاف تعيين وجه النصب في ﴿غير﴾ من قوله تعالى: ﴿غير الحق﴾»","url":""}]},{"id":"s5-695","number":695,"surah":5,"verses":[77],"references":[{"surah":5,"verses":[77]}],"verseLabel":"المائدة: 77","question":"هل يفيد قوله تعالى: ﴿لا تغلوا في دينكم غير الحق﴾ وجود غلوٍّ بحق؟","answer":"القيد احتراس من فهم أن كل زيادة أو مبالغة مذمومة؛ فالمنهي عنه تجاوز دائرة الحق إلى الباطل، كغلو النصارى في المسيح. أما الاجتهاد المشروع في الطاعة من غير مخالفة للشرع فليس داخلًا في هذا الغلو.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص489–490، تحت عنوان «بلاغة الاحتراس في تقييد ﴿لا تغلوا﴾ بقوله: ﴿غير الحق﴾»","url":""}]},{"id":"s5-400","number":400,"surah":5,"verses":[77],"references":[{"surah":5,"verses":[77]}],"verseLabel":"المائدة: 77","question":"لماذا جُمعت كلمة ﴿هوى﴾ في قوله تعالى: ﴿ولا تتبعوا أهواء قوم﴾؟","answer":"جُمعت على ﴿أهواء﴾ تنبيهًا إلى كثرة ميولهم الباطلة وتنوعها؛ فهم متفاوتون في ضروب الانحراف، فلا يتبع أهل الكتاب شيئًا منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص490–491، تحت عنوان «سر جمع (هوى) على (أهواء) في قوله تعالى: ﴿ولا تتبعوا أهواء قوم قد ضلوا من قبل﴾»","url":""}]},{"id":"s5-696","number":696,"surah":5,"verses":[77],"references":[{"surah":5,"verses":[77]}],"verseLabel":"المائدة: 77","question":"ما دلالة تنكير ﴿قوم﴾ في قوله تعالى: ﴿ولا تتبعوا أهواء قوم﴾؟","answer":"التنكير للتحقير والتحذير؛ أي لا تتبعوا أهواء قوم شأنهم أن ضلوا من قبل، وفي إضافة الأهواء إليهم زيادة تحذير من الاقتداء بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص491، تحت عنوان «نكتة تنكير ﴿قوم﴾ من قوله تعالى: ﴿ولا تتبعوا أهواء قوم قد ضلوا من قبل﴾»","url":""}]},{"id":"s5-401","number":401,"surah":5,"verses":[77],"references":[{"surah":5,"verses":[77]}],"verseLabel":"المائدة: 77","question":"ما دلالة تكرار فعل الضلال في قوله تعالى: ﴿قد ضلوا من قبل وأضلوا كثيرًا وضلوا عن سواء السبيل﴾؟","answer":"كرر الفعل لأن المراتب مختلفة: ضلوا أولًا في أنفسهم، ثم أضلوا كثيرًا من الناس، ثم استمروا في ضلالهم عن الطريق المستقيم. فالتكرار يصور انتقال الضلال من النفس إلى الغير ثم رسوخه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص491–492، تحت عنوان «نكتة تكرار الفعل ﴿ضلوا﴾ من قوله تعالى: ﴿قد ضلوا من قبل وأضلوا كثيرًا وضلوا عن سواء السبيل﴾»","url":""}]},{"id":"s5-402","number":402,"surah":5,"verses":[78],"references":[{"surah":5,"verses":[78]}],"verseLabel":"المائدة: 78","question":"لماذا بُني فعل ﴿لُعن﴾ للمفعول في قوله تعالى: ﴿لُعن الذين كفروا من بني إسرائيل﴾؟","answer":"بُني للمفعول للإشعار باستحقاقهم اللعن وتهويله، ولصرف العناية إلى نفس وقوع اللعن عليهم من غير حاجة إلى تعيين اللاعن؛ فالمقام مقام تقبيح حالهم وعقوبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص496، تحت عنوان «علة بناء الفعل للمفعول»","url":""}]},{"id":"s5-403","number":403,"surah":5,"verses":[78],"references":[{"surah":5,"verses":[78]}],"verseLabel":"المائدة: 78","question":"ما دلالة الجمع بين داود وعيسى عليهما السلام مع تباعد زمنيهما؟","answer":"خُصّا بالذكر لأن بني إسرائيل لُعنوا على لسانيهما في زمنين متباعدين؛ فدل ذلك على امتداد اللعن واستمرار موجبه عبر عصور طويلة، لا على أنه حادثة جيل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص497، تحت عنوان «السر في تخصيص ذكر داود وعيسى دون غيرهما»","url":""}]},{"id":"s5-404","number":404,"surah":5,"verses":[78],"references":[{"surah":5,"verses":[78]}],"verseLabel":"المائدة: 78","question":"لماذا عُبِّر عن العصيان بالماضي وعن الاعتداء بالمضارع في قوله تعالى: ﴿عصوا وكانوا يعتدون﴾؟","answer":"عُبّر عن العصيان بالماضي للدلالة على استقراره في نفوسهم حتى صار وصفًا معروفًا، وعن الاعتداء بالمضارع لأنه متجدد مستمر؛ فقد تكرر اعتداؤهم في زمن النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص501، تحت عنوان «السر في التعبير عن العصيان بالماضي، والاعتداء بالمضارع»","url":""}]},{"id":"s5-405","number":405,"surah":5,"verses":[79],"references":[{"surah":5,"verses":[79]}],"verseLabel":"المائدة: 79","question":"لماذا عُدَّ ترك التناهي عن المنكر تفسيرًا للعصيان والاعتداء؟","answer":"لأن ترك إنكار المنكر يشيع المعصية ويقرها؛ فكانوا يفعلون المنكر ولا ينهى بعضهم بعضًا عنه، فاجتمع فيهم فعل المعصية والرضا بها وترك مقاومتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص503، تحت عنوان «السر في جعل ترك النهي تفسيرًا للمعصية»","url":""}]},{"id":"s5-697","number":697,"surah":5,"verses":[79],"references":[{"surah":5,"verses":[79]}],"verseLabel":"المائدة: 79","question":"ما دلالة صيغة التفاعل في قوله تعالى: ﴿كانوا لا يتناهون﴾؟","answer":"صيغة التفاعل تدل على المشاركة؛ أي إنهم لم يكن بعضهم ينهى بعضًا عن المنكر، فعمّ ترك الإنكار جماعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص504، تحت عنوان «إيثار التعبير بصيغة التفاعل»","url":""}]},{"id":"s5-698","number":698,"surah":5,"verses":[79],"references":[{"surah":5,"verses":[79]}],"verseLabel":"المائدة: 79","question":"كيف يوجَّه النهي عن ﴿منكر فعلوه﴾ مع أن الفعل قد وقع؟","answer":"المقصود النهي عن معاودة المنكر والاستمرار فيه؛ فالماضي يصف ما وقع منهم، والنهي المتروك كان ينبغي أن يمنع تكراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص504، تحت عنوان «وجه توجيه النهي إلى منكر قد فعلوه»","url":""}]},{"id":"s5-406","number":406,"surah":5,"verses":[79],"references":[{"surah":5,"verses":[79]}],"verseLabel":"المائدة: 79","question":"ما دلالة تنكير ﴿منكر﴾ في قوله ﴿عن منكر فعلوه﴾؟","answer":"يفيد التنكير هنا تهويل كثرة المنكر الذي فعلوه، حتى كأنه مما لا يحيط به التفصيل؛ ووروده في سياق النفي يبالغ في تصوير إغراقهم في المنكر مع ترك التناهي عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص504، تحت «الغرض من تنكير المنكر»","url":""}]},{"id":"s5-407","number":407,"surah":5,"verses":[79],"references":[{"surah":5,"verses":[79]}],"verseLabel":"المائدة: 79","question":"ما غرض الذم في قوله تعالى: ﴿لبئس ما كانوا يفعلون﴾؟","answer":"جاء الذم للتقبيح والتعجيب من سوء فعلهم، إذ جمعوا بين ارتكاب المنكر وترك التناهي عنه، وفيه تحذير للمؤمنين من سلوك طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص505، تحت عنوان «الغرض من الذم»","url":""}]},{"id":"s5-699","number":699,"surah":5,"verses":[79],"references":[{"surah":5,"verses":[79]}],"verseLabel":"المائدة: 79","question":"ما دلالة اللام في قوله تعالى: ﴿لبئس ما كانوا يفعلون﴾؟","answer":"اللام موطئة للقسم؛ فالجملة تتضمن قسمًا مقدرًا يؤكد شدة ذم أفعالهم ويقويه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص505، تحت عنوان «دلالة لام القسم»","url":""}]},{"id":"s5-700","number":700,"surah":5,"verses":[79],"references":[{"surah":5,"verses":[79]}],"verseLabel":"المائدة: 79","question":"لماذا عبّر عن ترك النهي بلفظ الفعل في قوله تعالى: ﴿لبئس ما كانوا يفعلون﴾؟","answer":"أطلق الفعل على ترك التناهي لأن السكوت على المنكر مشاركة فيه وإظهار للرضا به؛ فصار ترك الإنكار في حكم الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص505–506، تحت عنوان «إطلاق لفظ الفعل على ترك النهي»","url":""}]},{"id":"s5-408","number":408,"surah":5,"verses":[80],"references":[{"surah":5,"verses":[80]}],"verseLabel":"المائدة: 80","question":"ما أثر التعبير بالرؤية في ﴿ترى كثيرًا منهم يتولون الذين كفروا﴾؟","answer":"يجعل موالاتهم أمرًا واضحًا مشاهدًا؛ فعدل عن مجرد الإخبار إلى الرؤية البصرية لتأكيد تحققها وظهور آثارها، حتى يراها كل أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص508، تحت «العدول عن الإخبار إلى الرؤية بالبصر»","url":""}]},{"id":"s5-409","number":409,"surah":5,"verses":[80],"references":[{"surah":5,"verses":[80]}],"verseLabel":"المائدة: 80","question":"ما سر وصف الأعمال بالتقديم في قوله تعالى: ﴿لبئس ما قدمت لهم أنفسهم﴾؟","answer":"صُورت الأعمال كشيء يقدمه الإنسان أمامه ثم يلقاه يوم القيامة؛ فالآية تذم ما أرسلته أنفسهم من أعمال سيئة ليجدوا جزاءه حاضرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص509، تحت عنوان «السر في وصف الأعمال بالتقديم»","url":""}]},{"id":"s5-410","number":410,"surah":5,"verses":[80],"references":[{"surah":5,"verses":[80]}],"verseLabel":"المائدة: 80","question":"ما دلالة جعل ما قدمته أنفسهم هو قوله تعالى: ﴿أن سخط الله عليهم﴾؟","answer":"التقدير: موجب سخط الله عليهم؛ فحُذف المضاف وأقيم السخط مقام سببه للمبالغة، كأن أعمالهم الموجبة للسخط والسخط الناتج عنها شيء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص510، تحت عنوان «علة تقدير مضاف محذوف»","url":""}]},{"id":"s5-411","number":411,"surah":5,"verses":[80],"references":[{"surah":5,"verses":[80]}],"verseLabel":"المائدة: 80","question":"ما دلالة التقديم والتوكيد في قوله تعالى: ﴿وفي العذاب هم خالدون﴾؟","answer":"قُدم الخبر ﴿في العذاب﴾ للاهتمام به وتعجيل ما يفجعهم، وأكدت الجملة بضمير الفصل ﴿هم﴾ وبالتقديم؛ ردًا على توهمهم أن النار لا تمسهم إلا أيامًا معدودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص511، تحت عنوان «تأكيد الخبر بضمير الوصل وتقديم الخبر»","url":""}]},{"id":"s5-412","number":412,"surah":5,"verses":[81],"references":[{"surah":5,"verses":[81]}],"verseLabel":"المائدة: 81","question":"لماذا يمنع صدق الإيمان بالله والنبي والقرآن من موالاة الكافرين؟","answer":"لأن الإيمان الصادق يقتضي طاعة الله ورسوله واتباع القرآن، وقد نهت هذه الأصول عن اتخاذ الكافرين أولياء؛ فموالاتهم تكشف خلل الدعوى وعدم تحقق مقتضاها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص513، تحت عنوان «علة كون الإيمان بالنبي والقرآن يمنع من موالاة الكافرين»","url":""}]},{"id":"s5-413","number":413,"surah":5,"verses":[81],"references":[{"surah":5,"verses":[81]}],"verseLabel":"المائدة: 81","question":"ما أثر الأسلوب الشرطي في ﴿ولو كانوا يؤمنون بالله والنبي وما أنزل إليه ما اتخذوهم أولياء﴾؟","answer":"يربط بين صدق الإيمان وترك هذه الموالاة، ثم يستدل على الأمر الخفي، وهو انتفاء الإيمان عنهم، بالأمر المشاهد من اتخاذهم أولياء؛ فالشرط يبين التلازم ويؤكد وجه الدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص513–514، تحت «السر في التعبير بالجملة الشرطية»","url":""}]},{"id":"s5-414","number":414,"surah":5,"verses":[81],"references":[{"surah":5,"verses":[81]}],"verseLabel":"المائدة: 81","question":"ما فائدة الاستدراك في قوله تعالى: ﴿ولكن كثيرًا منهم فاسقون﴾؟","answer":"استدركت الجملة على الشرط السابق لتبين سبب تركهم مقتضى الإيمان؛ فكثير منهم خارجون عن الطاعة، ولذلك والوا الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص515، تحت عنوان «فائدة الاستدراك»","url":""}]},{"id":"s5-701","number":701,"surah":5,"verses":[81],"references":[{"surah":5,"verses":[81]}],"verseLabel":"المائدة: 81","question":"لماذا نُسب الفسق إلى كثير منهم دون جميعهم؟","answer":"لإنصاف من آمن منهم أو لم يثبت عليه الفسق؛ فالقرآن لا يعمم الحكم على الجميع مع علمه باختلاف أحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص515، تحت عنوان «علة نسبة الفسق للأكثر دون الجميع»","url":""}]},{"id":"s5-702","number":702,"surah":5,"verses":[81],"references":[{"surah":5,"verses":[81]}],"verseLabel":"المائدة: 81","question":"لماذا قيل: ﴿فاسقون﴾ بعد نفي حقيقة الإيمان عنهم؟","answer":"اختير اسم الفاعل للدلالة على تمكن الفسق وثباته في كثير منهم، فبيّن أن خروجهم عن الطاعة هو الحامل على موالاة الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص516، تحت عنوان «إيثار التعبير بالفسق بعد الوصف بانتفاء الإيمان»","url":""}]},{"id":"s5-415","number":415,"surah":5,"verses":[82],"references":[{"surah":5,"verses":[82]}],"verseLabel":"المائدة: 82","question":"ما دلالة لام القسم ونون التوكيد في قوله تعالى: ﴿لتجدن أشد الناس عداوة﴾ و﴿ولتجدن أقربهم مودة﴾؟","answer":"تؤكدان أن ما أخبر به القرآن حقيقة سيجدها المخاطب واضحة في الواقع، وفي التوكيد تقرير لشدة عداوة فريق وقرب مودة فريق آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص522–523، تحت عنوان «لام القسم ودورها في تأكيد مضمون الخطاب»","url":""}]},{"id":"s5-703","number":703,"surah":5,"verses":[82],"references":[{"surah":5,"verses":[82]}],"verseLabel":"المائدة: 82","question":"ما أثر المقابلة بين ﴿أشد الناس عداوة﴾ و﴿أقربهم مودة﴾؟","answer":"أبرزت المقابلة تفاوت الطوائف في موقفها من المؤمنين؛ فوضعت شدة العداوة في طرف وقرب المودة في طرف آخر، فظهر المعنى بالضد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص525–526، تحت عنوان «الطباق ودوره في إبراز المعنى»","url":""}]},{"id":"s5-416","number":416,"surah":5,"verses":[82],"references":[{"surah":5,"verses":[82]}],"verseLabel":"المائدة: 82","question":"ما سرّ تقديم اليهود على المشركين في جانب العداوة؟","answer":"قُدِّم اليهود على المشركين من باب تقديم الأكثر عداوة على الأقل؛ فعداوتهم للمؤمنين أشد، ثم عُطف المشركون عليهم لاشتراك الفريقين فيها","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص524–525، تحت «دور تقديم لفظ اليهود»","url":""}]},{"id":"s5-417","number":417,"surah":5,"verses":[82],"references":[{"surah":5,"verses":[82]}],"verseLabel":"المائدة: 82","question":"ما دلالة وصف النصارى بأنهم ﴿أقربهم مودة للذين آمنوا﴾ دون: أشدهم مودة؟","answer":"جيء بـ﴿أقربهم﴾ مع أن المقابل ﴿أشد الناس عداوة﴾؛ لأن المقصود ترتيب الطوائف في قرب المودة، لا إثبات أن كل فرد منهم بلغ أشد المودة. فاختير اللفظ الذي يلائم حقيقة التفاوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص526–527، تحت عنوان «مخالفة القياس في أفعل التفضيل ودلالته»","url":""}]},{"id":"s5-418","number":418,"surah":5,"verses":[82],"references":[{"surah":5,"verses":[82]}],"verseLabel":"المائدة: 82","question":"ما دلالة الباء في قوله تعالى: ﴿ذلك بأن منهم قسيسين ورهبانًا﴾؟","answer":"الباء سببية؛ أي إن وجود أهل العلم والعبادة المتواضعين بينهم كان سببًا في قرب مودة فريق منهم للمؤمنين وقبولهم الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص529، تحت عنوان «فائدة الباء السببية»","url":""}]},{"id":"s5-704","number":704,"surah":5,"verses":[82],"references":[{"surah":5,"verses":[82]}],"verseLabel":"المائدة: 82","question":"لماذا قُدِّم ﴿قسيسين﴾ على ﴿رهبانًا﴾؟","answer":"قُدّم القسيسون لأنهم أهل العلم والتعليم، والعلم أصل تهتدي به العبادة؛ ثم ذُكر الرهبان لما في زهدهم وتواضعهم من تهيئة لقبول الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص530، تحت عنوان «حكمة تقديم لفظ (قسيسين) على (رهبانًا)»","url":""}]},{"id":"s5-419","number":419,"surah":5,"verses":[82],"references":[{"surah":5,"verses":[82]}],"verseLabel":"المائدة: 82","question":"ما دلالة ختم التعليل بقوله تعالى: ﴿وأنهم لا يستكبرون﴾؟","answer":"خُصّ عدم الاستكبار لأنه الأساس الذي جعل علمهم وعبادتهم يثمران قبولًا للحق؛ فالعارف قد يمنعه الكبر من الإذعان، أما تواضعهم فمهّد لسماع القرآن والإيمان به.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص531، تحت عنوان «السر في ذكر صفة عدم استكبارهم على الخصوص»","url":""}]},{"id":"s5-420","number":420,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"ما دلالة العدول من الإخبار إلى الرؤية في قوله تعالى: ﴿ترى أعينهم تفيض من الدمع﴾؟","answer":"حوّل التعبير حالهم إلى مشهد بصري حاضر؛ فكأن السامع يراهم أمامه ودموعهم تفيض، وفي ذلك مبالغة في بيان شدة تأثرهم بالحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص538، تحت عنوان «العدول عن الإخبار إلى الرؤية»","url":""}]},{"id":"s5-705","number":705,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"لماذا عُبِّر عن فيض عيونهم بالفعل المضارع ﴿تفيض﴾؟","answer":"المضارع يستحضر صورة الفيضان متجددة أمام السامع، ويصور استمرار تأثرهم ورقة قلوبهم كلما سمعوا الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص539–540، تحت عنوان «إيثار التعبير عن فيض عيونهم بالفعل المضارع»","url":""}]},{"id":"s5-421","number":421,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"ما سرّ إسناد الفيضان إلى الأعين لا إلى الدموع؟","answer":"أُسند الفيضان إلى الأعين وهي ظرف الدمع على سبيل المجاز العقلي، مبالغة في كثرة البكاء؛ كأن العين نفسها فاضت بعدما امتلأت بالدمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص541، تحت عنوان «إسناد الفيض إلى الظرف من باب المجاز العقلي»","url":""}]},{"id":"s5-422","number":422,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"ما دلالة التعبير بالفعل ﴿عرفوا﴾ في قوله تعالى: ﴿مما عرفوا من الحق﴾؟","answer":"المعرفة إدراك للشيء متميزًا مفصلًا؛ فدل الفعل على أنهم لم يتأثروا بمجرد الصوت، بل تحققوا أن المنزل هو الحق الذي عرفوا دلائله، ففاضت أعينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص543، تحت عنوان «دلالة التعبير بالفعل ﴿عرف﴾»","url":""}]},{"id":"s5-423","number":423,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"ما موقع جملة ﴿يقولون ربنا آمنا﴾ من مشهد فيض الدموع؟","answer":"يجوز أن تكون حالًا، فيكون قولهم مصاحبًا لرؤية أعينهم تفيض، ويجوز أن تكون استئنافًا يبين ما نطقوا به بعد أن عرفوا الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص544، تحت عنوان «جملة ﴿يقولون﴾ بين الحالية والاستئناف»","url":""}]},{"id":"s5-706","number":706,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"ما دلالة حذف أداة النداء في قولهم: ﴿ربنا آمنا﴾؟","answer":"حُذفت أداة النداء إشعارًا بقرب المدعو وسرعة المناجاة، وإظهارًا لصدق الالتجاء إلى الله عقب معرفتهم الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص544–545، تحت عنوان «دلالة حذف أداة النداء في قولهم ﴿ربنا﴾»","url":""}]},{"id":"s5-707","number":707,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"ما دلالة الفاء في قولهم: ﴿فَاكتبنا مع الشاهدين﴾؟","answer":"الفاء تفريعية؛ ربطت طلب الكتابة مع الشاهدين بإيمانهم، فكأنهم جعلوا الإيمان سببًا مباشرًا لهذا الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص545، تحت عنوان «الربط بالفاء التفريعية في قوله: ﴿فاكتبنا﴾»","url":""}]},{"id":"s5-424","number":424,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"من الشاهدون الذين طلبوا أن يكتبهم الله معهم في قوله: ﴿فاكتبنا مع الشاهدين﴾؟","answer":"من توجيهاتهم أمة محمد ﷺ التي تشهد للرسل بالبلاغ، أو الذين شهدوا بالحق وصدقوا الرسل. وطلبوا الكتابة معهم رغبة في شرف هذه المنزلة وثباتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص545–546، تحت عنوان «السر في طلبهم أن يكونوا مع الشاهدين»","url":""}]},{"id":"s5-425","number":425,"surah":5,"verses":[84],"references":[{"surah":5,"verses":[84]}],"verseLabel":"المائدة: 84","question":"ما دلالة قولهم: ﴿وما لنا لا نؤمن بالله وما جاءنا من الحق﴾؟","answer":"الاستفهام إنكاري ينفي وجود مانع معقول من الإيمان بعد معرفة الحق؛ فكأنهم يقولون: أي عذر يبقى لنا في تركه؟ وفيه رد على من لامهم أو حاول صدهم عن إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص549، تحت «الغرض من الاستفهام في وما لنا لا نؤمن بالله»","url":""}]},{"id":"s5-426","number":426,"surah":5,"verses":[84],"references":[{"surah":5,"verses":[84]}],"verseLabel":"المائدة: 84","question":"ما دلالة التعبير بلفظ ﴿القوم﴾ في قوله تعالى: ﴿مع القوم الصالحين﴾؟","answer":"لفظ القوم يشعر بأن الصلاح صار سمة راسخة للجماعة، لا وصفًا عارضًا لفرد، ولذلك رغبوا في الانضمام إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص550، تحت عنوان «دلالة التعبير بلفظ ﴿القوم﴾»","url":""}]},{"id":"s5-708","number":708,"surah":5,"verses":[84],"references":[{"surah":5,"verses":[84]}],"verseLabel":"المائدة: 84","question":"ما معنى المعية في قوله تعالى: ﴿مع القوم الصالحين﴾؟","answer":"هي معية الصحبة واللحوق بالصالحين في الجنة والمشاركة في كرامتهم، لا مجرد اجتماع مكاني عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص551، تحت عنوان «معنى المعية في قوله تعالى: ﴿مع القوم الصالحين﴾»","url":""}]},{"id":"s5-427","number":427,"surah":5,"verses":[83,84],"references":[{"surah":5,"verses":[83,84]}],"verseLabel":"المائدة: 83–84","question":"ما معنى المعية في قولهم: ﴿فاكتبنا مع الشاهدين﴾؟","answer":"المعية هي الإلحاق بجماعة الشاهدين في الوصف والمنزلة والجزاء؛ أي اجعلنا ممن صدقوا الحق وقاموا بالشهادة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص545، تحت عنوان «معنى المعية في ﴿فاكتبنا مع الشاهدين﴾»","url":""}]},{"id":"s5-428","number":428,"surah":5,"verses":[85],"references":[{"surah":5,"verses":[85]}],"verseLabel":"المائدة: 85","question":"ما دلالة قوله تعالى: ﴿فأثابهم الله بما قالوا جنات﴾، مع أن الثواب ليس على مجرد القول؟","answer":"قولهم كان إقرارًا صادقًا كشف ما استقر في قلوبهم من معرفة وإيمان، واقترن بما ظهر من خشوعهم؛ فذكر القول لأنه الصورة المعلنة لتصديقهم، لا لأن لفظًا مجردًا من الاعتقاد والعمل يوجب الثواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص554، تحت «فاء السببية وترتب الثواب على العمل»","url":""}]},{"id":"s5-429","number":429,"surah":5,"verses":[85],"references":[{"surah":5,"verses":[85]}],"verseLabel":"المائدة: 85","question":"ما بلاغة قوله تعالى: ﴿جنات تجري من تحتها الأنهار﴾؟","answer":"تفيد ﴿من تحتها﴾ أن مبادئ الأنهار تجري من تحت أشجار الجنات وقصورها، وهو تصوير لوفرة النعيم ودوامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص555، تحت عنوان «بلاغة التعبير بـ﴿تجري من تحتها الأنهار﴾ دون ﴿تجري تحتها الأنهار﴾»","url":""}]},{"id":"s5-709","number":709,"surah":5,"verses":[85],"references":[{"surah":5,"verses":[85]}],"verseLabel":"المائدة: 85","question":"ما دلالة المضارع في قوله تعالى: ﴿تجري من تحتها الأنهار﴾؟","answer":"المضارع يدل على الحال والاستقبال، فيصور جريان الأنهار متجددًا دائمًا؛ وفيه نعيم مستمر لا ينقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص555، تحت عنوان «دلالة المضارع في ﴿تجري﴾»","url":""}]},{"id":"s5-430","number":430,"surah":5,"verses":[85],"references":[{"surah":5,"verses":[85]}],"verseLabel":"المائدة: 85","question":"ما دلالة ختم الآية بقوله تعالى: ﴿وذلك جزاء المحسنين﴾ دون: المؤمنين؟","answer":"وُضع «المحسنين» موضع ضميرهم ثناءً عليهم وتعميمًا للجزاء؛ فهو جزاء من آمن وأحسن العمل وترقى في مدارج الإحسان. وفي التصريح بالوصف تقوية للمعنى وزيادة بيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص555–556، تحت «دلالة الإظهار بدل الإضمار في لفظ المحسنين»","url":""}]},{"id":"s5-431","number":431,"surah":5,"verses":[86],"references":[{"surah":5,"verses":[86]}],"verseLabel":"المائدة: 86","question":"ما دلالة الجمع بين قوله تعالى: ﴿كفروا﴾ وقوله: ﴿وكذبوا بآياتنا﴾؟","answer":"الكفر تغطية الحق، والتكذيب بالآيات ضرب مخصوص منه؛ فعُطف الخاص على العام لتأكيد حالهم وإبراز جحدهم دلائل الله","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص558، تحت «التكذيب بعد الكفر من الخاص على العام»","url":""}]},{"id":"s5-432","number":432,"surah":5,"verses":[86],"references":[{"surah":5,"verses":[86]}],"verseLabel":"المائدة: 86","question":"ما دلالة اسم الإشارة في قوله تعالى: ﴿أولئك أصحاب الجحيم﴾؟","answer":"يشير اسم الإشارة إلى المذكورين بصفاتهم، ويفيد بعد منزلتهم في الكفر واستحقاقهم الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص559، تحت عنوان «دلالة اسم الإشارة ﴿أولئك﴾»","url":""}]},{"id":"s5-710","number":710,"surah":5,"verses":[86],"references":[{"surah":5,"verses":[86]}],"verseLabel":"المائدة: 86","question":"ما دلالة الجملة الاسمية في قوله تعالى: ﴿أولئك أصحاب الجحيم﴾؟","answer":"تفيد الاسمية الثبات واللزوم، ولفظ ﴿أصحاب﴾ يصور ملازمتهم للجحيم كما يلازم الصاحب صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص559، تحت عنوان «التعبير بالاسمية ودلالاتها على الثبات واللزوم»","url":""}]},{"id":"s5-433","number":433,"surah":5,"verses":[87],"references":[{"surah":5,"verses":[87]}],"verseLabel":"المائدة: 87","question":"ما مناسبة النهي عن تحريم الطيبات بعد ذكر النصارى الذين قربوا مودة؟","answer":"لئلا يحمل الثناء على خشوع فريق من النصارى المؤمنين بعض المسلمين على تقليد الرهبانية وترك المباحات تقربًا؛ فصحح السياق الميزان: يُقبل تواضعهم للحق، ولا يُتبع ما أحدث من تحريم الطيبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص561، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s5-434","number":434,"surah":5,"verses":[87],"references":[{"surah":5,"verses":[87]}],"verseLabel":"المائدة: 87","question":"كيف أكد قوله تعالى: ﴿ولا تعتدوا﴾ النهي في ﴿لا تحرموا طيبات ما أحل الله لكم﴾؟","answer":"جاء النهي عن الاعتداء بعد النهي عن التحريم ليقرر أن تحريم الحلال تجاوز لحدود الله، ويمنع كذلك مجاوزة حد الاعتدال في المباح.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص565–566، تحت عنوان «تأكيد النهي في ﴿لا تحرموا﴾ بالنهي في ﴿ولا تعتدوا﴾»","url":""}]},{"id":"s5-711","number":711,"surah":5,"verses":[87],"references":[{"surah":5,"verses":[87]}],"verseLabel":"المائدة: 87","question":"ما معنى الاعتداء في قوله تعالى: ﴿ولا تعتدوا﴾؟","answer":"هو تجاوز الحد فيما حرّم الله أو أحل؛ فيشمل تحريم الطيبات بلا دليل، كما يشمل الإسراف أو استعمال المباح على وجه محظور.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص566، تحت عنوان «معنى الاعتداء في الآية الكريمة»","url":""}]},{"id":"s5-435","number":435,"surah":5,"verses":[87],"references":[{"surah":5,"verses":[87]}],"verseLabel":"المائدة: 87","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله لا يحب المعتدين﴾؟","answer":"الخاتمة تعلل النهي: من تجاوز حدود الله بتحريم حلال أو تعدي حد الاعتدال حرم محبته؛ وتسميتهم ﴿المعتدين﴾ تجعل الحكم متعلقًا بوصف التجاوز نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص566، تحت «مناسبة التذييل بقوله إن الله لا يحب المعتدين»","url":""}]},{"id":"s5-436","number":436,"surah":5,"verses":[88],"references":[{"surah":5,"verses":[88]}],"verseLabel":"المائدة: 88","question":"ما دلالة الأمر في قوله تعالى: ﴿وكلوا مما رزقكم الله﴾؟","answer":"الأمر للإباحة وإبطال ما أحدثوه من تحريم الطيبات، وفيه دعوة إلى قبول رزق الله والانتفاع به من غير تنطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص566، تحت عنوان «الأمر للإباحة في قوله: ﴿وكلوا﴾»","url":""}]},{"id":"s5-712","number":712,"surah":5,"verses":[88],"references":[{"surah":5,"verses":[88]}],"verseLabel":"المائدة: 88","question":"ما دلالة ﴿مما﴾ في قوله تعالى: ﴿وكلوا مما رزقكم الله﴾؟","answer":"تحتمل التبعيض، فتشير إلى الأكل بقدر الحاجة وترك الإسراف، وتفيد ابتداء التناول من رزق الله الواسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص567، تحت عنوان «دلالة التعبير بـ﴿مما﴾»","url":""}]},{"id":"s5-713","number":713,"surah":5,"verses":[88],"references":[{"surah":5,"verses":[88]}],"verseLabel":"المائدة: 88","question":"هل المراد بالأكل في قوله تعالى: ﴿وكلوا مما رزقكم الله﴾ الطعام وحده؟","answer":"الأكل هنا كناية عن الانتفاع العام؛ لأنه أعظم وجوه الانتفاع بالرزق، فيشمل الطعام والشراب واللباس وسائر المباحات.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص567، تحت عنوان «المراد بمعنى الأكل»","url":""}]},{"id":"s5-437","number":437,"surah":5,"verses":[88],"references":[{"surah":5,"verses":[88]}],"verseLabel":"المائدة: 88","question":"ما الفرق بين ﴿حلالًا﴾ و﴿طيبًا﴾ في وصف الرزق؟","answer":"الحلال ما أباحه الشرع ولم يمنعه، والطيب ما تستلذه النفس ويكون نافعًا سائغًا؛ فجمع الوصفان الإباحة الشرعية والاستطابة، فلا يكفي أحدهما عن الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص561–562، تحت عنوان «شرح المفردات: ﴿طيبات﴾ و﴿أحل﴾»","url":""}]},{"id":"s5-438","number":438,"surah":5,"verses":[88],"references":[{"surah":5,"verses":[88]}],"verseLabel":"المائدة: 88","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿واتقوا الله الذي أنتم به مؤمنون﴾؟","answer":"الإيمان بالله يقتضي تقواه في حدوده: فلا يحرم المؤمن ما أحل الله، ولا يتجاوز في المباح. لذلك جاء الأمر بالتقوى ليستنهض الإيمان إلى الامتثال العملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص568، تحت عنوان «اقتران الأمر بالتقوى بالإيمان»","url":""}]},{"id":"s5-439","number":439,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما الفرق بين لغو اليمين واليمين المعقودة في قوله تعالى: ﴿لا يؤاخذكم الله باللغو في أيمانكم ولكن يؤاخذكم بما عقدتم الأيمان﴾؟","answer":"لغو اليمين ما يجري على اللسان من غير قصد عقد اليمين، فلا مؤاخذة به. أما اليمين المعقودة فهي المقصودة بالقلب، وتتعلق المؤاخذة والكفارة بالحنث فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص573–574، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-440","number":440,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما دلالة اختيار فعل ﴿عقدتم﴾ للأيمان؟","answer":"استعار العقد الحسي لربط القلب بالقصد وتوثيق اليمين، كأن الحالف شد على نفسه عهدًا لا ينحل بلا وفاء أو كفارة؛ فهو أبلغ من مجرد النطق بالحلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص578–579، تحت «الاستعارة في تعقيد الأيمان»","url":""}]},{"id":"s5-441","number":441,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما معنى التخيير في قوله تعالى: ﴿أو كسوتهم أو تحرير رقبة﴾؟","answer":"تفيد ﴿أو﴾ أن الإطعام والكسوة والتحرير بدائل متساوية في أصل الإجزاء، فيختار المكفّر واحدًا منها بحسب قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص584–585، تحت عنوان «معنى التخيير في ﴿أو كسوتهم﴾»","url":""}]},{"id":"s5-714","number":714,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"لماذا فُصل الصيام عن خصال الكفارة بقوله تعالى: ﴿فمن لم يجد فصيام ثلاثة أيام﴾؟","answer":"لأن الصيام بدل لا ينتقل إليه إلا من عجز عن الخصال المالية السابقة كلها؛ فاستؤنف به خيار رابع مشروط بعدم الوجدان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص587، تحت عنوان «الفاء الاستئنافية وبيان الخيار الرابع»","url":""}]},{"id":"s5-442","number":442,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما دلالة تقييد الإطعام بقوله تعالى: ﴿من أوسط ما تطعمون أهليكم﴾؟","answer":"قُدّر في التركيب معنى المماثلة، أي إطعامًا مثل أوسط ما تطعمون أهليكم. فربط مقدار الكفارة بعادة المكلف في أهله، بعيدًا عن الإسراف والتقتير.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص583–584، تحت عنوان «بناء عبارة ﴿من أوسط ما تطعمون أهليكم﴾ على التشبيه»","url":""}]},{"id":"s5-443","number":443,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما دلالة قوله تعالى: ﴿فمن لم يجد فصيام ثلاثة أيام﴾ مع عدم ذكر التتابع؟","answer":"ظاهر الآية أطلق صيام الأيام الثلاثة ولم يقيده بالتتابع؛ فاللفظ واللغة لا يوجبان اتصال الأيام، ويجوز من جهتهما أن تكون متتابعة أو متفرقة","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص587، تحت «الفاء الاستئنافية وبيان الخيار الرابع»","url":""}]},{"id":"s5-444","number":444,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما دلالة عودة الإشارة إلى الكفارة في قوله تعالى: ﴿ذلك كفارة أيمانكم﴾؟","answer":"أعادت الإشارة نتيجة التفصيل إلى سببه، فشابهت رد العجز على الصدر وربطت خصال الكفارة بالأيمان التي تقدمت.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص588، تحت عنوان «الإشارة قريبة من رد العجز على الصدر»","url":""}]},{"id":"s5-715","number":715,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما المحذوف في قوله تعالى: ﴿كفارة أيمانكم إذا حلفتم﴾؟","answer":"دل السياق على معطوف محذوف، أي: إذا حلفتم وحنثتم؛ لأن مجرد الحلف لا يوجب الكفارة حتى يقع الحنث.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص588–589، تحت عنوان «حذف المعطوف ﴿حنثتم﴾»","url":""}]},{"id":"s5-445","number":445,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما مناسبة الأمر بقوله تعالى: ﴿واحفظوا أيمانكم﴾ بعد بيان الكفارة؟","answer":"حفظ اليمين يكون بتقليل الحلف، والصدق والوفاء فيما لا معصية فيه، وأداء الكفارة عند الحنث. وجاء الأمر بعد بيان الكفارة حتى لا يتخذها الناس ذريعة للتساهل في الأيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص590، تحت عنوان «معنى حفظ اليمين»","url":""}]},{"id":"s5-446","number":446,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿كذلك يبين الله لكم آياته لعلكم تشكرون﴾؟","answer":"﴿لعل﴾ للرجاء في خطاب الناس: بيّن الله أحكام الأيمان والكفارة لتقوم الحجة ويكون البيان داعيًا إلى شكر النعمة قولًا وعملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص590–591، تحت عنوان «معنى ﴿لعل﴾ في قوله: ﴿لعلكم تشكرون﴾»","url":""}]},{"id":"s5-447","number":447,"surah":5,"verses":[90],"references":[{"surah":5,"verses":[90]}],"verseLabel":"المائدة: 90","question":"لماذا ضُمّت الأنصاب والأزلام إلى الخمر والميسر في السياق؟","answer":"ضُمّت إليها لتأكيد قبح الخمر والميسر؛ إذ قرنهما بما عُرف من شعائر الجاهلية والشرك، ثم خُصّا بعد ذلك بذكر أضرارهما المباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص608–609، تحت عنوان «ضم الأنصاب والأزلام إلى الخمر والميسر؛ تأكيد لقبحهما»","url":""}]},{"id":"s5-448","number":448,"surah":5,"verses":[90],"references":[{"surah":5,"verses":[90]}],"verseLabel":"المائدة: 90","question":"ما أثر القصر في وصف الخمر والميسر والأنصاب والأزلام بأنها ﴿رجس﴾؟","answer":"القصر ادعائي للمبالغة؛ كأن هذه الأشياء لا حقيقة لها إلا الخبث والفساد، فيشتد التنفير منها ويتهيأ الأمر باجتنابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص596، تحت عنوان «قصر ادعائي للمبالغة»","url":""}]},{"id":"s5-716","number":716,"surah":5,"verses":[90],"references":[{"surah":5,"verses":[90]}],"verseLabel":"المائدة: 90","question":"لماذا نُسبت الخمر والميسر والأنصاب والأزلام إلى عمل الشيطان؟","answer":"نسبت إليه مجازًا لعلاقة السببية؛ لأنه يزينها ويدعو إليها، فبيّن التعبير مصدر الإغواء الذي يحمل الناس على تعاطيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص598، تحت عنوان «تعاطي المحرمات أضيف إلى الشيطان كمجاز مرسل علاقته السببية»","url":""}]},{"id":"s5-449","number":449,"surah":5,"verses":[90],"references":[{"surah":5,"verses":[90]}],"verseLabel":"المائدة: 90","question":"ما سرّ إفراد ﴿رجس﴾ مع تعدد الخمر والميسر والأنصاب والأزلام؟","answer":"﴿رجس﴾ مصدر أو اسم جنس يستوي فيه المفرد والجمع، وقد جعلت المذكورات كلها جنسًا واحدًا في الخبث والحكم؛ لذلك صح الإخبار عنها بالمفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص598، تحت «الإخبار عن هذه المحرمات بأنها رجس باللفظ المفرد المعبر عن حقيقتها»","url":""}]},{"id":"s5-450","number":450,"surah":5,"verses":[90],"references":[{"surah":5,"verses":[90]}],"verseLabel":"المائدة: 90","question":"ما دلالة الأمر بقوله تعالى: ﴿فاجتنبوه﴾ بدل: فاتركوه؟","answer":"الاجتناب أبلغ من الترك؛ لأنه يقتضي أن يكون المحرَّم في جانب والإنسان في جانب آخر، فيبتعد عن تعاطيه وعن أسبابه ومجالسه المؤدية إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص601، تحت عنوان «التعبير بالاجتناب أبلغ من التعبير بالترك؛ لأن الاجتناب يقتضي الابتعاد»","url":""}]},{"id":"s5-451","number":451,"surah":5,"verses":[90],"references":[{"surah":5,"verses":[90]}],"verseLabel":"المائدة: 90","question":"إلى ماذا يعود الضمير المفرد في قوله تعالى: ﴿فاجتنبوه﴾؟","answer":"يعود الضمير إلى فعل التعاطي المقدّر؛ أي فاجتنبوا تعاطي الخمر والميسر والأنصاب والأزلام، وهذا يؤكد أن الحكم متعلق بتعاطيها لا بمجرد أعيانها","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص600–601، تحت «الهاء في فاجتنبوه تعود على فعل التعاطي دلالة على أن الحرمة ليست للذات»","url":""}]},{"id":"s5-452","number":452,"surah":5,"verses":[90],"references":[{"surah":5,"verses":[90]}],"verseLabel":"المائدة: 90","question":"ما مناسبة ختم الأمر بالاجتناب بقوله تعالى: ﴿لعلكم تفلحون﴾؟","answer":"جعل الفلاح ثمرة الاجتناب، و﴿لعل﴾ للرجاء؛ فمآل اجتناب هذه المحرمات الصلاح والفوز، ومن لم يجتنب خاب وخسر","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص602، تحت «لفظ لعل فيها رجاء وخبرها جملة تؤكد تجلية ذلك المرجو»","url":""}]},{"id":"s5-453","number":453,"surah":5,"verses":[91],"references":[{"surah":5,"verses":[91]}],"verseLabel":"المائدة: 91","question":"ما دلالة التصدير بـ﴿إنما﴾ في قوله تعالى: ﴿إنما يريد الشيطان أن يوقع بينكم العداوة والبغضاء﴾؟","answer":"تفيد القصر للمبالغة في كشف مقصد الشيطان من تزيين الخمر والميسر؛ فكأن غايته المحصورة إفساد علاقات الناس وصدهم عن طاعة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص606، تحت عنوان «التصدير بـ(إنما) لإفادة الحصر»","url":""}]},{"id":"s5-717","number":717,"surah":5,"verses":[91],"references":[{"surah":5,"verses":[91]}],"verseLabel":"المائدة: 91","question":"ما الفرق بين العداوة والبغضاء في قوله تعالى: ﴿العداوة والبغضاء﴾؟","answer":"العداوة أثر ظاهر يظهر في القول والفعل، أما البغضاء فهي كراهية باطنة في القلب؛ فجمعهما ليصور فساد الظاهر والباطن معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص608–609، تحت عنوان «الفرق المعجمي بين ﴿العداوة﴾ و﴿البغضاء﴾ في الآية»","url":""}]},{"id":"s5-454","number":454,"surah":5,"verses":[91],"references":[{"surah":5,"verses":[91]}],"verseLabel":"المائدة: 91","question":"ما النتيجتان اللتان تذكرهما الآية لتعاطي الخمر والميسر؟","answer":"الأولى إفساد علاقة الناس بإيقاع العداوة والبغضاء بينهم، والثانية إفساد صلتهم بالله بالصد عن ذكره وعن الصلاة؛ فجمعت ضرر المعاملة وضرر العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص610–611، تحت عنوان «نتيجتان أخريان لتعاطي الخمر والميسر»","url":""}]},{"id":"s5-455","number":455,"surah":5,"verses":[91],"references":[{"surah":5,"verses":[91]}],"verseLabel":"المائدة: 91","question":"ما دلالة قوله تعالى: ﴿في الخمر والميسر﴾ دون: بالخمر والميسر؟","answer":"جاءت «في» هنا للسببية والتعليل؛ أي بسبب تعاطي الخمر والميسر. فالتعبير يربط وقوع العداوة والبغضاء بما ينشأ عن تعاطيهما من سكر وخسارة وخصومة، لا بمجرد ظرف مكاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص609–610، تحت «دلالة حرف الجر في على السببية والتعليل في الآية»","url":""}]},{"id":"s5-456","number":456,"surah":5,"verses":[91],"references":[{"surah":5,"verses":[91]}],"verseLabel":"المائدة: 91","question":"ما فائدة إعادة حرف الجر في ﴿عن ذكر الله وعن الصلاة﴾؟","answer":"أعيد حرف الجر لتأكيد الصد عن كل منهما، والتنبيه إلى أهمية الذكر والصلاة، ولا سيما الصلاة التي هي عماد الدين؛ فليس ذكرها أمرًا تابعًا يمر دون عناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص612، تحت «تقديم صد الذكر على الصلاة من باب تقديم الأخص على الأعم»","url":""}]},{"id":"s5-457","number":457,"surah":5,"verses":[91],"references":[{"surah":5,"verses":[91]}],"verseLabel":"المائدة: 91","question":"ما دلالة ختم الآية بالاستفهام: ﴿فهل أنتم منتهون﴾ بدل الأمر المباشر؟","answer":"خرج الاستفهام بـ﴿هل﴾ إلى التحضيض والأمر بالانتهاء، لكنه أبلغ من الأمر المباشر؛ لأنه جاء بعد استيفاء أسباب التحريم فلا يترك جوابًا لائقًا إلا إعلان الانتهاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص613–614، تحت عنوان «خروج (هل) الاستفهامية إلى الأمر؛ للتحضيض على الانتهاء»","url":""}]},{"id":"s5-458","number":458,"surah":5,"verses":[92],"references":[{"surah":5,"verses":[92]}],"verseLabel":"المائدة: 92","question":"ما دلالة تكرار فعل الطاعة في قوله تعالى: ﴿وأطيعوا الله وأطيعوا الرسول﴾؟","answer":"إعادة ﴿أطيعوا﴾ مع الرسول تؤكد استقلال وجوب طاعته فيما يبلغه ويبينه، وفيها تشريف له؛ فطاعته واجبة كما تجب طاعة الله، وهي من طاعة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص618، تحت عنوان «تكرار الفعل مسندًا إلى الرسول من ملمح التوكيد والتشريف له»","url":""}]},{"id":"s5-459","number":459,"surah":5,"verses":[92],"references":[{"surah":5,"verses":[92]}],"verseLabel":"المائدة: 92","question":"ما دلالة قوله تعالى: ﴿واحذروا﴾ مع حذف المحذور؟","answer":"حُذف مفعول ﴿واحذروا﴾ للاهتمام بفعل الحذر نفسه وليعم كل محذور: مخالفة أوامر الله، والرجوع إلى الخمر والميسر، وكل ما يفضي إلى التولي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص620، تحت عنوان «حذف مفعول الفعل ﴿واحذروا﴾؛ للاهتمام بفعل الحذر دون المحذور»","url":""}]},{"id":"s5-460","number":460,"surah":5,"verses":[92],"references":[{"surah":5,"verses":[92]}],"verseLabel":"المائدة: 92","question":"ما دلالة قصر البلاغ على الرسول في قوله تعالى: ﴿إنما على رسولنا البلاغ المبين﴾؟","answer":"قُصر واجبه ﷺ على تبليغ الرسالة وبيانها، وقد أداه؛ فلا يدخل في مسؤوليته إكراه الناس على القبول. وبذلك يحمل المتولي تبعة إعراضه بعد البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص622–623، تحت عنوان «قصر صفة التبليغ والإنذار على الموصوف، وهو الرسول ﷺ»","url":""}]},{"id":"s5-461","number":461,"surah":5,"verses":[92],"references":[{"surah":5,"verses":[92]}],"verseLabel":"المائدة: 92","question":"ما دلالة إضافة الرسول إلى ضمير العظمة في قوله تعالى: ﴿رسولنا﴾؟","answer":"الإضافة إلى ضمير العظمة تشريف للرسول ﷺ وتعظيم لشأنه، وإبراز لعناية الله به؛ فهو يبلغ عن الله، والتولي عن أمره تولٍّ عما أُرسل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص623، تحت «أضاف الضمير نا إلى الرسول تشريفًا وفيه مخالفة مقتضى الظاهر»","url":""}]},{"id":"s5-462","number":462,"surah":5,"verses":[92],"references":[{"surah":5,"verses":[92]}],"verseLabel":"المائدة: 92","question":"ما دلالة وصف البلاغ بأنه ﴿المبين﴾؟","answer":"المبين هو الواضح في نفسه والمظهر لما يحتاج الناس إلى معرفته؛ فنفى الوصف أن يكون توليهم ناشئًا من غموض الرسالة، وأقام عليهم الحجة بعد تمام البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص622–623، تحت «زيادة وصف المبين كي لا تبقى حجة يتحجج بها المبلغون»","url":""}]},{"id":"s5-463","number":463,"surah":5,"verses":[92],"references":[{"surah":5,"verses":[92]},{"surah":64,"verses":[12]}],"verseLabel":"المائدة: 92؛ التغابن: 12","question":"ما سرّ زيادة ﴿واحذروا﴾ و﴿فاعلموا﴾ في المائدة، وعدم ذكرهما في الآية المشابهة من التغابن؟","answer":"جاءت المائدة عقب تحريم الخمر والميسر، فناسب المقام زيادة التحذير والأمر بالعلم بما على الرسول من البلاغ. أما التغابن فجاء الأمر بالطاعة بعد بيان أن المصيبة بإذن الله وهداية قلب المؤمن؛ فاختلف السياق، ولم يحتج إلى هاتين الزيادتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص624، تحت «تعقيب فعل الطاعة بفعل الحذر في قوله واحذروا لتحقيق التهديد بما يشعر بالوعيد»","url":""}]},{"id":"s5-464","number":464,"surah":5,"verses":[93],"references":[{"surah":5,"verses":[93]}],"verseLabel":"المائدة: 93","question":"لماذا عُبر عن رفع الإثم بقوله تعالى: ﴿ليس على الذين آمنوا وعملوا الصالحات جناح﴾؟","answer":"نفي الجناح كناية شائعة عن نفي الإثم والحرج؛ فرفع المؤاخذة عمن تناول قبل التحريم ما كان مباحًا ثم اتقى بعد البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص629–630، تحت عنوان «نفي الإثم والحرج بطريقة نفي الجناح»","url":""}]},{"id":"s5-718","number":718,"surah":5,"verses":[93],"references":[{"surah":5,"verses":[93]}],"verseLabel":"المائدة: 93","question":"لماذا عبّر بـ﴿طعموا﴾ في قوله تعالى: ﴿فيما طعموا﴾؟","answer":"أرجع التعبير معنى الطعام إلى التلذذ، فشمل الأكل والشرب؛ ولذلك صح استعماله في الخمر وما تناوله المؤمنون قبل التحريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص631، تحت عنوان «التعبير بـ﴿طعموا﴾؛ لأنه أرجع معنى الطعم إلى التلذذ أكلًا وشربًا»","url":""}]},{"id":"s5-465","number":465,"surah":5,"verses":[93],"references":[{"surah":5,"verses":[93]}],"verseLabel":"المائدة: 93","question":"ما دلالة تكرار التقوى وتدرج الأوصاف في قوله تعالى: ﴿إذا ما اتقوا وآمنوا وعملوا الصالحات ثم اتقوا وآمنوا ثم اتقوا وأحسنوا﴾؟","answer":"ليس التكرار حشوًا، بل يصور سياقًا متدرجًا: تقوى تصحب الإيمان والعمل الصالح، ثم ثبات على التقوى والإيمان، ثم ارتقاء إلى الإحسان. و﴿ثم﴾ تنقل بين هذه المراتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص633–634، تحت عنوان «التقوى، والإيمان، والعمل الصالح سياق متدرج، وليس من المتشابه»","url":""}]},{"id":"s5-466","number":466,"surah":5,"verses":[93],"references":[{"surah":5,"verses":[93]}],"verseLabel":"المائدة: 93","question":"ما دلالة ختم التدرج بالإحسان في قوله تعالى: ﴿ثم اتقوا وأحسنوا﴾؟","answer":"الإحسان مرتبة يتجاوز فيها المؤمن مجرد ترك الحرام إلى إتقان الطاعة وفعل الخير ومراقبة الله؛ فناسب أن يكون غاية التدرج بعد الإيمان والتقوى والعمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص635، تحت «تذييل الآية بالإحسان لأنه أمر زائد على التقوى»","url":""}]},{"id":"s5-467","number":467,"surah":5,"verses":[93],"references":[{"surah":5,"verses":[93]}],"verseLabel":"المائدة: 93","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله يحب المحسنين﴾؟","answer":"لما انتهى التدرج إلى الإحسان خُتم بالجزاء الموافق له، وهو محبة الله؛ فدل التذييل على أن الإحسان مرتبة زائدة على مجرد التقوى، ورغّب في بلوغها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص635، تحت عنوان «تذييل الآية بالإحسان؛ لأنه أمر زائد على التقوى»","url":""}]},{"id":"s5-468","number":468,"surah":5,"verses":[94],"references":[{"surah":5,"verses":[94]}],"verseLabel":"المائدة: 94","question":"ما دلالة وصف الابتلاء بقوله تعالى: ﴿بشيء من الصيد﴾؟","answer":"التنكير والتبعيض في ﴿بشيء﴾ يشعران بقلة ما وقع به الابتلاء وخفته؛ فهو بعض الصيد وفي حال مخصوصة، ومع ذلك يكشف صدق الطاعة من ضعفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص641–642، تحت عنوان «التعبير بـ﴿شيء﴾ يوحي بالتقليل أو التبعيض، وله غرض وهدف»","url":""}]},{"id":"s5-469","number":469,"surah":5,"verses":[94],"references":[{"surah":5,"verses":[94]}],"verseLabel":"المائدة: 94","question":"ما البلاغة في التعبير بالرماح في قوله تعالى: ﴿تناله أيديكم ورماحكم﴾؟","answer":"ذُكرت الرماح وهي بعض أدوات الصيد وأريد بها مجموع آلاته؛ فهو مجاز مرسل علاقته الجزئية، ويقابل ما تناله الأيدي من الصيد القريب والصغير بما تدركه الآلات من البعيد والكبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص644، تحت عنوان «التعبير بالرماح هو تعبير بالجزء عن الكل»","url":""}]},{"id":"s5-470","number":470,"surah":5,"verses":[94],"references":[{"surah":5,"verses":[94]}],"verseLabel":"المائدة: 94","question":"كيف نفهم قوله تعالى: ﴿ليعلم الله من يخافه بالغيب﴾ مع سبق علم الله بكل شيء؟","answer":"لا يدل على تجدد علم الله؛ فعلمه لم يزل ولا يزال، وإنما عُبِّر بهذه الصيغة تقريبًا لأفهام المخاطبين، وقيل التقدير: ليعلم أولياء الله من يخافه بالغيب","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص646، تحت «ليعلم الله من يخافه بالغيب على حذف مضاف تقديره ليعلم أولياء الله»","url":""}]},{"id":"s5-471","number":471,"surah":5,"verses":[94],"references":[{"surah":5,"verses":[94]}],"verseLabel":"المائدة: 94","question":"ما دلالة التعبير عن الطاعة في الخلوة بقوله تعالى: ﴿يخافه بالغيب﴾؟","answer":"الجملة تعليل للابتلاء؛ أي ليظهر في الواقع من يراقب الله في الخلوة فيمتنع عن الصيد مع قدرته عليه، لا خوفًا من رقابة الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص645–646، تحت عنوان «جملة ﴿ليعلم الله من يخافه بالغيب﴾ تعليل لما سبق من الابتلاء»","url":""}]},{"id":"s5-472","number":472,"surah":5,"verses":[94],"references":[{"surah":5,"verses":[94]}],"verseLabel":"المائدة: 94","question":"ما دلالة الفاء في قوله تعالى: ﴿فمن اعتدى بعد ذلك فله عذاب أليم﴾؟","answer":"الفاء الثانية رابطة لجواب الشرط، فرتبت استحقاق العذاب على الاعتداء بعد البيان؛ وفي هذا الربط تشديد للوعيد وبيان مباشر لعاقبة المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص647، تحت عنوان «الفاء واقعة في جواب شرط؛ لأن العذاب مترتب على الاعتداء»","url":""}]},{"id":"s5-473","number":473,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما سر التعبير بالقتل دون الذبح في ﴿لا تقتلوا الصيد وأنتم حرم﴾؟","answer":"القتل أعم من الذبح؛ فيشمل إزهاق روح الصيد بالسهم والحجر والجوارح وغيرها. فاختير اللفظ الأوسع ليستوعب صور الاعتداء على الصيد حال الإحرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص660، تحت عنوان «دلالة استعمال لفظ ﴿القتل﴾ لا لفظ ﴿الذبح﴾ في الآية»","url":""}]},{"id":"s5-474","number":474,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما معنى الحال ﴿متعمدًا﴾ في وصف قاتل الصيد؟","answer":"تصور الحال من قصد قتل الصيد وهو ذاكر لإحرامه؛ فالتعمد عقد القصد إلى الفعل. وبذلك يبرز النص صورة الاعتداء المقصود على حرمة الإحرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص662–663، تحت «الدلالة على الحالية في اسم الفاعل متعمدًا»","url":""}]},{"id":"s5-475","number":475,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما الفرق بين كاف التشبيه ولفظ ﴿مثل﴾ في قوله تعالى: ﴿فجزاء مثل ما قتل من النعم﴾؟","answer":"الكاف تجعل المشبه في حكم المنفصل عن المشبه به، أما ﴿مثل﴾ فهي اسم يدل على المماثلة نفسها ويقبل الإضافة والوصف. واختيار ﴿مثل﴾ يجعل مقدار الجزاء مماثلًا لما قتل على الوجه الذي يقدره الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص664، تحت عنوان «الفرق بين كاف التشبيه وبين المثل»","url":""}]},{"id":"s5-476","number":476,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما دلالة اشتراط أن يحكم بالمثل ﴿ذوا عدل منكم﴾؟","answer":"لأن تقدير المماثلة قد يختلف باختلاف الصيد، فاحتاج إلى اثنين يجمعان الخبرة والعدالة حتى يبتعد الحكم عن هوى الجاني أو اجتهاد الفرد المنفرد، ويطمأن إلى تقديره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص665–666، تحت «إضافة النكرة إلى النكرة يفيد التخصيص في قوله ذوا عدل»","url":""}]},{"id":"s5-477","number":477,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما الأوجه الإعرابية في قوله تعالى: ﴿هديًا بالغ الكعبة﴾، وما دلالتها؟","answer":"يجوز نصب ﴿هديًا﴾ على الحال، أو على المصدر، أو على التمييز؛ وعلى هذه الأوجه يتأكد أن الجزاء يُهدى إلى الحرم ويبلغ موضعه المشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص666، تحت عنوان «دلالة قوله تعالى: ﴿هديًا بالغ الكعبة﴾ بين الحالية والمصدرية والتمييز»","url":""}]},{"id":"s5-719","number":719,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما البلاغة في قوله تعالى: ﴿بالغ الكعبة﴾؟","answer":"التقدير: بالغ حرم الكعبة؛ فحُذف المضاف وأقيمت الكعبة مقامه، تشريفًا لها وإيجازًا مع وضوح المراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص666–667، تحت عنوان «بلاغة الحذف في قوله: ﴿هديًا بالغ الكعبة﴾»","url":""}]},{"id":"s5-478","number":478,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما دلالة العطف بـ﴿أو﴾ في قوله تعالى: ﴿أو كفارة طعام مساكين﴾؟","answer":"عطفت الكفارة على جزاء الصيد لتبين بدلًا آخر، وهو إطعام المساكين بقيمة ما يقابل الصيد؛ وفي ﴿أو﴾ معنى الانتقال بين البدائل المشروعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص667–668، تحت عنوان «معنى العطف في ﴿أو كفارة طعام مساكين﴾»","url":""}]},{"id":"s5-720","number":720,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما دلالة ﴿أو﴾ في قوله تعالى: ﴿أو عدل ذلك صيامًا﴾؟","answer":"تفيد التخيير عند طائفة من أهل العلم، وقيل تحمل على ترتيب البدائل بحسب الاستطاعة؛ وعلى الوجهين جعل الصيام مقابلًا لما يعادل الطعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص669، تحت عنوان «التخيير بـ﴿أو﴾ في قوله: ﴿أو عدل ذلك صيامًا﴾»","url":""}]},{"id":"s5-479","number":479,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما الإيجاز بالحذف في قوله تعالى: ﴿ليذوق وبال أمره﴾؟","answer":"من توجيهات العبارة أن الضمير يعود إلى الله، والتقدير: ليذوق وبال مخالفة أمر الله؛ فحُذف المضاف لدلالة السياق عليه. فالوبال مترتب على المخالفة، لا على أمر الله نفسه، وفي الإيجاز تشديد للزجر عن الاعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص670–671، تحت «دلالة الإيجاز بالحذف في قوله ليذوق وبال أمره»","url":""}]},{"id":"s5-480","number":480,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما دلالة المضي في قوله تعالى: ﴿عفا الله عما سلف﴾؟","answer":"يتعلق العفو بما وقع قبل ورود التحريم والبيان، فأسقط الله المؤاخذة عما مضى حين لم يكن الحكم قد بلغهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص671، تحت عنوان «المعنى الدلالي للمضي في قوله: ﴿عفا الله عما سلف﴾»","url":""}]},{"id":"s5-721","number":721,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما دلالة العود في قوله تعالى: ﴿ومن عاد فينتقم الله منه﴾؟","answer":"العود هو تكرار الاعتداء بعد ورود الحكم والعفو عما سبق؛ فمن رجع إلى المخالفة بعد العلم استحق الوعيد بالانتقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص672–673، تحت عنوان «دلالة العود في قوله: ﴿ومن عاد فينتقم الله منه﴾»","url":""}]},{"id":"s5-481","number":481,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله عزيز ذو انتقام﴾؟","answer":"قُدّم ﴿عزيز﴾ لأن الانتقام يترتب على القدرة والغلبة؛ فالله غالب لا يفوته المعتدي، ثم جاء ﴿ذو انتقام﴾ ليبين أثر تلك العزة في مجازاة من عاد بعد العفو والبيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص674، تحت عنوان «تقديم وصف ﴿عزيز﴾ على ﴿ذو انتقام﴾؛ لترتب الثانية على الأولى»","url":""}]},{"id":"s5-482","number":482,"surah":5,"verses":[96],"references":[{"surah":5,"verses":[96]}],"verseLabel":"المائدة: 96","question":"ما الفرق بين ﴿صيد البحر﴾ و﴿طعامه﴾ في قوله تعالى: ﴿أحل لكم صيد البحر وطعامه﴾؟","answer":"في ﴿طعامه﴾ وجهان: أن يعود الضمير إلى الصيد، أي أُبيح صيد البحر وأكل صيده؛ أو يعود إلى البحر، فيراد ما يُتخذ منه طعامًا، ومنه السمك المملح المدخر للمسافرين؛ فعطف الطعام يبين عموم الانتفاع","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص679، تحت عنوان «تعويض المحذوف بالضمير»","url":""}]},{"id":"s5-483","number":483,"surah":5,"verses":[96],"references":[{"surah":5,"verses":[96]}],"verseLabel":"المائدة: 96","question":"ما وجه اللف والنشر في ﴿أحل لكم صيد البحر وطعامه متاعًا لكم وللسيارة﴾؟","answer":"ذُكر صيد البحر وطعامه أولًا، ثم بُين الانتفاع بهما للمقيمين والمسافرين. ومن توجيهاته أن الطري للمقيمين، والطعام المملح المدخر للمسافرين؛ ففُصل بعد الإجمال ما يناسب كل فريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص680–681، تحت «أسلوب اللف والنشر»","url":""}]},{"id":"s5-484","number":484,"surah":5,"verses":[96],"references":[{"surah":5,"verses":[96]}],"verseLabel":"المائدة: 96","question":"ما دلالة المقابلة بين حل صيد البحر وتحريم صيد البر؟","answer":"أظهرت المقابلة اختلاف الحكمين حال الإحرام: أُبيح صيد البحر وطعامه توسعةً، وحُرم صيد البر ما داموا حرمًا حمايةً للصيد البري؛ فبرز الحكم بضده.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص680–681، تحت عنوان «دلالة المقابلة»","url":""}]},{"id":"s5-485","number":485,"surah":5,"verses":[1,96],"references":[{"surah":5,"verses":[1,96]}],"verseLabel":"المائدة: 1، 96","question":"ما مناسبة إعادة قيد ﴿ما دمتم حرمًا﴾ في تحريم صيد البر؟","answer":"أعيد القيد لتوكيد أن تحريم صيد البر مؤقت بمدة الإحرام، وأن المنع يزول بانتهاء المناسك، وفي مقابل إطلاق إباحة صيد البحر","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص681، تحت «زيادة توكيد التحريم»","url":""}]},{"id":"s5-486","number":486,"surah":5,"verses":[96],"references":[{"surah":5,"verses":[96]}],"verseLabel":"المائدة: 96","question":"ما موقع الواو في قوله تعالى: ﴿واتقوا الله الذي إليه تحشرون﴾؟","answer":"تحتمل الواو العطف على ما سبق، فيتصل الأمر بالتقوى بأحكام الصيد، وتحتمل الاستئناف لافتتاح توجيه جامع بعد بيان الحكم. وعلى الوجهين تربط التقوى بالامتثال لما شرعه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص682، تحت عنوان «الواو في ﴿واتقوا الله﴾ بين الاستئناف والعطف»","url":""}]},{"id":"s5-722","number":722,"surah":5,"verses":[96],"references":[{"surah":5,"verses":[96]}],"verseLabel":"المائدة: 96","question":"ما دلالة بناء ﴿تُحشرون﴾ للمفعول؟","answer":"بُني الفعل للمفعول لأن المقصود تقرير وقوع الحشر نفسه وعمومه، لا تسمية من يتولى جمع الخلق؛ فكلهم يُجمعون إلى الله للحساب والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص682، تحت عنوان «التعبير بالبناء للمفعول في ﴿تحشرون﴾»","url":""}]},{"id":"s5-487","number":487,"surah":5,"verses":[97],"references":[{"surah":5,"verses":[97]}],"verseLabel":"المائدة: 97","question":"ما معنى جعل الكعبة ﴿قيامًا للناس﴾ في قوله تعالى: ﴿جعل الله الكعبة البيت الحرام قيامًا للناس﴾؟","answer":"أي جعلها ما تقوم به مصالح دينهم ودنياهم: قبلةً وموضع حج وعبادة، وأمنًا يجتمعون عنده، وسببًا لتعارفهم وتجارتهم. و﴿قيامًا﴾ يصورها دعامة تنتظم بها شؤونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص685–686، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-488","number":488,"surah":5,"verses":[97],"references":[{"surah":5,"verses":[97]}],"verseLabel":"المائدة: 97","question":"ما دلالة تعريف ﴿الشهر الحرام﴾ في قوله تعالى: ﴿والشهر الحرام﴾؟","answer":"تفيد أل العهد؛ أي الجنس المعروف من الأشهر الحرم التي عظّمها الله وجعل حرمتها سببًا لأمن الناس وانتظام مصالحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص688، تحت عنوان «الألف واللام في ﴿والشهر الحرام﴾»","url":""}]},{"id":"s5-723","number":723,"surah":5,"verses":[97],"references":[{"surah":5,"verses":[97]}],"verseLabel":"المائدة: 97","question":"ما مناسبة عطف ﴿الهدي والقلائد﴾ على الكعبة والشهر الحرام؟","answer":"لأن قيام مصالح الناس لا يتم بالمكان والزمان وحدهما؛ فالهدي شعيرة تصل إلى الحرم، والقلائد علامة تصونه في الطريق، فانتظمت عناصر الأمن والنسك في سياق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص688–689، تحت عنوان «عطف لفظي: ﴿والهدي والقلائد﴾»","url":""}]},{"id":"s5-724","number":724,"surah":5,"verses":[97],"references":[{"surah":5,"verses":[97]}],"verseLabel":"المائدة: 97","question":"لماذا قُدِّمت الكعبة على الشهر الحرام والهدي والقلائد؟","answer":"قُدِّمت لأنها الأصل الجامع لهذه الشعائر والمكان الذي تتجه إليه؛ ثم ذُكر الزمن وما يُهدى إليها وما يميزه، فجاء الترتيب من الأصل إلى ما يتعلق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص690، تحت عنوان «علة تقديم الكعبة»","url":""}]},{"id":"s5-489","number":489,"surah":5,"verses":[2,97],"references":[{"surah":5,"verses":[2,97]}],"verseLabel":"المائدة: 2، 97","question":"ما فائدة تخصيص الهدي والقلائد بالذكر بعد عموم الشعائر في قوله تعالى: ﴿ولا الهدي ولا القلائد﴾؟","answer":"خُصا بالذكر بعد عموم شعائر الله لمزيد العناية بحرمتهما؛ فالهدي شعيرة ظاهرة، والقلائد علامة أمانه، وفي تخصيصهما تشديد للنهي عن التعرض لهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص511–512، تحت عنوان «التخصيص بعد التعميم، في قوله: ﴿ولا الهدي ولا القلائد﴾»","url":""}]},{"id":"s5-490","number":490,"surah":5,"verses":[97],"references":[{"surah":5,"verses":[97]}],"verseLabel":"المائدة: 97","question":"ما دلالة اسم الإشارة في قوله تعالى: ﴿ذلك لتعلموا أن الله يعلم ما في السماوات وما في الأرض﴾؟","answer":"يشير ﴿ذلك﴾ إلى ما تقدم من جعل الكعبة والشهر الحرام والهدي والقلائد قيامًا للناس؛ فهذه المصالح المحكمة دليل على علم الله المحيط بحاجات خلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص690–691، تحت عنوان «دلالة اسم الإشارة»","url":""}]},{"id":"s5-491","number":491,"surah":5,"verses":[97],"references":[{"surah":5,"verses":[97]}],"verseLabel":"المائدة: 97","question":"ما دلالة الجمع بين قوله تعالى: ﴿يعلم ما في السماوات وما في الأرض﴾ وقوله: ﴿وأن الله بكل شيء عليم﴾؟","answer":"الأول يصرح بإحاطة علمه بأعظم عالمي الخلق وما فيهما، ثم جاء العام ﴿بكل شيء عليم﴾ ليمنع توهم اختصاص العلم بهما أو ببعض ما فيهما، ويقرر القاعدة الشاملة بعد المثال الواسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص693–694، تحت عنوان «تذييل الآية»","url":""}]},{"id":"s5-492","number":492,"surah":5,"verses":[98],"references":[{"surah":5,"verses":[98]}],"verseLabel":"المائدة: 98","question":"ما دلالة الجمع بين شدة العقاب والمغفرة والرحمة؟","answer":"يجمع مقام الإيمان بين الخوف والرجاء؛ فذُكر العقاب، ثم خُتم بوصفَي المغفرة والرحمة فتحًا لباب الإنابة","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص699، تحت عنوان «ورود التعبير بأنه غفور رحيم بعد العقاب الشديد»","url":""}]},{"id":"s5-493","number":493,"surah":5,"verses":[98],"references":[{"surah":5,"verses":[98]}],"verseLabel":"المائدة: 98","question":"ما سرّ تقديم ﴿شديد العقاب﴾ على ﴿غفور رحيم﴾؟","answer":"من توجيهاته أن الآية بدأت بالعقاب ثم انتهت بالمغفرة والرحمة، فيبقى ختام الرجاء حاضرًا في النفس. وقد جمع الختام وصفين للمغفرة والرحمة بعد وصف العقاب، تأكيدًا لسعة باب الإنابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص699، تحت «تقديم العقاب على المغفرة والرحمة إيذان بالعفو والغفران»","url":""}]},{"id":"s5-494","number":494,"surah":5,"verses":[98],"references":[{"surah":5,"verses":[98]}],"verseLabel":"المائدة: 98","question":"ما دلالة اختيار ﴿غفور رحيم﴾ بدل غافر راحم؟","answer":"الصيغتان أبلغ في الدلالة على كثرة المغفرة والرحمة من اسمي الفاعل، فهما تقويان جانب الرجاء بعد ذكر شدة العقاب، مع بقاء الخوف والرجاء متلازمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص698–699، تحت «صيغتا المبالغة غفور رحيم أقوى من اسم الفاعل غافر راحم»","url":""}]},{"id":"s5-495","number":495,"surah":5,"verses":[99],"references":[{"surah":5,"verses":[99]}],"verseLabel":"المائدة: 99","question":"ما دلالة القصر في قوله تعالى: ﴿ما على الرسول إلا البلاغ﴾؟","answer":"حصر واجب الرسول ﷺ في إيصال الرسالة، فلا يملك إجبار القلوب على الإيمان ولا يحمل وزر من أعرض بعد البيان؛ وفي الوقت نفسه يحمل المخاطبين مسؤولية الاستجابة لأن الحجة قد بلغتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص703–704، تحت عنوان «البلاغ مقصور من باب قصر الصفة على الموصوف»","url":""}]},{"id":"s5-496","number":496,"surah":5,"verses":[92,99],"references":[{"surah":5,"verses":[92,99]}],"verseLabel":"المائدة: 92، 99","question":"ما سرّ الاقتصار على ﴿البلاغ﴾ هنا، ووصفه في الآية 92 بأنه ﴿البلاغ المبين﴾؟","answer":"في الآية 92 جاء ذكر البلاغ المبين عقب الأمر بالطاعة والتحذير من التولي؛ فوُصف بالمبين لقطع الاعتراض وإلزام المخاطبين الحجة والبرهان. أما هنا فالمقام حصر مهمة الرسول في البلاغ، وعُرّف البلاغ بأل العهدية؛ أي البلاغ المعهود المعروف، وهو شرائع الإسلام","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص622–623، تحت عنوان «زيادة وصف ﴿المبين﴾ كي لا تبقى حجة يتحجج بها المبلَّغون»","url":""}]},{"id":"s5-497","number":497,"surah":5,"verses":[99],"references":[{"surah":5,"verses":[99]}],"verseLabel":"المائدة: 99","question":"ما سرّ تقديم ما يُبدى على ما يُكتم في قوله تعالى: ﴿والله يعلم ما تبدون وما تكتمون﴾؟","answer":"قُدّم ما تبدون لأن الإنسان بطبعه يُظهر كلامه أولًا، ثم قد يكتم ما لا يريد إظهاره؛ فناسب الترتيبُ طبيعةَ الإبداء ثم الكتمان، وجُمع الطرفان لإفادة إحاطة علم الله بالظاهر والباطن","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص706، تحت «علة تقديم قوله ما تبدون على قوله وما تكتمون»","url":""}]},{"id":"s5-498","number":498,"surah":5,"verses":[100],"references":[{"surah":5,"verses":[100]}],"verseLabel":"المائدة: 100","question":"ما الاستعارة في قوله تعالى: ﴿لا يستوي الخبيث والطيب﴾؟","answer":"استعير الخبيث والطيب لكل باطل وحق أو محرم وحلال، فانتقل الوصفان من المحسوسات إلى الاعتقاد والقول والعمل والكسب؛ لتقرير أن الحقائق لا تتساوى وإن تشابهت مظاهرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص711–712، تحت عنوان «الاستعارة التصريحية»","url":""}]},{"id":"s5-499","number":499,"surah":5,"verses":[100],"references":[{"surah":5,"verses":[100]}],"verseLabel":"المائدة: 100","question":"ما سرّ تقديم ﴿الخبيث﴾ على ﴿الطيب﴾؟","answer":"لأن السياق يحذر من الاغترار بكثرة الخبيث، فبدأ به ليضع موضع الفتنة أمام السامع ثم نفى مساواته بالطيب؛ وبذلك مهد لقوله: ﴿ولو أعجبك كثرة الخبيث﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص712–713، تحت عنوان «التقديم بما يلائم السياق البعدي للآية»","url":""}]},{"id":"s5-500","number":500,"surah":5,"verses":[100],"references":[{"surah":5,"verses":[100]}],"verseLabel":"المائدة: 100","question":"ما دلالة الأسلوب الشرطي في قوله تعالى: ﴿ولو أعجبك كثرة الخبيث﴾؟","answer":"تفيد ﴿لو﴾ أن الحكم ثابت حتى في أشد أحوال الإعجاب بالكثرة؛ فلا يستوي الخبيث والطيب ولو بلغ الخبيث من الوفرة ما يلفت النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص713–714، تحت عنوان «﴿ولو أعجبك كثرة الخبيث﴾ أسلوب يفيد الشرط»","url":""}]},{"id":"s5-725","number":725,"surah":5,"verses":[100],"references":[{"surah":5,"verses":[100]}],"verseLabel":"المائدة: 100","question":"ما المجاز في قوله تعالى: ﴿فاتقوا الله﴾؟","answer":"المراد اتقاء سخط الله وعذابه بامتثال أوامره واجتناب نواهيه؛ فحُذف المضاف وأقيم اسم الجلالة مقامه تعظيمًا للأمر واستحضارًا للمراقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص714–715، تحت عنوان «المجاز في قوله: ﴿فاتقوا الله﴾»","url":""}]},{"id":"s5-501","number":501,"surah":5,"verses":[100],"references":[{"surah":5,"verses":[100]}],"verseLabel":"المائدة: 100","question":"ما سرّ ذكر ﴿كثرة الخبيث﴾ دون وصف الطيب بالكثرة؟","answer":"ذُكرت كثرة الخبيث لأن المقصود إبطال الاغترار بها؛ فالعبرة بالجودة والرداءة لا بالقلة والكثرة، والمحمود القليل خير من المذموم الكثير","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص710، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-502","number":502,"surah":5,"verses":[100],"references":[{"surah":5,"verses":[100]}],"verseLabel":"المائدة: 100","question":"ما دلالة الفاء في قوله تعالى: ﴿فاتقوا الله يا أولي الألباب﴾؟","answer":"الفاء فصيحة تفصح عن نتيجة ما قبلها: إذا تقرر أن الخبيث لا يستوي بالطيب فلا تغتروا بالكثرة، بل اتقوا الله واختاروا الطيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص714، تحت عنوان «البدء بالفاء الفصيحة»","url":""}]},{"id":"s5-726","number":726,"surah":5,"verses":[100],"references":[{"surah":5,"verses":[100]}],"verseLabel":"المائدة: 100","question":"ما دلالة ﴿لعلكم تفلحون﴾ في ختام الآية؟","answer":"جاء الترجي في خطاب العباد للتعليل والحث؛ أي اتقوا الله رجاء الفلاح، فالتقوى طريق النجاة ونيل المطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص715، تحت عنوان «﴿لعلكم﴾ لفظ يفيد الترجي وقد يرد للتعليل»","url":""}]},{"id":"s5-503","number":503,"surah":5,"verses":[101],"references":[{"surah":5,"verses":[101]}],"verseLabel":"المائدة: 101","question":"ما دلالة النهي بقوله تعالى: ﴿لا تسألوا عن أشياء إن تبد لكم تسؤكم﴾؟","answer":"خرج النهي عن معناه الأصلي إلى النصح والإرشاد: لا تتكلفوا أسئلة لا حاجة إليها إذا كان كشف جوابها يجلب حرجًا أو تكليفًا، أما سؤال التعلم والحاجة فمشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص719–720، تحت عنوان «خروج الفعل ﴿لا تسألوا﴾ عن معناه الحقيقي إلى النصح والإرشاد»","url":""}]},{"id":"s5-504","number":504,"surah":5,"verses":[101],"references":[{"surah":5,"verses":[101]}],"verseLabel":"المائدة: 101","question":"ما دلالة تنكير ﴿أشياء﴾ وعدم تحديدها؟","answer":"نُكرت ﴿أشياء﴾ لتفيد العموم في أشياء غير محددة، فلا ينحصر النهي في الوقائع التي نزلت بسببها الآية، بل يشمل كل سؤال تتعلق بإبداء جوابه مساءة أو مشقة","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص721، تحت «سر تنكير لفظة أشياء لكونها للعموم لا للحصر»","url":""}]},{"id":"s5-505","number":505,"surah":5,"verses":[101],"references":[{"surah":5,"verses":[101]}],"verseLabel":"المائدة: 101","question":"ما دلالة بناء ﴿إن تبد لكم﴾ للمفعول؟","answer":"يبرز ما قد ينشأ عن إظهار تلك الأشياء من مساءة من غير تعلق الغرض بتعيين من يظهرها؛ وفيه إبقاء للأمر عامًا وإيجاز بحذف الفاعل، موافقًا لسياق النهي عن السؤال المؤدي إلى الحرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص722–723، تحت «انسجام الفعل المبني للمفعول مع السياق»","url":""}]},{"id":"s5-506","number":506,"surah":5,"verses":[101],"references":[{"surah":5,"verses":[101]}],"verseLabel":"المائدة: 101","question":"ما دلالة تقييد السؤال بقوله تعالى: ﴿حين ينزل القرآن﴾؟","answer":"قُيد السؤال بزمن نزول القرآن لأن السؤال آنذاك قد يستدعي جوابًا وحيًا يصير حكمًا ظاهرًا لازمًا بعد أن كان مسكوتًا عنه؛ لذلك كان التكلف في ذلك الزمن أشد أثرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص725، تحت عنوان «﴿حين﴾ ظرف يدل على زمن نزول القرآن»","url":""}]},{"id":"s5-507","number":507,"surah":5,"verses":[101],"references":[{"surah":5,"verses":[101]}],"verseLabel":"المائدة: 101","question":"ما دلالة قوله تعالى بعد النهي: ﴿عفا الله عنها﴾؟","answer":"يحتمل أن المعنى: عفا الله عما سلف من أسئلتكم، ويحتمل أنه سكت عن تلك الأشياء فلم يكلفكم بها؛ وعلى الوجهين تبني الجملة أدبًا قوامه قبول عفو الله وعدم تتبع ما ستره أو تركه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص727–728، تحت «جملة عفا الله عنها بمعنى لا تسألوا عما هو معفو عنه»","url":""}]},{"id":"s5-508","number":508,"surah":5,"verses":[101],"references":[{"surah":5,"verses":[101]}],"verseLabel":"المائدة: 101","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله غفور حليم﴾ دون: غفور رحيم؟","answer":"الغفور يستر ما سلف من خطئهم، والحليم لا يعاجل بالعقوبة من أساء السؤال أو تجاوز الأدب، بل يمهله ليعود؛ فالحلم أنسب بمقام النهي عن التعنت بعد ذكر العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص728، تحت عنوان «﴿والله غفور حليم﴾ تذييل لما سبق وتوكيد للعفو»","url":""}]},{"id":"s5-509","number":509,"surah":5,"verses":[102],"references":[{"surah":5,"verses":[102]}],"verseLabel":"المائدة: 102","question":"ما صلة قوله تعالى: ﴿قد سألها قوم من قبلكم﴾ بالنهي عن السؤال؟","answer":"جاءت الجملة استئنافًا تحذيريًا يذكر شاهدًا من التاريخ: أقوام سألوا مثل تلك المسائل ثم لم يمتثلوا، فبيّن المثال عاقبة التعنت وأكد حكمة النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص731–732، تحت عنوان «جملة ﴿قد سألها قوم﴾ استئنافية ومرتبطة بما قبلها»","url":""}]},{"id":"s5-510","number":510,"surah":5,"verses":[102],"references":[{"surah":5,"verses":[102]}],"verseLabel":"المائدة: 102","question":"ما سرّ عود الضمير المؤنث المفرد في ﴿سألها﴾ إلى ﴿أشياء﴾؟","answer":"عاد الضمير إلى لفظ ﴿أشياء﴾ دون مدلوله، أو على تقدير مضاف: قد سأل قوم من قبلكم أمثالها؛ لأن مسائلهم لم تكن عين الأشياء المنهي عن سؤالها هنا، بل كانت من نوعها","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص734–735، تحت «أسلوب عود الضمير على غير الظاهر بعد التكرار»","url":""}]},{"id":"s5-511","number":511,"surah":5,"verses":[102],"references":[{"surah":5,"verses":[102]}],"verseLabel":"المائدة: 102","question":"ما دلالة ﴿أصبحوا﴾ في قوله تعالى: ﴿ثم أصبحوا بها كافرين﴾؟","answer":"جاءت بمعنى صاروا، فصورت انتقالهم إلى حال الكفر بعد السؤال، ولا يلزم أن تكون الصيرورة في وقت الصباح.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص736، تحت عنوان «التعبير عن الصيرورة بالإصباح»","url":""}]},{"id":"s5-512","number":512,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"ما دلالة دخول ﴿ما﴾ النافية على الماضي في قوله تعالى: ﴿ما جعل الله﴾؟","answer":"ينفي الأسلوب أن يكون هذا التشريع قد صدر عن الله في أي وقت مضى، فيبطل نسبة عادات الجاهلية إليه من أصلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص741، تحت عنوان «دلالة دخول ﴿ما﴾ النافية على الفعل الماضي»","url":""}]},{"id":"s5-727","number":727,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"ما معنى فعل ﴿جعل﴾ في قوله تعالى: ﴿ما جعل الله من بحيرة﴾؟","answer":"جاء ﴿جعل﴾ بمعنى شرع وسمّى وحكم؛ أي لم يقرر الله لهذه الأنعام حرمة دينية، وإنما ابتدعها أهل الجاهلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص742–743، تحت عنوان «معاني الفعل ﴿جعل﴾ في قوله: ﴿ما جعل الله﴾»","url":""}]},{"id":"s5-728","number":728,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"ما فائدة دخول ﴿من﴾ في قوله تعالى: ﴿ما جعل الله من بحيرة﴾؟","answer":"دخلت ﴿من﴾ في سياق النفي لتأكيد الاستغراق؛ فنفت أن يكون الله شرع فردًا واحدًا من هذه الأصناف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص743–744، تحت عنوان «دخول ﴿من﴾ في سياق النفي يجعلها للجنس»","url":""}]},{"id":"s5-513","number":513,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"كيف أكدت الآية نفي تشريع البحيرة والسائبة والوصيلة والحام؟","answer":"اجتمع النفي بـ﴿ما﴾، وزيادة ﴿من﴾، وتكرار ﴿لا﴾ مع الأصناف؛ فاشتد النفي وثبت استقلال الحكم بإبطال كل صنف منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص747–748، تحت عنوان «اجتماع أساليب توكيدية في: ﴿ما جعل الله من بحيرة ولا سائبة ولا وصيلة ولا حام﴾»","url":""}]},{"id":"s5-729","number":729,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"ما فائدة الاستدراك في قوله تعالى: ﴿ولكن الذين كفروا يفترون على الله الكذب﴾؟","answer":"بعد نفي أن يكون الله شرع تلك العادات، استدرك فبيّن منشأها الحقيقي: افتراء الكافرين؛ فانتقل الكلام من إبطال النسبة إلى كشف واضعيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص748–749، تحت عنوان «قوله: ﴿ولكن الذين كفروا﴾ جملة معطوفة على سابقتها مع الاستدراك»","url":""}]},{"id":"s5-514","number":514,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"ما دلالة التعبير بالمصدر ﴿الكذب﴾ مع ﴿يفترون على الله﴾؟","answer":"وصف افتراءهم بالمصدر يبالغ في قبحه، كأنهم بلغوا في الكذب غايته حتى صار هو حقيقة عملهم. فالذم يتعلق بنسبة تلك الأحكام المختلقة إلى الله، وفي التصريح باسمه تعظيم لجرم الافتراء عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص749–750، تحت «دلالة التعبير بالمصدر على المعنى وبلوغ الغاية»","url":""}]},{"id":"s5-515","number":515,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وأكثرهم لا يعقلون﴾ دون: لا يعلمون؟","answer":"خُتم بـ﴿لا يعقلون﴾ لأن أكثرهم مقلدون لكبارهم في هذه المحرمات من غير نظر، أما الأقل فهم الذين اخترعوا الافتراء ونسبوه إلى الله؛ فدلَّت ﴿أكثرهم﴾ على انتقال الحكم من المتبوعين المفترين إلى أتباعهم المقلدين","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص750–751، تحت «قوله وأكثرهم لا يعقلون جملة تدل على الحال»","url":""}]},{"id":"s5-517","number":517,"surah":5,"verses":[104],"references":[{"surah":5,"verses":[104]}],"verseLabel":"المائدة: 104","question":"ما دلالة فعل ﴿وجدنا﴾ في قولهم: ﴿ما وجدنا عليه آباءنا﴾؟","answer":"هو من الوجدان العلمي؛ فقد ادعوا العلم بصحة الموروث لمجرد أنهم ألفوا آباءهم عليه، من غير برهان يثبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص759–760، تحت عنوان «قولهم ﴿وجدنا﴾ من باب الوجدان العلمي»","url":""}]},{"id":"s5-730","number":730,"surah":5,"verses":[104],"references":[{"surah":5,"verses":[104]}],"verseLabel":"المائدة: 104","question":"ما الصورة في قوله تعالى: ﴿ما وجدنا عليه آباءنا﴾؟","answer":"تفيد ﴿على﴾ الاستعلاء مجازًا؛ فصُورت ملازمتهم تقليد الآباء وتمكنهم منه بحال راكب مستعلٍ على مركوبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص760–761، تحت عنوان «التعبير بحرف الجر ﴿على﴾ يفيد الاستعلاء مجازًا»","url":""}]},{"id":"s5-518","number":518,"surah":5,"verses":[104],"references":[{"surah":5,"verses":[104]}],"verseLabel":"المائدة: 104","question":"ما دلالة الاستفهام في قوله تعالى: ﴿أولو كان آباؤهم لا يعلمون شيئًا ولا يهتدون﴾؟","answer":"الاستفهام للإنكار والإلزام: أيكفيهم طريق الآباء حتى لو فقد الآباء العلم والهداية؟ فهو يهدم التقليد بإظهار النتيجة التي لا يقبلها عقل: اتباع الجاهل الضال لمجرد سبقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص761–762، تحت عنوان «أثر الهمزة في الإنكار وتوجيه المعنى»","url":""}]},{"id":"s5-519","number":519,"surah":5,"verses":[104],"references":[{"surah":5,"verses":[104]}],"verseLabel":"المائدة: 104","question":"ما الفرق بين نفي العلم ونفي الهداية في قوله تعالى: ﴿لا يعلمون شيئًا ولا يهتدون﴾؟","answer":"نفي العلم يسلب عن الآباء المعرفة التي يصح بها المعتقد، ونفي الهداية يسلب عنهم الاهتداء إلى طريق الحق؛ فجمع فقد المعرفة وفقد الاهتداء، فلا يبقى لتقليدهم وجه","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص763–764، تحت عنوان «الفعل ﴿يعلمون﴾ اكتفى بمفعول واحد فيكون معناه المعرفة»","url":""}]},{"id":"s5-520","number":520,"surah":5,"verses":[104],"references":[{"surah":2,"verses":[170]},{"surah":5,"verses":[104]},{"surah":31,"verses":[21]}],"verseLabel":"البقرة: 170؛ المائدة: 104؛ لقمان: 21","question":"ما الفرق بين قوله تعالى: ﴿ما ألفينا عليه آباءنا﴾ في البقرة، وقوله: ﴿ما وجدنا عليه آباءنا﴾ في المائدة ولقمان؟","answer":"من توجيهات المصدر أن «ألفينا» أخص؛ فهي وجدان الشيء على هيئة مخصوصة، فناسبت أول موضع للتقليد في البقرة. أما «وجدنا» فأعم في وجوه الوجدان، فوردت في المائدة ولقمان. فالفرق في سعة اللفظ وخصوصه مع اتحاد أصل التمسك بما عليه الآباء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص663–664، تحت عنوان «توجيه المتشابه اللفظي بين ﴿ما ألفينا﴾ و﴿ما وجدنا﴾»","url":""}]},{"id":"s5-522","number":522,"surah":5,"verses":[104],"references":[{"surah":2,"verses":[170]},{"surah":5,"verses":[104]},{"surah":31,"verses":[21]}],"verseLabel":"البقرة: 170؛ المائدة: 104؛ لقمان: 21","question":"ما دلالة فعل ﴿تعالوا﴾ في قوله تعالى: ﴿تعالوا إلى ما أنزل الله وإلى الرسول﴾؟","answer":"أصل الفعل دعوة إلى العلو، فاستعمل هنا في الإقبال على الوحي والرسول، وفيه تصوير للانتقال من حضيض التقليد إلى رفعة الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص756، تحت عنوان «دلالة الفعل ﴿تعالوا﴾ على الترقي بالنظر إلى أصله اللغوي»","url":""}]},{"id":"s5-731","number":731,"surah":5,"verses":[104],"references":[{"surah":2,"verses":[170]},{"surah":5,"verses":[104]},{"surah":31,"verses":[21]}],"verseLabel":"البقرة: 170؛ المائدة: 104؛ لقمان: 21","question":"ما غرض الأمر في قوله تعالى: ﴿اتبعوا ما أنزل الله﴾؟","answer":"الأمر للإرشاد والإلزام باتباع الوحي وترك تقليد الآباء؛ فالمنزل من الله هو الميزان الذي تصح به العقيدة والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص663، تحت عنوان «غرض الأمر في قوله: ﴿اتبعوا ما أنزل الله﴾»","url":""}]},{"id":"s5-523","number":523,"surah":5,"verses":[104],"references":[{"surah":2,"verses":[170]},{"surah":5,"verses":[104]}],"verseLabel":"البقرة: 170؛ المائدة: 104","question":"ما سرّ وصف الآباء في البقرة بأنهم ﴿لا يعقلون شيئًا﴾، وفي المائدة بأنهم ﴿لا يعلمون شيئًا﴾؟","answer":"زاد أهل المائدة على مجرد اتباع الآباء دعوى الاكتفاء بقولهم «حسبنا»، فنُفي عن آبائهم العلم الذي يبرر هذا الاكتفاء. أما البقرة فاقتصروا على الاتباع، فجاء نفي العقل؛ ويربط المصدر زيادة الدعوى بزيادة الرد عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص669، تحت «توجيه المتشابه اللفظي: وجه التشابه بين ما في البقرة لا يعقلون وما في المائدة لا يعلمون»","url":""}]},{"id":"s5-524","number":524,"surah":5,"verses":[105],"references":[{"surah":5,"verses":[105]}],"verseLabel":"المائدة: 105","question":"ما دلالة قوله تعالى: ﴿عليكم أنفسكم﴾ دون: أصلحوا أنفسكم؟","answer":"التركيب اسم فعل للإغراء بمعنى: الزموا شأن أنفسكم واحفظوها، واختيار ﴿على﴾ يلائم معنى الوجوب والإلزام والتمكن؛ فهو أوجز وأقوى تنبيهًا من أمر مباشر","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص767–768، تحت عنوان «خروج الجار والمجرور عن معناه الحقيقي إلى معنى اسم الفعل»","url":""}]},{"id":"s5-525","number":525,"surah":5,"verses":[105],"references":[{"surah":5,"verses":[105]}],"verseLabel":"المائدة: 105","question":"كيف يُفهم قوله تعالى: ﴿لا يضركم من ضل إذا اهتديتم﴾ مع الأمر بإصلاح الغير؟","answer":"الاهتداء يشمل أداء ما أوجب الله، ومنه الأمر بالمعروف والنهي عن المنكر بحسب القدرة والحكمة؛ فإذا أصلح المؤمن نفسه وبذل واجب البيان لم يضره إصرار غيره على الضلال. فالآية تنفي تبعة نتيجة لا يملكها، ولا تبيح ترك النصيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص769–770، تحت عنوان «قوله: ﴿لا يضركم من ضل إذا اهتديتم﴾»","url":""}]},{"id":"s5-526","number":526,"surah":5,"verses":[105],"references":[{"surah":5,"verses":[105]}],"verseLabel":"المائدة: 105","question":"ما دلالة تقديم الخبر في قوله تعالى: ﴿إلى الله مرجعكم جميعًا﴾؟","answer":"تقديم ﴿إلى الله﴾ يفيد التخصيص والتوكيد؛ فمرجع المهتدي والضال إلى الله وحده، وهو الذي يفصل في الأعمال والمصائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص773–774، تحت عنوان «تقدم الخبر على المبتدأ لإفادة التخصيص والتوكيد»","url":""}]},{"id":"s5-527","number":527,"surah":5,"verses":[105],"references":[{"surah":5,"verses":[105]}],"verseLabel":"المائدة: 105","question":"ما دلالة قوله تعالى: ﴿فينبئكم بما كنتم تعملون﴾ دون: فيحاسبكم؟","answer":"الإنباء هنا ليس مجرد إخبارهم بما يجهلون؛ بل هو مجاز عن مجازاتهم على أعمالهم، خيرًا كانت أو شرًا، ولذلك جاء وعدًا ووعيدًا للفريقين","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص777، تحت «دلالة حذف المفعول الثالث للفعل فينبئكم»","url":""}]},{"id":"s5-528","number":528,"surah":5,"verses":[105,106],"references":[{"surah":5,"verses":[105,106]}],"verseLabel":"المائدة: 105–106","question":"لماذا بُدئ حكم الوصية بلفظ ﴿شهادة﴾؟","answer":"قُدمت الشهادة لأنها محور الحكم وموضع العناية في توثيق الوصية، ولأن واقعة النزول تتصل بأدائها وما وقع فيها من خيانة. فالتقديم يوجه الانتباه إلى أصل المقصود قبل تفصيل الشاهدين ووقت الشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص782، تحت «البدء بكلمة شهادة لأنها بؤرة الموضوع وسبب النزول»","url":""}]},{"id":"s5-529","number":529,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما الصورة في قوله تعالى: ﴿إذا حضر أحدكم الموت﴾ مع أن الحاضر أماراته؟","answer":"المراد حضور علامات الموت وأماراته، وعُبر عنه بالفعل الماضي ﴿حضر﴾ مع كونه مستقبلًا للدلالة على حتميته وتحقق وقوعه؛ فيستدعي المبادرة إلى الوصية قبل فوات القدرة","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص784–785، تحت عنوان «إشارة إلى علامات نهاية أجل الإنسان»","url":""}]},{"id":"s5-530","number":530,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما دلالة قوله تعالى في شاهدي الوصية: ﴿ذوا عدل منكم﴾؟","answer":"تفيد ﴿من﴾ التبعيض؛ أي شاهدان عدلان من جماعة المخاطبين، فاشترطت الآية العدالة مع الانتماء إلى الجماعة التي تحفظ الحقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص786، تحت عنوان «دلالة التعبير بـ﴿منكم﴾ تفيد التبعيض»","url":""}]},{"id":"s5-732","number":732,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما دلالة ﴿أو﴾ في قوله تعالى: ﴿أو آخران من غيركم﴾؟","answer":"هي للتقسيم بحسب الحال لا للتخيير المطلق؛ فالأصل شاهدان من المسلمين، وينتقل إلى آخرين عند الضرورة التي بينها سياق السفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص786–787، تحت عنوان «لفظ ﴿أو﴾ حرف عطف للتقسيم لا للتخيير»","url":""}]},{"id":"s5-531","number":531,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما دلالة تخصيص السفر في قوله تعالى: ﴿إن أنتم ضربتم في الأرض فأصابتكم مصيبة الموت﴾؟","answer":"في السفر يبعد الإنسان عن أهله وجماعته، وقد تفجؤه أمارات الموت ولا يجد الشهود المعتادين؛ لذلك احتاج السياق إلى بيان رخصة التوثيق بمن يتاح وحماية الوصية من الضياع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص787–788، تحت عنوان «تحديد الشاهدين مقيد بالضرب في الأرض»","url":""}]},{"id":"s5-532","number":532,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما الصورة في التعبير عن السفر بقوله تعالى: ﴿ضربتم في الأرض﴾؟","answer":"التعبير كناية عن السير والسفر؛ فأصل السير ضرب الأرض بالأرجل. و«في الأرض» تصور الانتقال فيها، فيلائم ذلك حال المسافر الذي قد لا يجد عند حضور الموت من يشهد من جماعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص787–788، تحت «تحديد الشاهدين مقيد بالضرب في الأرض»","url":""}]},{"id":"s5-533","number":533,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما دلالة تسمية الموت ﴿مصيبة الموت﴾؟","answer":"جمع «أصابتكم» و«مصيبة» جناسًا اشتقاقيًا يزيد العبارة تآلفًا ويؤكد وقع الموت وخطورة الحال. فكان يمكن في أصل المعنى أن يقال أصابكم الموت، لكن التعبير بالمصيبة يبرز فداحة الخطب وأهمية صون الحقوق بالوصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص788–789، تحت «الجناس الاشتقاقي لتحلية الكلام»","url":""}]},{"id":"s5-534","number":534,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما دلالة حبس الشاهدين ﴿من بعد الصلاة﴾ عند الشك؟","answer":"الحبس هنا إيقاف الشاهدين لاستحلافهما لا سجنهما، واختير ما بعد الصلاة لأن الصلاة تنقي النفس من أدرانها فيكون الصدق في الشهادة أرجى؛ وقيل المراد صلاة العصر خاصة","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص789–790، تحت عنوان «﴿تحبسونهما من بعد الصلاة﴾ عام في كل متهمين حكمًا»","url":""}]},{"id":"s5-535","number":535,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما دلالة إيراد لفظ الجلالة في يمين الشاهدين: ﴿فيقسمان بالله﴾؟","answer":"ذُكر اسم الله مع القسم لتوكيد اليمين وتغليظها، واستحضار مراقبة الله حتى يمتنع الشاهدان من بيع الحق بثمن أو محاباة قريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص792، تحت عنوان «دلالة إيراد لفظ الجلالة مع القسم للتوكيد والتغليظ»","url":""}]},{"id":"s5-536","number":536,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما الصورة في قوله تعالى: ﴿لا نشتري به ثمنًا﴾ في سياق الشهادة؟","answer":"صُوِّر أخذ العوض على تغيير الشهادة بيعًا أو شراءً: فلا يبيع الشاهد قسمه أو شهادته وعهده بثمن، سواء أكان الثمن بخسًا أم مساويًا أم زائدًا","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص793–794، تحت «لفظ نشتري من الألفاظ المتضادة»","url":""}]},{"id":"s5-537","number":537,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما دلالة إضافة الشهادة إلى الله في ﴿ولا نكتم شهادة الله﴾؟","answer":"الإضافة تعظم الشهادة وتفخم أمرها، وتذكر الشاهد بأنها أمانة فرضها الله عليه؛ فتكسبها حرمةً تقوي الوازع عن كتمانها أو تبديلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص795–796، تحت «ولا نكتم شهادة الله يحتمل أن يكون خبرًا من أنفسهم»","url":""}]},{"id":"s5-538","number":538,"surah":5,"verses":[107],"references":[{"surah":5,"verses":[107]}],"verseLabel":"المائدة: 107","question":"ما الصورة في قوله تعالى: ﴿فإن عُثر على أنهما استحقا إثمًا﴾؟","answer":"أصل العثور الوقوع على الشيء، واستعمل مجازًا في الاطلاع على أمر خفي؛ أي ظهور كذب الشاهدين أو خيانتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص13، تحت عنوان «دلالة المعنى الحقيقي والمجازي في مصدر قوله: ﴿عُثر﴾»","url":""}]},{"id":"s5-733","number":733,"surah":5,"verses":[107],"references":[{"surah":5,"verses":[107]}],"verseLabel":"المائدة: 107","question":"لماذا بُني الفعل ﴿عُثر﴾ للمفعول؟","answer":"لأن المقصود وقوع الكشف وثبوت الخيانة، لا تعيين من اكتشفها؛ فصُرف النظر إلى الحدث وآثاره القضائية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص13–14، تحت عنوان «دلالة بناء الفعل ﴿عُثر﴾ لما لم يسم فاعله»","url":""}]},{"id":"s5-539","number":539,"surah":5,"verses":[107],"references":[{"surah":5,"verses":[107]}],"verseLabel":"المائدة: 107","question":"ما دلالة إطلاق الإثم على فعل الشاهدين في قوله تعالى: ﴿استحقا إثمًا﴾؟","answer":"أطلق الوصف على الموصوف مبالغةً في تقبيح الخيانة؛ فكأن الفعل الذي استوجب الإثم صار هو الإثم نفسه، مع تأكيد لزوم تبعته عليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص14–15، تحت عنوان «دلالة إطلاق الصفة على الموصوف في قوله: ﴿استحقا إثمًا﴾»","url":""}]},{"id":"s5-540","number":540,"surah":5,"verses":[107],"references":[{"surah":5,"verses":[107]}],"verseLabel":"المائدة: 107","question":"ما نكتة ذكر ﴿الأوليان﴾ وارتباطه بلفظ ﴿استحق﴾؟","answer":"المراد الأقربان من أولياء الميت ممن وقع عليهم الاستحقاق والضرر؛ فهما أولى بالدفاع عن الحق والقيام بالشهادة البديلة عند ظهور خيانة الشاهدين الأولين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص18–19، تحت عنوان «نكتة ذكر ﴿الأوليين﴾ وارتباطه بلفظ ﴿استحق﴾»","url":""}]},{"id":"s5-541","number":541,"surah":5,"verses":[107],"references":[{"surah":5,"verses":[107]}],"verseLabel":"المائدة: 107","question":"ما دلالة قوله تعالى: ﴿لشهادتنا أحق من شهادتهما﴾ دون: أصدق؟","answer":"اختير ﴿أحق﴾ بصيغة التفضيل مع أنه لا حقيقة في يمين الأولين، مراعاةً لظاهر دعواهما وإمكان قبول يمينهما قبل انكشاف الخيانة؛ فالمعنى أن شهادة الآخرين أحق وأصدق مما شهدا به","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص23، تحت «نكتة صيغة التفضيل في لشهادتنا أحق»","url":""}]},{"id":"s5-542","number":542,"surah":5,"verses":[107],"references":[{"surah":5,"verses":[107]}],"verseLabel":"المائدة: 107","question":"ما دلالة ختم يمين الشاهدين الآخرين بقوله تعالى: ﴿إنا إذًا لمن الظالمين﴾؟","answer":"يعترفان بأنهما إن كذبا أو تجاوزا الحق كانا مندرجين في زمرة الظالمين؛ و﴿إن﴾ واللام تؤكدان تبعة الشهادة، و﴿إذًا﴾ تربط الظلم بما لو وقع منهما من اعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص24، تحت «دلالة الاستئناف في إنا إذًا لمن الظالمين»","url":""}]},{"id":"s5-543","number":543,"surah":5,"verses":[108],"references":[{"surah":5,"verses":[108]}],"verseLabel":"المائدة: 108","question":"ما معنى الإتيان بالشهادة ﴿على وجهها﴾ في قوله تعالى: ﴿ذلك أدنى أن يأتوا بالشهادة على وجهها﴾؟","answer":"وجه الشهادة صورتها الصحيحة المستقيمة التي توافق الحق بلا كتمان ولا تبديل؛ أي إن هذا الإجراء أقرب إلى حمل الشهود على أدائها كاملة كما يجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص32–33، تحت عنوان «الاستعارة ونكتة إيرادها»","url":""}]},{"id":"s5-544","number":544,"surah":5,"verses":[108],"references":[{"surah":5,"verses":[108]}],"verseLabel":"المائدة: 108","question":"ما دلالة قوله تعالى: ﴿أو يخافوا أن ترد أيمان بعد أيمانهم﴾؟","answer":"الإجراء يردع الشاهدين من جهة أخرى: يخافان أن تكشف خيانتهما فتأتي أيمان الورثة بعد أيمانهما فتبطل أثرها وتفضحهما؛ فاحتمال رد اليمين يحمل على الصدق من البداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص35–36، تحت عنوان «دلالة قوله: ﴿أن ترد أيمان بعد أيمانهم﴾ في السياق الحكيم»","url":""}]},{"id":"s5-545","number":545,"surah":5,"verses":[108],"references":[{"surah":5,"verses":[108]}],"verseLabel":"المائدة: 108","question":"لماذا حُذف متعلق التقوى في قوله تعالى: ﴿واتقوا الله﴾؟","answer":"حُذف ليعم كل ما تجب تقوى الله فيه، وبخاصة أمانة الشهادة واليمين وما يتصل بهما من أحكام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص37، تحت عنوان «نكتة عدم ذكر متعلق التقوى في قوله تعالى: ﴿واتقوا الله﴾»","url":""}]},{"id":"s5-734","number":734,"surah":5,"verses":[108],"references":[{"surah":5,"verses":[108]}],"verseLabel":"المائدة: 108","question":"لماذا لا يراد بقوله تعالى: ﴿واسمعوا﴾ مجرد إدراك الصوت؟","answer":"استُعمل السماع مجازًا في القبول والطاعة؛ فالمطلوب تلقي أحكام الشهادة واليمين بالانقياد والعمل، لا سماع ألفاظها فحسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص38، تحت عنوان «دلالة المجاز في ﴿واسمعوا﴾»","url":""}]},{"id":"s5-546","number":546,"surah":5,"verses":[108],"references":[{"surah":5,"verses":[108]}],"verseLabel":"المائدة: 108","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله لا يهدي القوم الفاسقين﴾؟","answer":"من خرج عن طاعة الله في الشهادة واليمين فقد فسق، والإصرار على هذا الخروج يحرمه هداية التوفيق إلى أداء الحق؛ فكانت الخاتمة تهديدًا بعد الأمر بالتقوى والسماع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص38–39، تحت عنوان «دلالة قوله: ﴿والله لا يهدي القوم الفاسقين﴾»","url":""}]},{"id":"s5-547","number":547,"surah":5,"verses":[109],"references":[{"surah":5,"verses":[109]}],"verseLabel":"المائدة: 109","question":"ما مناسبة الانتقال من الشهادة في الدنيا إلى قوله تعالى: ﴿يوم يجمع الله الرسل﴾؟","answer":"لما تم الكلام على شهادة الناس على وصايا المخلوقين والتحذير من تحريفها، ناسب الانتقال إلى شهادة الرسل على وصايا الخالق يوم القيامة؛ تحذيرًا من ذلك المشهد وتمهيدًا لسؤال عيسى عليه السلام وبيان معجزاته","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص41، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s5-548","number":548,"surah":5,"verses":[109],"references":[{"surah":5,"verses":[109]}],"verseLabel":"المائدة: 109","question":"ما الحكمة التي يبينها سؤال الرسل: ﴿ماذا أجبتم﴾ مع علم الله بالجواب؟","answer":"السؤال ليس لطلب علم، بل لفضح كفر بعض الأمم ونفاقها وتكذيبها رسلها على رؤوس الأشهاد، وإقامة الحجة عليهم تمهيدًا لعقوبتهم","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص44–45، تحت عنوان «سبب سؤال الله تعالى عما هو به عالم»","url":""}]},{"id":"s5-549","number":549,"surah":5,"verses":[109],"references":[{"surah":5,"verses":[109]}],"verseLabel":"المائدة: 109","question":"ما دلالة جواب الرسل: ﴿لا علم لنا﴾ مع علمهم بمن استجاب لهم في الظاهر؟","answer":"ليس المراد نفي كل علم، بل نفي علم الإحاطة والشمول المختص بالله؛ فالرسل يعلمون ظاهر إجابة أقوامهم، ولا يعلمون بواطنهم ولا حال من لم يروه منهم ولا ما حدث بعدهم إلا بوحي","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص45–46، تحت عنوان «سر مجيء جواب الرسل على خلاف مقتضى الظاهر»","url":""}]},{"id":"s5-550","number":550,"surah":5,"verses":[109],"references":[{"surah":5,"verses":[109]}],"verseLabel":"المائدة: 109","question":"ما دلالة ضمير الفصل في قوله تعالى: ﴿إنك أنت علام الغيوب﴾؟","answer":"يفيد ﴿أنت﴾ القصر والتوكيد؛ فردّ الرسل العلم المحيط بالغيوب إلى الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص47، تحت عنوان «بلاغة أسلوب الحصر بالضمير ﴿أنت﴾»","url":""}]},{"id":"s5-735","number":735,"surah":5,"verses":[109],"references":[{"surah":5,"verses":[109]}],"verseLabel":"المائدة: 109","question":"ما دلالة صيغة ﴿علام﴾؟","answer":"هي صيغة مبالغة تدل على كمال العلم وكثرته وإحاطته، فلا يخفى على الله شيء من بواطن الخلق ومآلاتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص47، تحت عنوان «دلالة وصف ﴿علام﴾ على المبالغة»","url":""}]},{"id":"s5-736","number":736,"surah":5,"verses":[109],"references":[{"surah":5,"verses":[109]}],"verseLabel":"المائدة: 109","question":"لماذا جُمع الغيب في قوله تعالى: ﴿علام الغيوب﴾؟","answer":"جُمع لتعدد أنواع ما غاب عن الخلق من السرائر والأزمنة والأمكنة والمآلات، وكلها داخلة في علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص48، تحت عنوان «دلالة صيغة الجمع للفظ الغيب»","url":""}]},{"id":"s5-551","number":551,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"لماذا أُمر عيسى عليه السلام بذكر النعم يوم القيامة؟","answer":"لإظهار كرم المنعم وإقامة الحجة على من غلا في عيسى؛ فكل ما ظهر على يديه نعمة من الله لا قدرة مستقلة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص56، تحت عنوان «الأمر بذكر النعم يوم القيامة إظهارًا لكرم المنعم»","url":""}]},{"id":"s5-737","number":737,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما فائدة تكرار ﴿على﴾ في قوله تعالى: ﴿نعمتي عليك وعلى والدتك﴾؟","answer":"كرر حرف الاستعلاء لتمييز ما اختص به عيسى وما وصل إلى والدته، مع بيان شمول النعمة لكليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص57، تحت عنوان «فائدة العطف وحرف الاستعلاء في قوله: ﴿عليك وعلى والدتك﴾»","url":""}]},{"id":"s5-552","number":552,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما سر التعبير بقوله تعالى: ﴿إذ أيدتك بروح القدس﴾؟","answer":"دل التأييد على التقوية والحفظ، وروح القدس جبريل عليه السلام؛ فظهر أن كلام عيسى في المهد وسائر شأنه كان بنعمة الله وتأييده لا باستقلال منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص58–59، تحت عنوان «سر التعبير بـ﴿إذ أيدتك بروح القدس﴾ ودلالة الجملة الحالية»","url":""}]},{"id":"s5-553","number":553,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما سرّ ترتيب قوله تعالى: ﴿تكلم الناس في المهد وكهلًا﴾؟","answer":"قُرن كلامه في المهد بكلامه كهلًا للدلالة على أن كلامه في الحالين على نسق واحد صادر عن كمال العقل بلا تفاوت، وفيه إشعار باستمرار حياته إلى سن الكهولة؛ وقيل يتضمن نزوله قبل القيامة","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص59–60، تحت «سبب اقتران وكهلًا بفي المهد»","url":""}]},{"id":"s5-554","number":554,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما دلالة تكرار قوله تعالى: ﴿بإذني﴾ مع صنع هيئة الطير والشفاء وإحياء الموتى؟","answer":"كرر القيد عند الخوارق التي قد تكون مدخلًا للغلو، ليقرر أن عيسى سبب مأذون له وأن الخلق والشفاء والإحياء الحقيقي بقدرة الله؛ فكل معجزة شاهد على الرسالة لا على الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص62–63، تحت عنوان «سبب تخصيص كلمة ﴿بإذني﴾ في أربعة مواضع»","url":""}]},{"id":"s5-555","number":555,"surah":5,"verses":[110],"references":[{"surah":3,"verses":[49]},{"surah":5,"verses":[110]}],"verseLabel":"آل عمران: 49؛ المائدة: 110","question":"ما سر قوله تعالى في آل عمران: ﴿فأنفخ فيه﴾، وفي المائدة: ﴿فتنفخ فيها﴾؟","answer":"في آل عمران عاد ضمير ﴿فيه﴾ إلى الطير المذكر، وجُعل تشكيل الهيئة ونفخ الروح نعمة واحدة في سياق الإيجاز؛ وفي المائدة عاد ضمير ﴿فيها﴾ إلى الكاف بوصفها صفة الهيئة المؤنثة، وعُدَّ تشكيل الهيئة ونفخ الروح نعمتين في مقام تعداد النعم، فاختلاف المقصودين أوجب اختلاف العبارتين","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص71–72، تحت «التشابه اللفظي مع تذكير الضمير في فأنفخ فيه وتأنيثه في فتنفخ فيها»","url":""}]},{"id":"s5-556","number":556,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما دلالة قوله تعالى: ﴿فتكون طيرًا بإذني﴾ واختيار ﴿طيرًا﴾ دون: طائرًا؟","answer":"قرأ الجمهور ﴿طيرًا﴾ بصيغة اسم الجمع، وفيها اعتبار تعدد الهيئات وكثرة أفراد الطير؛ وقُرئت ﴿طائرًا﴾ بالإفراد، أي إن كل هيئة يصنعها تصير طائرًا واحدًا، والمآل في القراءتين تعدد الطير، ثم قُيد ذلك بإذن الله","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص69–70، تحت «توجيه قراءتي سحر وساحر»","url":""}]},{"id":"s5-557","number":557,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما دلالة الجمع بين إبراء الأكمه والأبرص وإخراج الموتى؟","answer":"جُعل إبراء الأكمه والأبرص معًا آيةً واحدة في الإعجاز، ثم ذُكر إحياء هيئة الطير قبلهما لأنه أعظم من شفاء المرض، وجُعل إخراج الموتى نعمة مستقلة لأنه أعظم من الجميع؛ فترقى تعداد الخوارق إلى أبلغها","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص63–64، تحت «سبب عدم البدء بإذ عند الكلام عن إبراء الأكمه والأبرص»","url":""}]},{"id":"s5-558","number":558,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما الصورة في قوله تعالى: ﴿إذ كففت بني إسرائيل عنك﴾؟","answer":"الكف في الأصل المنع، وسميت الكف كفًّا لأنها تمنع ما فيها، ثم أطلق على الدفع؛ فمعنى ﴿كففت بني إسرائيل عنك﴾: منعت أذاهم عنه، وهي نعمة العصمة بعد تعداد نعم التأييد والتعليم","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص73–74، تحت عنوان «الكف والمنع»","url":""}]},{"id":"s5-559","number":559,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما دلالة القصر في قول المكذبين: ﴿إن هذا إلا سحر مبين﴾؟","answer":"قصروا البينات على السحر بـ﴿إن... إلا﴾ مكابرةً؛ فكأنها لا تحمل عندهم دلالة إلا هذا الوصف الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص67–68، تحت عنوان «بلاغة أسلوب القصر في قوله: ﴿إن هذا إلا سحر مبين﴾»","url":""}]},{"id":"s5-738","number":738,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما مناسبة وصف السحر بأنه ﴿مبين﴾؟","answer":"وصفوه بالمبين للمبالغة في دعواهم وقلب الحقيقة؛ فالذي كان مبينًا في الواقع هو الآيات، فجعلوا الوضوح للسحر افتراءً.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص68، تحت عنوان «مناسبة الصفة ﴿مبين﴾»","url":""}]},{"id":"s5-739","number":739,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"لماذا قابلوا البينات المجموعة باسم الإشارة المفرد ﴿هذا﴾؟","answer":"جمعوا الخوارق المتنوعة في حكم واحد وأشاروا إليها كأنها شيء واحد، ليسهل عليهم وصمها كلها بالسحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص68–69، تحت عنوان «سبب مقابلة لفظ ﴿البينات﴾ بالمفرد ﴿هذا﴾»","url":""}]},{"id":"s5-560","number":560,"surah":5,"verses":[110],"references":[{"surah":3,"verses":[49]},{"surah":5,"verses":[110]}],"verseLabel":"آل عمران: 49؛ المائدة: 110","question":"ما الفرق بين ﴿بإذني﴾ في المائدة و﴿بإذن الله﴾ في آل عمران؟","answer":"في المائدة يرد الخطاب من الله إلى عيسى، فناسبت إضافة الإذن إلى ضمير المتكلم ﴿بإذني﴾. وفي آل عمران يحكي عيسى لقومه آياته، فناسب إظهار اسم الله في ﴿بإذن الله﴾ لإسناد القدرة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص70–71، تحت عنوان «التشابه اللفظي بين ﴿بإذني﴾ و﴿بإذن الله﴾»","url":""}]},{"id":"s5-561","number":561,"surah":5,"verses":[110],"references":[{"surah":3,"verses":[49]},{"surah":5,"verses":[110]}],"verseLabel":"آل عمران: 49؛ المائدة: 110","question":"ما الفرق بين قول عيسى عليه السلام في آل عمران: ﴿وأحيي الموتى بإذن الله﴾، وقول الله في المائدة: ﴿وإذ تخرج الموتى بإذني﴾؟","answer":"صرحت آل عمران بالإحياء في مقام الإخبار بالمعجزة: «وأحيي الموتى بإذن الله». أما المائدة، في مقام تعداد النعم، فعبّرت عن الإحياء بلازمه وهو إخراج الموتى أحياء من قبورهم؛ وفي المضارع استحضار للصورة العجيبة، مع رد القدرة في الموضعين إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص64–65، تحت «بلاغة الكناية في وإذ تخرج الموتى»","url":""}]},{"id":"s5-562","number":562,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما نكتة ترتيب ﴿الكتاب والحكمة والتوراة والإنجيل﴾؟","answer":"بدأ بالكتاب الذي يحتمل الكتابة أو جنس الكتب، ثم الحكمة التي تضبط العلم والعمل، ثم خص التوراة والإنجيل لشرفهما وصلتهما برسالة عيسى؛ فجاء الترتيب من العام والأصل إلى الكتابين المعينين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص60، تحت عنوان «نكتة الترتيب في ذكر الكتاب والحكمة والتوراة والإنجيل»","url":""}]},{"id":"s5-563","number":563,"surah":5,"verses":[111],"references":[{"surah":5,"verses":[111]}],"verseLabel":"المائدة: 111","question":"ما معنى الوحي في قوله تعالى: ﴿وإذ أوحيت إلى الحواريين﴾؟","answer":"الوحي إعلام خفي سريع، والمراد هنا الإلهام أو الأمر بواسطة الرسول؛ فلا يلزم من إطلاقه عليهم وحي النبوة والتشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص75، تحت عنوان «شرح المفردات: ﴿أوحيت﴾»","url":""}]},{"id":"s5-740","number":740,"surah":5,"verses":[111],"references":[{"surah":5,"verses":[111]}],"verseLabel":"المائدة: 111","question":"ما وجه ﴿أن﴾ في قوله تعالى: ﴿أن آمنوا بي وبرسولي﴾؟","answer":"تحتمل أن تكون تفسيرية لما تضمنه الوحي من معنى القول، وتحتمل المصدرية؛ أي أوحيت إليهم الإيمان بالله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص76–77، تحت عنوان «دلالة ﴿أن﴾ على التفسيرية والمصدرية»","url":""}]},{"id":"s5-564","number":564,"surah":5,"verses":[111],"references":[{"surah":5,"verses":[111]}],"verseLabel":"المائدة: 111","question":"ما دلالة الجمع في الأمر بين ﴿أن آمنوا بي وبرسولي﴾؟","answer":"الإيمان بالله أصل، والإيمان برسوله تصديق لمن اختاره الله واتباع لما بلغه؛ فلا يصح ادعاء الأول مع رد الثاني. وإضافته إلى الله في ﴿برسولي﴾ تشرف عيسى وتثبت عبوديته ورسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص77، تحت «سر تعدد المتعلق في أن آمنوا بي وبرسولي»","url":""}]},{"id":"s5-565","number":565,"surah":5,"verses":[111],"references":[{"surah":5,"verses":[111]}],"verseLabel":"المائدة: 111","question":"ما دلالة قول الحواريين: ﴿آمنا واشهد بأننا مسلمون﴾ دون: مؤمنون؟","answer":"قدموا الإيمان لأنه تصديق القلب، ثم طلبوا أن يشهد عيسى لهم بالإسلام لأنه الانقياد والخضوع الظاهر الذي تدل عليه الأعمال والأقوال؛ فالشهادة تتعلق بالظاهر لا بما استأثر الله بعلمه في القلوب","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص78–79، تحت «إيثار تقديم الإيمان على الإسلام»","url":""}]},{"id":"s5-566","number":566,"surah":5,"verses":[112],"references":[{"surah":5,"verses":[112]}],"verseLabel":"المائدة: 112","question":"ما دلالة نداء الحواريين عيسى باسمه في طلب المائدة؟","answer":"نادوه باسمه دون وصفه بالرسالة أو روح الله؛ ومن توجيهات المصدر أن طلبهم اقتراح تكلفوا فيه، فخاطبوه خطاب إيناس ليبسطوا إليه المسألة. ويحمل النداء أيضًا بيان منزلته البشرية، مع بقاء وجوب توقير الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص83، تحت «دلالة النداء في يا عيسى»","url":""}]},{"id":"s5-567","number":567,"surah":5,"verses":[112],"references":[{"surah":5,"verses":[112]}],"verseLabel":"المائدة: 112","question":"ما دلالة الاستفهام بـ﴿هل﴾ في قول الحواريين: ﴿هل يستطيع ربك﴾؟","answer":"وردت ﴿هل﴾ لطلب التصديق بحصول الفعل، لا للحكم جزمًا بعجز الرب؛ والسياق يحتمل السؤال عن الفعل والإجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص83–84، تحت عنوان «نكتة التعبير بـ﴿هل﴾ في الاستفهام»","url":""}]},{"id":"s5-741","number":741,"surah":5,"verses":[112],"references":[{"surah":5,"verses":[112]}],"verseLabel":"المائدة: 112","question":"كيف تؤثر القراءات في فهم قوله تعالى: ﴿هل يستطيع ربك﴾؟","answer":"على قراءة الجمهور يكون السؤال: هل يفعل ربك ذلك؟ وعلى قراءة ﴿هل تستطيع ربَّك﴾ يكون المعنى: هل تستطيع أن تسأل ربك؟ فتتساند القراءتان في دفع التسرع بنسبة الشك إلى الحواريين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص87–88، تحت عنوان «تنوع القراءات القرآنية وأثرها في ترسية المعنى وبيانه»","url":""}]},{"id":"s5-568","number":568,"surah":5,"verses":[112],"references":[{"surah":5,"verses":[112]}],"verseLabel":"المائدة: 112","question":"ما دلالة اختيار ﴿هل﴾ في سؤال الحواريين؟","answer":"طلبوا التصديق بوقوع المطلوب، أي إنزال المائدة مستقبلًا، فناسبت «هل» هذا المقام. ومن توجيهات الاستفهام أنه تلطف في عرض الطلب واستدعاء الإجابة، فلا يلزم حمله على الشك في القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص83–84، تحت «نكتة التعبير بهل في الاستفهام ودلالته في السياق»","url":""}]},{"id":"s5-569","number":569,"surah":5,"verses":[112],"references":[{"surah":5,"verses":[112]}],"verseLabel":"المائدة: 112","question":"ما علة الأمر بالتقوى في جواب عيسى: ﴿اتقوا الله إن كنتم مؤمنين﴾؟","answer":"جاء الجواب استئنافًا لما أثاره طلبهم، فبدأ عيسى بتقوى الله لأن طلب الخوارق على وجه الاختبار لا يليق بالمؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص84–85، تحت عنوان «بلاغة الاستئناف البياني وعلة الأمر بالتقوى»","url":""}]},{"id":"s5-742","number":742,"surah":5,"verses":[112],"references":[{"surah":5,"verses":[112]}],"verseLabel":"المائدة: 112","question":"ما بديع الأسلوب الحكيم في جواب عيسى للحواريين؟","answer":"عدل عن مجاراة طلب المائدة أولًا إلى ما هو أولى بهم: تقوى الله وحفظ الإيمان من التكلف في الآيات؛ فوجههم إلى الأهم قبل إجابة المطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص86، تحت عنوان «بديع الأسلوب الحكيم وأهميته في السياق»","url":""}]},{"id":"s5-570","number":570,"surah":5,"verses":[113],"references":[{"surah":5,"verses":[113]}],"verseLabel":"المائدة: 113","question":"ما دلالة تعليل الحواريين طلب المائدة بالأكل وطمأنينة القلب والعلم والشهادة؟","answer":"قدّموا الأكل لأنه أول ما يقع عند نزول المائدة، ثم يفضي الحس والذوق إلى سكون القلب، فالعلم اليقيني، فالشهادة؛ ويحتمل أن طلب بعض الطعام كان لحاجة أو جوع، أو للتبرك والتشريف، فلا يُحصر في معنى واحد","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص90–91، تحت عنوان «مناسبة الترتيب في المعاطيف عبر سياق الآية الكريمة»","url":""}]},{"id":"s5-571","number":571,"surah":5,"verses":[113],"references":[{"surah":5,"verses":[113]}],"verseLabel":"المائدة: 113","question":"ما سرّ تقديم قولهم: ﴿نريد أن نأكل منها﴾ على طمأنينة القلوب؟","answer":"من توجيهات الترتيب أنهم بدأوا بما يقع في الحواس من الأكل والمعاينة، فيفضي ذلك إلى طمأنينة القلب ثم العلم اليقيني، فتأتي الشهادة مبنية على اليقين. فجمعوا مقاصدهم على ترتيب يقوي بيانها، من غير حصر الغرض في الطعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص91–92، تحت «مناسبة الترتيب في المعاطيف عبر سياق الآية الكريمة»","url":""}]},{"id":"s5-572","number":572,"surah":5,"verses":[113],"references":[{"surah":5,"verses":[113]}],"verseLabel":"المائدة: 113","question":"ما دلالة قول الحواريين: ﴿ونعلم أن قد صدقتنا﴾؟","answer":"طلبوا علمًا تؤيده المعاينة فيزداد به اليقين بصدق عيسى، وأكدوا مضمون العلم بـ﴿أن﴾ و﴿قد﴾؛ فالمقصود طمأنينة القلب لا ابتداء الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص90، تحت عنوان «دلالة قوله: ﴿ونعلم أن قد صدقتنا﴾»","url":""}]},{"id":"s5-573","number":573,"surah":5,"verses":[113],"references":[{"surah":5,"verses":[113]}],"verseLabel":"المائدة: 113","question":"ما فائدة إطلاق شهادة الحواريين في قولهم: ﴿ونكون عليها من الشاهدين﴾؟","answer":"أطلقوا الشهادة لتشمل الشهادة بوقوع المائدة وبدلالتها على صدق الرسول وقدرة الله، فلا يقف أثرها عند انتفاعهم بالطعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص91–92، تحت عنوان «فائدة إطلاق شهادتهم في ﴿من الشاهدين﴾»","url":""}]},{"id":"s5-743","number":743,"surah":5,"verses":[113],"references":[{"surah":5,"verses":[113]}],"verseLabel":"المائدة: 113","question":"ما دلالة تقديم ﴿عليها﴾ في قوله تعالى: ﴿ونكون عليها من الشاهدين﴾؟","answer":"قُدم الجار والمجرور للاهتمام بالمائدة وجعلها محور الشهادة، ثم أخر وصفهم بالشاهدين لإتمام معنى الالتزام بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص92، تحت عنوان «مناسبة تقديم ﴿عليها﴾ وتأخير ﴿من الشاهدين﴾»","url":""}]},{"id":"s5-574","number":574,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما سر الجمع بين نداء الألوهية والربوبية في قول عيسى: ﴿اللهم ربنا﴾؟","answer":"جمع ﴿اللهم﴾ بما فيه من تعظيم المعبود، و﴿ربنا﴾ بما يستحضر التربية والرعاية؛ فاجتمع الجلال والقرب في مطلع الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص96–97، تحت عنوان «سر الجمع بين نداء الألوهية والربوبية»","url":""}]},{"id":"s5-744","number":744,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما دلالة إضافة الرب إلى الجماعة في قوله: ﴿ربنا﴾؟","answer":"أضاف الرب إليهم جميعًا ليدخل الداعي والحواريين في طلب الرعاية والإنعام، فيظهر صدق الالتجاء ووحدة الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص97، تحت عنوان «دلالة الإضافة في ﴿ربنا﴾»","url":""}]},{"id":"s5-575","number":575,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما دلالة الأمر في دعاء عيسى: ﴿أنزل علينا مائدة﴾؟","answer":"خرجت صيغة الأمر من العبد إلى معنى الدعاء والطلب والتضرع، فلا تحمل معنى الإلزام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص98، تحت عنوان «دلالة الأمر في ﴿أنزل﴾»","url":""}]},{"id":"s5-745","number":745,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"لماذا قُدِّم ﴿علينا﴾ على ﴿مائدة﴾؟","answer":"قُدم الجار والمجرور للاختصاص والاهتمام؛ أي أنزلها علينا نحن استجابة لهذا الدعاء، مع إبراز صلتهم بالآية المطلوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص98، تحت عنوان «دلالة تقديم شبه الجملة ﴿علينا﴾ على ﴿مائدة﴾»","url":""}]},{"id":"s5-576","number":576,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما معنى ﴿عيدًا﴾ في قوله تعالى: ﴿تكون لنا عيدًا﴾؟","answer":"العيد ما يعود في زمن معلوم بالفرح والاجتماع والذكر؛ فسأل عيسى أن يبقى يوم المائدة مناسبة شكر لا أثرًا ينقضي بالأكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص94، تحت عنوان «شرح المفردات: ﴿عيدًا﴾»","url":""}]},{"id":"s5-746","number":746,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما علة إسناد العيد إلى المائدة في قوله تعالى: ﴿تكون لنا عيدًا﴾؟","answer":"الإسناد مجازي؛ فالمائدة سبب للفرح والاجتماع المتجدد، فنُسب إليها العيد مع أن المراد يوم نزولها أو ذكراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص99–100، تحت عنوان «علة الإسناد المجازي للعيد إلى المائدة»","url":""}]},{"id":"s5-747","number":747,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما دلالة عودة اللام في قوله تعالى: ﴿لأولنا وآخرنا﴾؟","answer":"عادت اللام مع البدل لتأكيد شمول النفع والذكر لأول الجماعة وآخرها، فليست المناسبة خاصة بمن شهد النزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص100–101، تحت عنوان «عودة اللام مع البدل، محاذاة للمبدل منه، في قوله: ﴿تكون لنا عيدًا لأولنا وآخرنا﴾»","url":""}]},{"id":"s5-748","number":748,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما براعة الطباق في قوله تعالى: ﴿لأولنا وآخرنا﴾؟","answer":"جمع الطباق طرفي الزمن ليفيد الشمول: من أول الأمة إلى آخرها، ويبرز امتداد أثر المائدة عبر الأجيال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص101، تحت عنوان «براعة الطباق في قوله تعالى: ﴿لأولنا وآخرنا﴾»","url":""}]},{"id":"s5-577","number":577,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما دلالة قول عيسى عليه السلام: ﴿وآية منك﴾ في دعائه بالمائدة؟","answer":"طلب أن تكون المائدة علامة إعجاز دالة على توحيد الله وصدق رسوله، ودليلًا لأهل النظر والاستدلال، وزاد وصفها بأنها من الله تشريفًا وتعظيمًا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص102، تحت عنوان «دلالة التعبير بقوله تعالى: ﴿وآية منك﴾»","url":""}]},{"id":"s5-749","number":749,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما براعة أسلوب التدلي في قوله تعالى: ﴿تكون لنا عيدًا لأولنا وآخرنا وآية منك وارزقنا﴾؟","answer":"بدأ بما هو أشرف: ابتهاج الروح بالنعمة من جهة صدورها عن المنعم، ثم ذكر كونها آية لأهل النظر، ثم انتقل إلى طلب الرزق الذي تنتفع به النفس والبدن؛ فتدرج من الأعلى إلى ما دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص103، تحت عنوان «براعة أسلوب التدلي»","url":""}]},{"id":"s5-578","number":578,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما دلالة صيغة الأمر في قول عيسى عليه السلام: ﴿وارزقنا﴾؟","answer":"خرج الأمر عن الإلزام إلى الدعاء والطلب؛ لأنه صادر من عبد إلى ربه، فالمعنى: نسألك يا رب أن ترزقنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص102، تحت عنوان «دلالة الأمر في قوله تعالى: ﴿وارزقنا﴾»","url":""}]},{"id":"s5-750","number":750,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما مناسبة فاصلة قوله تعالى: ﴿وأنت خير الرازقين﴾ لسياق الآيات؟","answer":"جاءت الفاصلة نونية منسجمة مع فواصل السياق مثل ﴿مؤمنين﴾ و﴿الشاهدين﴾ و﴿العالمين﴾، فأكسبت التلاوة اتساقًا وخشوعًا، واختير لفظ الرزق لأنه عطاء الله الحلال المتجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص103، تحت عنوان «دلالة الفاصلة ومناسبتها»","url":""}]},{"id":"s5-751","number":751,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما دلالة التذييل في قوله تعالى: ﴿وأنت خير الرازقين﴾؟","answer":"جاء التذييل تعليلًا لطلب الرزق وثناءً على الله؛ فهو مصدر الأرزاق وخالقها ومعطيها، ولا يساويه أحد في رزقه وفضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص104، تحت عنوان «دلالة التذييل الجاري مجرى التعليل»","url":""}]},{"id":"s5-579","number":579,"surah":5,"verses":[115],"references":[{"surah":5,"verses":[115]}],"verseLabel":"المائدة: 115","question":"ما نكتة التأكيد في قوله تعالى: ﴿إني منزلها عليكم﴾؟","answer":"أكدت الجملة بـ﴿إن﴾ تحقيق استجابة الله لتنزيل المائدة وإزالة ما قد يتوهم من الشك في وقوع وعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص109–110، تحت عنوان «نكتة التأكيد»","url":""}]},{"id":"s5-752","number":752,"surah":5,"verses":[115],"references":[{"surah":5,"verses":[115]}],"verseLabel":"المائدة: 115","question":"ما سر التعبير عن إنزال المائدة بالمسند الاسمي ﴿منزلها﴾؟","answer":"جيء باسم الفاعل خبرًا للدلالة على ثبوت الوعد وتحققه، فصار نزول المائدة مقررًا لا ارتياب فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص110–111، تحت عنوان «سر التعبير بالمسند اسمًا»","url":""}]},{"id":"s5-580","number":580,"surah":5,"verses":[115],"references":[{"surah":5,"verses":[115]}],"verseLabel":"المائدة: 115","question":"لماذا قيل في إنزال المائدة: ﴿عليكم﴾ دون «إليكم»؟","answer":"طابق التعبير سؤال الحواريين: ﴿هل يستطيع ربك أن ينزل علينا مائدة﴾، وأفاد مباشرة النعمة لهم مع ما يترتب عليها من عهد ومسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص113، تحت عنوان «سر التعبير بلفظ ﴿عليكم﴾ دون «إليكم»»","url":""}]},{"id":"s5-753","number":753,"surah":5,"verses":[115],"references":[{"surah":5,"verses":[115]}],"verseLabel":"المائدة: 115","question":"لماذا خُص من يكفر من الحواريين بعد المائدة بعذاب لا يعذبه أحدًا من العالمين؟","answer":"لأن كفره يقع بعد طلب الآية ومشاهدتها وقيام الحجة الباهرة عليه، فيكون جحودًا وعنادًا بعد العلم، فناسبه الوعيد الأشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص115، تحت عنوان «علة اختصاص الحواريين دون العالمين بالعذاب»","url":""}]},{"id":"s5-581","number":581,"surah":5,"verses":[115],"references":[{"surah":5,"verses":[115]}],"verseLabel":"المائدة: 115","question":"ما نكتة تنكير ﴿عذابًا﴾ في قوله تعالى: ﴿فإني أعذبه عذابًا﴾؟","answer":"نُكِّر للتهويل والتفخيم؛ أي عذابًا عظيمًا شديدًا يناسب فظاعة الكفر بعد مشاهدة الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص113–114، تحت عنوان «نكتة تنكير ﴿عذابًا﴾»","url":""}]},{"id":"s5-754","number":754,"surah":5,"verses":[115],"references":[{"surah":5,"verses":[115]}],"verseLabel":"المائدة: 115","question":"ما دلالة انتصاب ﴿عذابًا﴾ في قوله تعالى: ﴿فإني أعذبه عذابًا﴾؟","answer":"انتصب مفعولًا مطلقًا مؤكدًا لعامله، فزاد الفعل تقريرًا وثبت وقوع العذاب وشدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص114، تحت عنوان «دلالة انتصاب ﴿عذابًا﴾»","url":""}]},{"id":"s5-755","number":755,"surah":5,"verses":[115],"references":[{"surah":5,"verses":[115]}],"verseLabel":"المائدة: 115","question":"ما دلالة التعبير بـ﴿أحدًا﴾ في قوله تعالى: ﴿لا أعذبه أحدًا من العالمين﴾؟","answer":"وقعت ﴿أحدًا﴾ في سياق النفي فأفادت العموم؛ أي لا يقع مثل ذلك العذاب على أي فرد من العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص115، تحت عنوان «دلالة التعبير بـ﴿أحدًا﴾»","url":""}]},{"id":"s5-582","number":582,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"ما الحكمة التي يبينها سؤال الله عيسى عليه السلام: ﴿أأنت قلت للناس اتخذوني وأمي إلهين من دون الله﴾ مع علم الله ببراءته؟","answer":"السؤال ليس لطلب العلم، بل لإعلان براءة عيسى على رؤوس الأشهاد، وإلزام من غلا فيه بشهادته، وتوبيخهم على نسبة ما لم يأمر به إليهم؛ فيقوم الإقرار العلني حجة في مشهد القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص123–124، تحت عنوان «دلالة الاستفهام»","url":""}]},{"id":"s5-583","number":583,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"ما دلالة التعبير بقوله تعالى: ﴿إلهين من دون الله﴾ في سؤال عيسى عليه السلام؟","answer":"صرح بالتثنية لإظهار بطلان اتخاذ عيسى وأمه معبودين، ثم قيدها بـ﴿من دون الله﴾ لبيان أن ذلك صرف للألوهية عمن يستحقها وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص124–125، تحت عنوان «دلالة التعبير بقوله تعالى: ﴿إلهين﴾»","url":""}]},{"id":"s5-584","number":584,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"ما دلالة ابتداء جواب عيسى عليه السلام بقوله: ﴿سبحانك﴾؟","answer":"بدأ بتنزيه الله عن الشريك قبل الدفاع عن نفسه؛ لأن مقالة التأليه اعتداء على توحيد الله أولًا، فقدم حق ربه وأعلن براءته العقدية ثم نفى صدور القول عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص128–129، تحت عنوان «فائدة التعبير بلفظ ﴿سبحانك﴾»","url":""}]},{"id":"s5-585","number":585,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"ما نكتة التعبير بالمضارع ﴿يكون﴾ في قول عيسى: ﴿ما يكون لي أن أقول ما ليس لي بحق﴾؟","answer":"يفيد المضارع استمرار نفي الصلاحية والملابسة؛ فهذا القول لا يليق بعيسى في زمن من الأزمنة، لا أنه واقعة ماضية نفاها فحسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص129–130، تحت عنوان «نكتة التعبير بالمضارع ﴿يكون﴾»","url":""}]},{"id":"s5-756","number":756,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"لماذا قال عيسى عليه السلام: ﴿أن أقول﴾ دون «لم أقله»؟","answer":"ليبالغ في التبرؤ؛ فنفى أن يكون له أصلًا حق أو إباحة في أن يقول ذلك، وهذا أبلغ من مجرد نفي وقوع القول في الماضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص131، تحت عنوان «سر التعبير بقوله: ﴿أن أقول﴾ دون عبارة: «لم أقله»»","url":""}]},{"id":"s5-586","number":586,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"كيف ساق عيسى عليه السلام تعليلات براءته في قوله: ﴿إن كنت قلته فقد علمته﴾؟","answer":"علّق القول بالشرط، ثم رد علمه إلى الله الذي يعلم ما في نفسه؛ فإذا كان الله محيطًا بالباطن فعلمه بالقول الظاهر أولى، فانتظمت الحجة في تفويض العلم إليه وإحكام البراءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص132–133، تحت عنوان «وجه سوق صور تعليلات عيسى»","url":""}]},{"id":"s5-587","number":587,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"ما دلالة التعبير بلفظ النفس في قوله تعالى: ﴿تعلم ما في نفسي ولا أعلم ما في نفسك﴾؟","answer":"المراد بما في نفس عيسى ما استقر في باطنه وخفي من أمره، وبما عند الله ما استأثر بعلمه؛ فدل اللفظ على إحاطة علم الله بعبده وقصور علم العبد عما غاب عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص132، تحت عنوان «دلالة التعبير بلفظ النفس»","url":""}]},{"id":"s5-757","number":757,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"ما دلالة الطباق في قوله تعالى: ﴿تعلم ما في نفسي ولا أعلم ما في نفسك﴾؟","answer":"قابل بين الإثبات في ﴿تعلم﴾ والنفي في ﴿لا أعلم﴾، فبرز التفاوت الكامل بين علم الخالق المحيط وعلم المخلوق المحدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص132–133، تحت عنوان «دلالة الطباق»","url":""}]},{"id":"s5-588","number":588,"surah":5,"verses":[109,116],"references":[{"surah":5,"verses":[109,116]}],"verseLabel":"المائدة: 109، 116","question":"ما وجه المبالغة في قوله تعالى: ﴿علام الغيوب﴾ بدل «عالم الغيوب»؟","answer":"جاءت صيغة المبالغة ﴿علام﴾ ملائمة لجمع ﴿الغيوب﴾ وكثرة المعلومات، فدلت بأقصى ما تتسع له اللغة على سعة علم الله وإحاطته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص134، تحت عنوان «وجه المبالغة في ﴿علام﴾ بدلًا من «عالم»»","url":""}]},{"id":"s5-589","number":589,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]},{"surah":25,"verses":[17]}],"verseLabel":"المائدة: 116؛ الفرقان: 17","question":"ما علة تقديم المسند إليه ﴿أنت﴾ على الخبر الفعلي في قوله تعالى: ﴿أأنت قلت للناس﴾؟","answer":"جُعل الضمير في صدر السؤال لتوجيه الإنكار والتقرير إلى نسبة القول لعيسى نفسه، فتتعلق العناية بتعيين القائل قبل بيان المقولة، وتظهر براءته في جوابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص123–124، تحت عنوان «علة تقديم المسند إليه على الخبر الفعلي»","url":""}]},{"id":"s5-590","number":590,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما دلالة القصر في قوله تعالى على لسان عيسى: ﴿ما قلت لهم إلا ما أمرتني به﴾؟","answer":"هذا قصر قلب يرد دعوى أنه أمرهم بتأليهه: فقد قال ما أمره الله به وبلّغ رسالة ربه، ولم يقل شيئًا من عنده، مع نفي الزيادة على ما أُمر به؛ فدعوى الألوهية لا تجتمع مع اعترافه بالوحدانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص140–141، تحت عنوان «دلالة قصر القلب»","url":""}]},{"id":"s5-591","number":591,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما دلالة ﴿أن﴾ في قوله تعالى: ﴿ما أمرتني به أن اعبدوا الله﴾؟","answer":"تحتمل أن تكون تفسيرية لما في الأمر من معنى القول، وتحتمل أن تكون مصدرية؛ أي ما أمرتني به من عبادتكم لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص141، تحت عنوان «دلالة ﴿أن﴾»","url":""}]},{"id":"s5-758","number":758,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما نكتة البدل في قوله تعالى: ﴿أن اعبدوا الله ربي وربكم﴾؟","answer":"جاءت الجملة بدلًا أو بيانًا من ﴿ما أمرتني به﴾، فكشفت مضمون الأمر الإلهي وحددته بعبادة الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص142، تحت عنوان «نكتة البدل»","url":""}]},{"id":"s5-759","number":759,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"لماذا قدّم عيسى إثبات ربوبية الله له على إثبات ربوبيته لقومه في قوله: ﴿ربي وربكم﴾؟","answer":"بدأ بنفسه ليعلن عبوديته وأنه مربوب لله قبل أن يدعو قومه إلى العبادة، فيبطل من أصل الكلام ادعاء ألوهيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص142–143، تحت عنوان «نكتة تقديم إثبات ربوبية الله له على إثبات ربوبيته لهم»","url":""}]},{"id":"s5-592","number":592,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما دلالة وصف عيسى نفسه بقوله: ﴿وكنت عليهم شهيدًا ما دمت فيهم﴾ دون: شاهدًا؟","answer":"﴿شهيد﴾ أبلغ في ثبوت الشهادة والمراقبة واستحضار ما وقع، وقيّدها بمدة وجوده بينهم ليحدد نطاق علمه ومسؤوليته البشرية؛ فهو يشهد بما عاينه لا بما استتر بعد رفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص143، تحت عنوان «سر التعبير بلفظ ﴿شهيدًا﴾»","url":""}]},{"id":"s5-593","number":593,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما دلالة التعبير عن انتهاء مقام عيسى بين قومه بقوله تعالى: ﴿فلما توفيتني﴾؟","answer":"التوفي في أصل اللغة أخذ الشيء وافيًا، والسياق هنا يدل على انتهاء مدة إقامة عيسى بين قومه وشهادته عليهم. واللفظ يأتي للموت والنوم والرفع، وقد رجحت الموسوعة في شرح الموضع أن المراد وفاة الرفع إلى السماء؛ فلا يدل أصل اللفظ وحده على تفاصيل الكيفية دون قرائن السياق وبقية الأدلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص145، تحت عنوان «دلالة التعبير بلفظ ﴿توفيتني﴾»","url":""}]},{"id":"s5-594","number":594,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما سر العدول من ﴿شهيدًا﴾ إلى ﴿الرقيب﴾ في قول عيسى عليه السلام؟","answer":"شهادة عيسى مقيدة بمدة وجوده في قومه، أما رقابة الله فدائمة محيطة بهم قبل ذلك وبعده؛ فناسب العدول اختلاف المقامين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص144، تحت عنوان «سر العدول من لفظ ﴿الشهيد﴾ إلى لفظ ﴿الرقيب﴾»","url":""}]},{"id":"s5-760","number":760,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما فائدة ضمير الفصل ﴿أنت﴾ في قوله تعالى: ﴿كنت أنت الرقيب عليهم﴾؟","answer":"أكد الضمير اختصاص الله بالرقابة التامة المستمرة بعد توفي عيسى، وقصر هذا الإحاطة عليه سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص145، تحت عنوان «فائدة التعبير بضمير الفصل ﴿أنت﴾»","url":""}]},{"id":"s5-761","number":761,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما سر دخول «أل» على ﴿الرقيب﴾ في قوله تعالى: ﴿كنت أنت الرقيب عليهم﴾؟","answer":"أفاد التعريف كمال هذا الوصف وتحققه في الله؛ فهو الرقيب المحيط الذي لا يغيب عنه شيء من أحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص145–146، تحت عنوان «سر دخول «أل» على كلمة ﴿الرقيب﴾»","url":""}]},{"id":"s5-595","number":595,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما دلالة تقديم الجار والمجرور في قوله تعالى: ﴿وأنت على كل شيء شهيد﴾؟","answer":"قدم ﴿على كل شيء﴾ للاهتمام بعموم متعلَّق الشهادة وإبراز إحاطة علم الله بكل ظاهر وباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص147، تحت عنوان «دلالة تقديم الجار والمجرور»","url":""}]},{"id":"s5-762","number":762,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما براعة رد العجز على الصدر في قوله تعالى: ﴿وأنت على كل شيء شهيد﴾؟","answer":"عاد ختام الكلام إلى لفظ الشهادة الذي ورد في قول عيسى: ﴿وكنت عليهم شهيدًا﴾، فانتظم طرفا المعنى مع بيان الفرق بين شهادته المحدودة وشهادة الله العامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص147–148، تحت عنوان «براعة رد العجز على الصدر»","url":""}]},{"id":"s5-763","number":763,"surah":5,"verses":[117],"references":[{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117","question":"ما دلالة الاعتراض التذييلي في قوله تعالى: ﴿وأنت على كل شيء شهيد﴾؟","answer":"جاءت الجملة تذييلًا يعمم الحكم بعد خصوص الرقابة على قوم عيسى، ويقرر إحاطة شهادة الله بكل شيء في كل وقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص148، تحت عنوان «دلالة الاعتراض التذييلي»","url":""}]},{"id":"s5-596","number":596,"surah":5,"verses":[117],"references":[{"surah":3,"verses":[55]},{"surah":5,"verses":[117]}],"verseLabel":"المائدة: 117؛ آل عمران: 55","question":"ما الفرق بين قول عيسى عليه السلام: ﴿فلما توفيتني﴾، وقول الله له: ﴿إني متوفيك ورافعك إلي﴾؟","answer":"في آل عمران يرد التوفي والرفع في وعد الله لعيسى، ويستشهد المصدر بهذه الآية عند تفسير قوله في المائدة «فلما توفيتني». أما في المائدة فالتعبير يحدد انتهاء مدة إقامته في قومه وشهادته عليهم، ويرجح المصدر أن المراد توفي الرفع إلى السماء. فالأول وعد بالقبض والرفع، والثاني حكاية انتهاء مقامه بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص145، تحت «دلالة التعبير بلفظ توفيتني»","url":""}]},{"id":"s5-597","number":597,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"لماذا فُصل قوله تعالى: ﴿إن تعذبهم فإنهم عبادك﴾ عما قبله؟","answer":"جاء استئنافًا بيانيًا يجيب عما قد يثيره المقام: هل يشفع عيسى لقومه؟ ففوض أمرهم كله إلى الله في التعذيب والمغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص152، تحت عنوان «علة فصل قوله تعالى: ﴿إن تعذبهم فإنهم عبادك﴾ عما قبله»","url":""}]},{"id":"s5-764","number":764,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"ما سر إيثار قوله تعالى: ﴿فإنهم عبادك﴾ في مقام التعذيب؟","answer":"العبودية تثبت تمام ملك الله لهم وانفراده بالتصرف والحكم، فليس لأحد أن يعترض على ما يقضي به فيهم وفق عدله وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص153، تحت عنوان «سر إيثار التعبير بقوله تعالى: ﴿فإنهم عبادك﴾»","url":""}]},{"id":"s5-765","number":765,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"ما دلالة الفاء والتأكيد في قوله تعالى: ﴿فإنهم عبادك﴾؟","answer":"ربطت الفاء جواب الشرط بالتعليل، وأكدت ﴿إن﴾ ثبوت عبوديتهم واستسلام الأمر لله، فاشتد معنى التفويض إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص153–154، تحت عنوان «دلالة الفاء ودلالة التأكيد»","url":""}]},{"id":"s5-598","number":598,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"ما وجه التناسب في قوله تعالى: ﴿وإن تغفر لهم فإنك أنت العزيز الحكيم﴾؟","answer":"ناسب ذكر العزة أن المغفرة تصدر عن قدرة لا عن عجز عن العقوبة، وناسبت الحكمة أن المغفرة توضع في موضعها لمن تقتضي الحكمة مغفرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص155، تحت عنوان «فن التخيير والتناسب»","url":""}]},{"id":"s5-766","number":766,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"ما أهمية قصر صفتي العزة والحكمة على الله في قوله: ﴿فإنك أنت العزيز الحكيم﴾؟","answer":"اجتمع التوكيد وضمير الفصل وتعريف الوصفين لإثبات كمال العزة والحكمة لله وحده، وأن حكمه لا يرده أحد ولا يخرج عن موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص156، تحت عنوان «أهمية قصر صفتي العزة والحكمة على الله دون سواه»","url":""}]},{"id":"s5-767","number":767,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"ما الكناية في وصف الله تعالى بـ﴿العزيز﴾ في مقام المغفرة؟","answer":"الوصف كناية عن أن مغفرته صادرة عن تمام القدرة والغلبة؛ فهو يغفر مع القدرة على العقوبة، لا عن ضعف أو عجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص156–157، تحت عنوان «براعة الكناية في قوله تعالى: ﴿فإنك أنت العزيز الحكيم﴾»","url":""}]},{"id":"s5-599","number":599,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"ما سرّ تقديم احتمال العذاب على المغفرة في قول عيسى عليه السلام؟","answer":"قُدّم العذاب لأن الآية جاءت بعد الوعيد الشديد لمن يكفر بعد نزول المائدة، ولأنها في سياق تبرؤ عيسى من مقالة طائفة من النصارى نسبت إليه دعوة الناس إلى اتخاذه وأمه إلهين؛ فناسب البدء بما يوافق سياق الوعيد والتبرؤ، ثم فُوض أمر المغفرة إلى مشيئة الله وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص154–155، تحت «دلالة تقديم لفظ التعذيب على لفظ المغفرة»","url":""}]},{"id":"s5-600","number":600,"surah":5,"verses":[118],"references":[{"surah":5,"verses":[118]}],"verseLabel":"المائدة: 118","question":"ما دلالة ضمير الفصل في قوله تعالى: ﴿فإنك أنت العزيز الحكيم﴾؟","answer":"يفيد ﴿أنت﴾ توكيد اختصاص الله بكمال العزة والحكمة؛ فهو وحده القادر على إنفاذ العذاب أو المغفرة، العالم بموضع كل منهما، وليس لعيسى إلا التسليم لحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص156، تحت «أهمية قصر صفتي العزة والحكمة على الله دون سواه»","url":""}]},{"id":"s5-601","number":601,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"لماذا قيل: ﴿هذا يوم ينفع الصادقين صدقهم﴾ دون «صدقت»؟","answer":"عدل إلى الاسم ليكون الحكم عامًا في الصدق، وليشهد لعيسى الذي برأ نفسه بصدق كامل، ويدخل فيه كل صادق في إيمانه وقوله وعمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص164، تحت عنوان «سر التعبير بقوله تعالى: ﴿ينفع الصادقين صدقهم﴾ دون: «صدقت»»","url":""}]},{"id":"s5-768","number":768,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"ما دلالة التعريف في لفظ ﴿الصادقين﴾؟","answer":"أفاد استغراق جنس الصادقين الكاملين في صدقهم، فشمل أهل الإيمان الذين وافق ظاهرهم باطنهم واستقام قولهم وعملهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص164–165، تحت عنوان «دلالة اللام في ﴿الصادقين﴾»","url":""}]},{"id":"s5-602","number":602,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"ما دلالة الإشارة في قوله تعالى: ﴿هذا يوم ينفع الصادقين صدقهم﴾ كأن اليوم حاضر؟","answer":"استحضرت الإشارة يوم القيامة حتى صار كالمشاهد القريب، ولا سيما بعد الحوار المعروض بين الله وعيسى؛ فيقوى اليقين بالجزاء ويشعر السامع أن الحكم يعلن أمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص163، تحت «سر التعبير باسم الإشارة هذا ودلالة المشاكلة»","url":""}]},{"id":"s5-604","number":604,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"ما دلالة التعطف في قوله تعالى: ﴿رضي الله عنهم ورضوا عنه﴾؟","answer":"صور رضا الله عن عباده وما قابلوه به من رضا عن جزائه وفضله، فاجتمع الإكرام الإلهي وطمأنينة العباد بما أعطاهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص170، تحت عنوان «دلالة التعطف»","url":""}]},{"id":"s5-769","number":769,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"ما براعة الترقي في الانتقال من الجنات إلى قوله تعالى: ﴿رضي الله عنهم ورضوا عنه﴾؟","answer":"ترقى السياق من نعيم الجنات الحسي إلى نعيم الرضوان الأعلى؛ فرضا الله أعظم من كل ما في الجنة من نعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص169–170، تحت عنوان «براعة الترقي في الآية الكريمة»","url":""}]},{"id":"s5-605","number":605,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"ما سر التعبير باسم الإشارة البعيد ﴿ذلك﴾ في قوله تعالى: ﴿ذلك الفوز العظيم﴾؟","answer":"استعمل اسم البعيد لتعظيم المشار إليه ورفع منزلته، وهو مجموع الخلود في الجنات ورضا الله عن الصادقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص170، تحت عنوان «سر التعبير باسم الإشارة ﴿ذلك﴾»","url":""}]},{"id":"s5-770","number":770,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"ما دلالة التعريف في لفظ ﴿الفوز﴾؟","answer":"يفيد أن هذا هو الفوز المعروف الكامل الذي يجمع حصول أعظم المطلوب والنجاة من أعظم المرهوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص170–171، تحت عنوان «دلالة اللام في ﴿الفوز﴾»","url":""}]},{"id":"s5-771","number":771,"surah":5,"verses":[119],"references":[{"surah":5,"verses":[119]}],"verseLabel":"المائدة: 119","question":"ما دلالة وصف الفوز بـ﴿العظيم﴾؟","answer":"عظمه لأنه يضم الخلود في النعيم ورضا الله، فلا يساويه نجاح مؤقت ولا نعيم زائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص171، تحت عنوان «دلالة وصف الفوز بالعظمة»","url":""}]},{"id":"s5-606","number":606,"surah":5,"verses":[120],"references":[{"surah":5,"verses":[120]}],"verseLabel":"المائدة: 120","question":"ما مناسبة ختم السورة بملك الله للسماوات والأرض؟","answer":"بعد محاجة من ألّه المسيح وأمه، وخضوع الرسل للحساب، ختمت السورة بأن الملك كله لله؛ فكل من في السماوات والأرض مملوك له، وبذلك يعود ختام السورة إلى أصل التوحيد الذي حسم حوارها الأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص181، تحت عنوان «بلاغة حسن ختام السورة»","url":""}]},{"id":"s5-607","number":607,"surah":5,"verses":[120],"references":[{"surah":5,"verses":[120]},{"surah":42,"verses":[49]}],"verseLabel":"المائدة: 120؛ الشورى: 49","question":"ما دلالة زيادة ﴿وما فيهن﴾ في خاتمة المائدة: ﴿لله ملك السماوات والأرض وما فيهن﴾، وعدم ذكرها في موضع الشورى؟","answer":"صرحت المائدة بـ﴿وما فيهن﴾ لأنها جاءت في ختام الرد على من اتخذ عيسى وأمه إلهين، فناسب المبالغة في بيان سعة ملك الله ودحض شبهة مشاركته فيه. أما الشورى فلم يسبق آية الملك فيها ذكر شرك أو منازعة في الملك، فناسب عدم ذكر العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص181–182، تحت «دلالة ذكر عبارة وما فيهن في آية سورة المائدة دون آية سورة الشورى»","url":""}]},{"id":"s5-608","number":608,"surah":5,"verses":[17,18,120],"references":[{"surah":5,"verses":[17,18,120]}],"verseLabel":"المائدة: 17–18، 120","question":"ما سر تذييل قوله تعالى: ﴿إن أراد أن يهلك المسيح ابن مريم وأمه ومن في الأرض جميعًا﴾ بذكر ملك السماوات والأرض؟","answer":"جاء ذكر الملك والخلق بعد الشرط ونفي المانع ليقرر أن المسيح وأمه وسائر الخلق مملوكون لله، وأن قدرته نافذة فيهم ولا يملك أحد رد إرادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص734–735، تحت عنوان «سر التذييل بذكر الملك والخلق بعد الشرط ونفي المانع»","url":""}]},{"id":"s5-609","number":609,"surah":5,"verses":[120],"references":[{"surah":5,"verses":[120]}],"verseLabel":"المائدة: 120","question":"لماذا قيل ﴿وما فيهن﴾ ولم يقل: ومن فيهن؟","answer":"«ما» أعم في هذا المقام؛ فتتناول العاقل وغير العاقل، بخلاف «من» المختصة في أصل وضعها بالعقلاء. وفيها تقرير شمول ملك الله لكل ما في السماوات والأرض، والتنبيه إلى افتقار المخلوقات جميعًا إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص179، تحت عنوان «سر التعبير بقوله تعالى: ﴿وما فيهن﴾ عوضًا عن «ومن فيهن»»","url":""}]},{"id":"s5-610","number":610,"surah":5,"verses":[120],"references":[{"surah":5,"verses":[120]}],"verseLabel":"المائدة: 120","question":"لماذا ختمت آية المائدة بـ﴿قدير﴾، وجاء في الأنعام ﴿وكيل﴾، وفي سبأ ﴿شهيد﴾؟","answer":"ناسب ﴿قدير﴾ في المائدة ذكر الملك الشامل، فالملك لا يقوم إلا بتمام القدرة. وناسب ﴿وكيل﴾ في الأنعام مقام الخلق والرزق والقيام بأمر العباد، وناسب ﴿شهيد﴾ في سبأ مقام تبليغ الرسول وشهادة الله على صدقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص182–183، تحت عنوان «تغير الأسماء الحسنى بين ﴿قدير﴾ و﴿وكيل﴾ و﴿شهيد﴾ في مواقعها من سورها»","url":""}]},{"id":"s6-1","number":1,"surah":6,"verses":[1],"references":[{"surah":6,"verses":[1]}],"verseLabel":"الأنعام: 1","question":"ما مناسبة افتتاح سورة الأنعام بقوله تعالى: ﴿الحمد لله﴾؟","answer":"افتتحت السورة بالحمد براعة استهلال؛ لأن مقصدها تقرير التوحيد بإظهار نعمتي الإيجاد والإمداد، ومن دلائلهما خلق السماوات والأرض وجعل الظلمات والنور.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص202، تحت عنوان «براعة الاستهلال في افتتاح السورة»","url":""}]},{"id":"s6-1036","number":1036,"surah":6,"verses":[1],"references":[{"surah":6,"verses":[1]}],"verseLabel":"الأنعام: 1","question":"ما بلاغة مجيء ﴿الحمد لله﴾ في افتتاح الأنعام خبرًا لفظًا ومعنى؟","answer":"قرر الخبر ثبوت الحمد واستحقاق الله له قبل أن يحمده الخلق؛ فالجملة تثبت حقيقة دائمة، وتناسب مقام الاستدلال بآثار الخلق والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص204، تحت عنوان «بلاغة القول بخبرية الحمد لله لفظًا ومعنى»","url":""}]},{"id":"s6-2","number":2,"surah":6,"verses":[1],"references":[{"surah":6,"verses":[1]}],"verseLabel":"الأنعام: 1","question":"ما الفرق بين التعبير بالخلق في ﴿خلق السماوات والأرض﴾، وبالجعل في ﴿وجعل الظلمات والنور﴾؟","answer":"الخلق أنسب بإيجاد الذوات، وفيه معنى التقدير والإبداع؛ فاقترن بالسماوات والأرض. أما الجعل فأنسب بإيجاد أعراض الذوات وأحوالها ونظامها، ويتضمن الإنشاء من شيء أو التصيير والتحويل؛ فناسب الظلمات والنور. وبهذا جاء كل فعل ملائمًا لما اقترن به.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص207، تحت «سر التعبير بالخلق والجعل، واختصاص كل في الآية الكريمة»","url":""}]},{"id":"s6-3","number":3,"surah":6,"verses":[1,3],"references":[{"surah":6,"verses":[1,3]}],"verseLabel":"الأنعام: 1، 3","question":"ما سرّ جمع ﴿السماوات﴾ وإفراد ﴿الأرض﴾ في سورة الأنعام؟","answer":"جُمعت السماوات للدلالة على تعددها، وأُفردت الأرض لأن لفظها يجري مجرى اسم الجنس، ولأن جموعها أثقل في النظم. ومن الوجوه المذكورة أن إفرادها يشير إلى وحدتها بالنسبة إلى عالم السماوات؛ فالاختيار يراعي المعنى وفصاحة اللفظ والسياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص208–209، تحت «سر جمع السماوات وإفراد الأرض»","url":""}]},{"id":"s6-5","number":5,"surah":6,"verses":[1],"references":[{"surah":6,"verses":[1]}],"verseLabel":"الأنعام: 1","question":"ما سرّ تقديم الظلمات على النور؟","answer":"قُدمت الظلمات لأن الظلمة عدم النور، والعدم متقدم على وجود المحدثات في التقدير والتحقق؛ ولأن الظلمات كثيرة والنور واحد. وفي الجانب المعنوي تسبق ظلمات الجهل والأهواء نور العلم والهداية المكتسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص212، تحت «سر تقديم لفظ الظلمات على لفظ النور في سياق الآية»","url":""}]},{"id":"s6-6","number":6,"surah":6,"verses":[1],"references":[{"surah":6,"verses":[1]}],"verseLabel":"الأنعام: 1","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم الذين كفروا بربهم يعدلون﴾ بعد دلائل الخلق؟","answer":"﴿ثم﴾ للتراخي الرتبي والتعجيب: بعد وضوح انفراد الله بخلق السماوات والأرض والظلمات والنور يبلغ التناقض غايته حين يجعل الكافر بربه عدلًا وشبيهًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص213–214، تحت «دلالة ثم على جملة من المعاني في قوله: ﴿ثم الذين كفروا﴾»","url":""}]},{"id":"s6-7","number":7,"surah":6,"verses":[1],"references":[{"surah":6,"verses":[1]}],"verseLabel":"الأنعام: 1","question":"ما دلالة تقديم ﴿بربهم﴾ في قوله تعالى: ﴿بربهم يعدلون﴾؟","answer":"قدم الجار والمجرور لإبراز موضع الجريمة والتعجيب منه: بربهم، الذي خلق وأنعم وربّاهم، يسوّون غيره! فالتقديم يركز الإنكار على المقابلة بين الرب المنعم والشريك المزعوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص214–215، تحت «دلالة تقديم المتعلق ﴿بربهم﴾ على ﴿يعدلون﴾»","url":""}]},{"id":"s6-8","number":8,"surah":6,"verses":[1],"references":[{"surah":6,"verses":[1]}],"verseLabel":"الأنعام: 1","question":"ما دلالة اختيار فعل ﴿يعدلون﴾ للتعبير عن الشرك؟","answer":"العدل هنا جعل الشيء عدلًا ونظيرًا لغيره، فيصور المشركين يسوّون المخلوق بالخالق، ويتضمن أيضًا ميلهم وعدولهم عن الحق؛ فجمع اللفظ التسوية الجائرة والانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص216، تحت «إيثار التعبير بالفعل ﴿يعدلون﴾»","url":""}]},{"id":"s6-9","number":9,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما دلالة قوله تعالى: ﴿هو الذي خلقكم من طين﴾ مع أن أفراد البشر يُخلقون من نطفة؟","answer":"أُسند خلق المخاطبين من طين لأن ابتداء خلق النوع الإنساني كان من آدم أبي البشر الذي خُلق من طين؛ فذُكر الأصل الأول للنوع، مع أن الذرية بعده تُخلق من نطفة الذكر وبويضة الأنثى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص220–221، تحت «إعجاز مبين في قوله: ﴿خلقكم من طين﴾».","url":""}]},{"id":"s6-10","number":10,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما دلالة الظرف ﴿عنده﴾ في قوله تعالى: ﴿وأجل مسمى عنده﴾؟","answer":"يفيد اختصاص علم ذلك الأجل بالله؛ فهو مثبت مقدر في علمه، ولا يطلع على حقيقته ووقته أحد سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص224–225، تحت عنوان «دلالة التعبير بالظرف ﴿عنده﴾»","url":""}]},{"id":"s6-11","number":11,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما سر تنكير ﴿أجلًا﴾ وتخصيص الأجل الثاني بقوله: ﴿وأجل مسمى﴾؟","answer":"جاء الأول نكرة لأنه أجل الجنس المعروف بانتهاء الحياة، وخصص الثاني بوصف ﴿مسمى﴾ ليدل على أجل معين مقدر لا يتقدم ولا يتأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص224، تحت عنوان «دلالة تنكير ﴿أجلًا﴾ وتخصيص ﴿وأجل مسمى﴾»","url":""}]},{"id":"s6-1037","number":1037,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما دلالة تقديم ﴿أجل مسمى﴾ على الظرف ﴿عنده﴾؟","answer":"قُدِّم الأجل المسمى للاهتمام به وتعظيم شأنه، ثم جاء ﴿عنده﴾ لبيان أن تعيينه والعلم بوقته مختصان بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص224–225، تحت عنوان «دلالة تقديم النكرة المخصصة ﴿وأجل مسمى﴾ على الظرف ﴿عنده﴾»","url":""}]},{"id":"s6-12","number":12,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما سرّ تقديم ﴿أجلًا﴾ على ﴿أجل مسمى عنده﴾؟","answer":"جاء الترتيب على ما يلقاه الإنسان: أجله القريب بالموت أولًا، ثم الأجل الجامع للبعث والجزاء؛ فانتقل من نهاية الفرد المشاهدة إلى النهاية الكبرى المغيبة عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص223–224، تحت «تقديم ﴿أجلًا﴾ على ﴿وأجل مسمى﴾»","url":""}]},{"id":"s6-13","number":13,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما المعاني التي أفادها العطف بـ﴿ثم﴾ في قوله تعالى: ﴿ثم أنتم تمترون﴾؟","answer":"أفاد استبعاد امترائهم والتعجيب منه والتراخي الرتبي؛ إذ وقع الشك بعد قيام دلائل الخلق وتقدير الآجال، فكان أبعد عن مقتضى العقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص225–226، تحت عنوان «إفادة ﴿ثم﴾ جملة من المعاني»","url":""}]},{"id":"s6-1038","number":1038,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما نكتة ذكر المسند إليه ﴿أنتم﴾ في قوله تعالى: ﴿ثم أنتم تمترون﴾؟","answer":"أبرز الضمير المخاطبين وواجههم بفعلهم لزيادة التوبيخ: أنتم أنفسكم تمترون بعد مشاهدة دليل الخلق وسماع خبر الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص226، تحت عنوان «نكتة ذكر المسند إليه ﴿أنتم﴾»","url":""}]},{"id":"s6-1039","number":1039,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما سر تقديم ﴿أنتم﴾ على المسند الفعلي ﴿تمترون﴾؟","answer":"جعل التقديم موضع العناية ذوات المخاطبين، فقوّى الإنكار والتعجيب من صدور الامتراء منهم خاصة بعد وضوح الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص226–227، تحت عنوان «سر تقديم المسند إليه على المسند الفعلي»","url":""}]},{"id":"s6-14","number":14,"surah":6,"verses":[2],"references":[{"surah":6,"verses":[2]}],"verseLabel":"الأنعام: 2","question":"ما الفرق بين ﴿تمترون﴾ و«تشكّون»؟","answer":"الامتراء في السياق يجمع الشك والمماراة والجدال؛ فهو تردد واضطراب يظهر في خصومة المشركين في قدرة الله على البعث بعد قيام دلائل الخلق، وليس مجرد ذكر شك عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص217–219، تحت «شرح المفردات: ﴿تمترون﴾»","url":""}]},{"id":"s6-15","number":15,"surah":6,"verses":[3],"references":[{"surah":6,"verses":[3]}],"verseLabel":"الأنعام: 3","question":"كيف يُفهم قوله تعالى: ﴿وهو الله في السماوات وفي الأرض﴾ مع تنزهه سبحانه عن المكان؟","answer":"المعنى أنه المعبود المسمى الله في السماوات وفي الأرض، أو أن ألوهيته وعلمه وسلطانه نافذة فيهما؛ وليس المراد حلول ذاته في مكان، تعالى الله عن ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص232–233، تحت «دلالة الظرفية بالحرف «في» وتعلقها باسم الجلالة»","url":""}]},{"id":"s6-16","number":16,"surah":6,"verses":[3],"references":[{"surah":6,"verses":[3]}],"verseLabel":"الأنعام: 3","question":"ما دلالة مجيء الاسم الظاهر ﴿الله﴾ بعد الضمير في قوله تعالى: ﴿وهو الله في السماوات وفي الأرض﴾؟","answer":"يتقدم الضمير فيتشوف السامع إلى ما يخبر به عنه، ثم يأتي اسم الجلالة ليقرر انفراده سبحانه بالألوهية؛ فهو المعروف بهذا الاسم، لا يلتبس بغيره ولا يشاركه أحد في صفات الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص232، تحت «سر تأخير الاسم الظاهر عن الضمير في ﴿وهو الله﴾»","url":""}]},{"id":"s6-17","number":17,"surah":6,"verses":[3],"references":[{"surah":6,"verses":[3]}],"verseLabel":"الأنعام: 3","question":"ما دلالة إضافة السر والجهر إلى المخاطبين في قوله تعالى: ﴿يعلم سركم وجهركم﴾؟","answer":"الإضافة تحملهم مسؤولية ما يخفون وما يعلنون، وتخص الحجة بأحوالهم التي قد يظنون أن بعضها مستور؛ فعلمه محيط بسر كل واحد وجهره، لا بالمفهوم المجرد وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص235، تحت «نكتة إضافة السر والجهر إلى ضمير المخاطبين»","url":""}]},{"id":"s6-18","number":18,"surah":6,"verses":[3],"references":[{"surah":6,"verses":[3]}],"verseLabel":"الأنعام: 3","question":"ما سرّ تقديم السر على الجهر؟","answer":"قُدّم السر لأن المراد به صفات القلب الداعية إلى الفعل أو الصارفة عنه، وهي المؤثرة في أعمال الجوارح المسماة بالجهر؛ فكان تقديم العلة على معلولها أولى في البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص235، تحت «سبب تقديم السر على الجهر في ﴿سركم وجهركم﴾»","url":""}]},{"id":"s6-19","number":19,"surah":6,"verses":[3],"references":[{"surah":6,"verses":[3]}],"verseLabel":"الأنعام: 3","question":"ما دلالة عطف قوله تعالى: ﴿ويعلم ما تكسبون﴾ بعد علمه بسرهم وجهرهم؟","answer":"عُطف ﴿ويعلم ما تكسبون﴾ مع أن الكسب داخل في عموم السر والجهر لإظهار كمال الاعتناء به؛ لأنه مدار الجزاء، ولذلك أعيد فعل ﴿يعلم﴾، والكسب يشمل أعمال القلوب والجوارح سرًا وعلانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص235–236، تحت «السر في تكرار ﴿يعلم﴾ وبلاغة التعبير بالفعل ﴿تكسبون﴾»","url":""}]},{"id":"s6-20","number":20,"surah":6,"verses":[3],"references":[{"surah":6,"verses":[3]}],"verseLabel":"الأنعام: 3","question":"ما بلاغة التعبير عن الأعمال بالفعل ﴿تكسبون﴾؟","answer":"الكسب ما يتعمده الإنسان لجلب نفع أو دفع ضر، فعبّر به عن الأعمال والاعتقادات لإبراز تعلق الجزاء بما يختاره المرء ويسعى فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص235–236، تحت عنوان «بلاغة التعبير بالفعل ﴿تكسبون﴾»","url":""}]},{"id":"s6-1040","number":1040,"surah":6,"verses":[3],"references":[{"surah":6,"verses":[3]}],"verseLabel":"الأنعام: 3","question":"ما دلالة ﴿ما﴾ في قوله تعالى: ﴿ويعلم ما تكسبون﴾؟","answer":"جاءت موصولة عامة فشملت كل ما يكتسبه الإنسان من خير وشر، وظاهر وباطن، من غير أن يخرج شيء عن علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص236، تحت عنوان «دلالة ﴿ما﴾ في قوله تعالى: ﴿ويعلم ما تكسبون﴾»","url":""}]},{"id":"s6-21","number":21,"surah":6,"verses":[4],"references":[{"surah":6,"verses":[4]}],"verseLabel":"الأنعام: 4","question":"ما دلالة تكرار ﴿من﴾ في قوله تعالى: ﴿وما تأتيهم من آية من آيات ربهم﴾؟","answer":"الأولى زائدة من جهة الصناعة النحوية، وفائدتها التوكيد واستغراق جنس الآيات في سياق النفي؛ أما الثانية فللتبعيض، أي: ما يظهر لهم دليل من جملة آيات ربهم إلا أعرضوا عنه، فتكرر الحرف لاختلاف وظيفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص239–240، تحت «دلالة حرف الجر «من» في قوله: ﴿من آية من آيات ربهم﴾»","url":""}]},{"id":"s6-22","number":22,"surah":6,"verses":[4],"references":[{"surah":6,"verses":[4]}],"verseLabel":"الأنعام: 4","question":"ما الصورة في قوله تعالى: ﴿تأتيهم من آية﴾؟","answer":"شُبه بلوغ الآيات إليهم بمجيء الجائي، فحذف المشبه وصرح بالمشبه به في استعارة تصريحية تبعية؛ للمبالغة في ظهور الآيات وقوتها حتى صارت بمنزلة المحسوسات، ومع ذلك أعرضوا عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص239، تحت «بلاغة الاستعارة في قول الله تعالى: ﴿وما تأتيهم﴾»","url":""}]},{"id":"s6-23","number":23,"surah":6,"verses":[4],"references":[{"surah":6,"verses":[4]}],"verseLabel":"الأنعام: 4","question":"ما نكتة التعبير بالمضارع ﴿تأتيهم﴾ في قوله تعالى: ﴿وما تأتيهم من آية﴾؟","answer":"يستحضر المضارع تجدد مجيء الآيات وتتابعها، فيقابل كثرة الحجج بتجدد إعراضهم عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص240، تحت عنوان «نكتة التعبير بالفعل المضارع في قوله: ﴿تأتيهم﴾»","url":""}]},{"id":"s6-1041","number":1041,"surah":6,"verses":[4],"references":[{"surah":6,"verses":[4]}],"verseLabel":"الأنعام: 4","question":"ما دلالة فعل الكون ﴿كانوا﴾ في قوله تعالى: ﴿كانوا عنها معرضين﴾؟","answer":"دل على أن الإعراض صار شأنًا ثابتًا متكررًا لهم كلما جاءتهم آية، لا موقفًا عارضًا وقع مرة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص242، تحت عنوان «دلالة التعبير بفعل الكون ﴿كانوا﴾»","url":""}]},{"id":"s6-1042","number":1042,"surah":6,"verses":[4],"references":[{"surah":6,"verses":[4]}],"verseLabel":"الأنعام: 4","question":"ما دلالة التعبير بالاسم ﴿معرضين﴾؟","answer":"دل اسم الفاعل على ثبوت الإعراض ورسوخه فيهم، فناسب استمرار صدهم عن الآيات مع تجدد ورودها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص242–243، تحت عنوان «دلالة التعبير بالاسم في قوله: ﴿معرضين﴾»","url":""}]},{"id":"s6-24","number":24,"surah":6,"verses":[4],"references":[{"surah":6,"verses":[4]}],"verseLabel":"الأنعام: 4","question":"ما دلالة تقديم ﴿عنها﴾ في قوله تعالى: ﴿إلا كانوا عنها معرضين﴾؟","answer":"قدم الجار والمجرور لإبراز أن إعراضهم واقع عن الآية نفسها مع كونها من آيات ربهم، ولتوجيه الذم إلى موقفهم منها قبل وصفهم الراسخ بالإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص241–242، تحت «سر تقديم الجار والمجرور على المسند» في قوله تعالى: ﴿إلا كانوا عنها معرضين﴾.","url":""}]},{"id":"s6-25","number":25,"surah":6,"verses":[4],"references":[{"surah":6,"verses":[4]}],"verseLabel":"الأنعام: 4","question":"ما دلالة وصفهم بقوله تعالى: ﴿معرضين﴾ بالاسم دون: يعرضون؟","answer":"اسم الفاعل يثبت الإعراض صفة راسخة فيهم، لا فعلًا عابرًا يقع ثم يزول؛ ولذلك ناسب تكرر مجيء الآيات مع ثبات موقفهم منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص242–243، تحت «دلالة التعبير بالاسم في قوله: ﴿معرضين﴾»","url":""}]},{"id":"s6-26","number":26,"surah":6,"verses":[4,5],"references":[{"surah":6,"verses":[4,5]}],"verseLabel":"الأنعام: 4–5","question":"كيف يتصاعد وصف موقفهم من ﴿معرضين﴾ إلى ﴿كذبوا بالحق﴾ ثم ﴿يستهزئون﴾؟","answer":"رتب السياق أحوالهم من الأقل إلى الأشد: بدأ بالإعراض عن النظر في الدلائل، ثم ذكر تكذيبهم بها، ثم استهزاءهم؛ فالاستهزاء أغلظ من مجرد التكذيب، وباجتماع هذه المراتب يبلغ رفضهم للحق غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص247، تحت «الترقي وتصعيد المعاني»","url":""}]},{"id":"s6-27","number":27,"surah":6,"verses":[5],"references":[{"surah":6,"verses":[5]}],"verseLabel":"الأنعام: 5","question":"ما دلالة تقييد التكذيب بقوله تعالى: ﴿لما جاءهم﴾؟","answer":"يبين أنهم بادروا إلى التكذيب وقت مجيء الحق من غير نظر ولا مهلة تدبر؛ فالجملة تشدد لومهم لأن ردهم لم ينشأ من غياب الحجة بل وقع عند حضورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص248، تحت «نكتة تعليق التكذيب على مطلق مجيء الحق».","url":""}]},{"id":"s6-28","number":28,"surah":6,"verses":[5],"references":[{"surah":6,"verses":[5]}],"verseLabel":"الأنعام: 5","question":"ما دلالة تسمية ما سيأتيهم ﴿أنباء ما كانوا به يستهزئون﴾؟","answer":"الأنباء هنا ليست مجرد أخبار، بل ما سيأتيهم من العذاب الذي أنبأ الله به، أو تحقق مضمون الخبر ومصداق ما استهزؤوا به؛ واختيار لفظ النبأ يهول شأن الوعيد لأنه خبر خطير عظيم الوقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص248–249، تحت «سر التعبير بلفظ ﴿أنباء﴾ في مقام الوعيد»","url":""}]},{"id":"s6-29","number":29,"surah":6,"verses":[5],"references":[{"surah":6,"verses":[5]}],"verseLabel":"الأنعام: 5","question":"ما دلالة ﴿سوف﴾ في قوله تعالى: ﴿فسوف يأتيهم أنباء ما كانوا به يستهزئون﴾؟","answer":"ينقل حرف التسويف الوعيد إلى المستقبل مع تأكيد حصوله: فما أخبر الله به من جزاء استهزائهم سيصيبهم. فعدم وقوع العقاب في الحال لا يعني سقوط الوعيد أو النجاة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص248، تحت «وجه دخول حرف التسويف ﴿فسوف﴾ في الجزاء»","url":""}]},{"id":"s6-30","number":30,"surah":6,"verses":[5],"references":[{"surah":6,"verses":[5]},{"surah":15,"verses":[11]}],"verseLabel":"الأنعام: 5؛ الحجر: 11","question":"ما دلالة تقديم ﴿به﴾ في قوله تعالى: ﴿ما كانوا به يستهزئون﴾ في سورة الأنعام؟","answer":"قدم الجار والمجرور للاهتمام بالحق الذي اتخذوه موضع استهزاء، وفي التقديم زيادة تهديد؛ إذ يبرز التباين بين سخريتهم منه وبين ما سيحيق بهم بسببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص249–250، تحت عنوان «فائدة تقديم الجار والمجرور في قوله: ﴿به يستهزئون﴾»","url":""}]},{"id":"s6-31","number":31,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"لماذا فُصل قوله تعالى: ﴿ألم يروا كم أهلكنا من قبلهم من قرن﴾ عما قبله؟","answer":"جاء استئنافًا يبين صدق الوعيد السابق بدليل تاريخي معلوم؛ فإهلاك القرون الماضية شاهد مستقل على أن ما وُعدوا به واقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص255، تحت عنوان «علة فصل قول الله تعالى: ﴿ألم يروا كم أهلكنا﴾ عما قبله»","url":""}]},{"id":"s6-1043","number":1043,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ألم يروا كم أهلكنا من قبلهم من قرن﴾؟","answer":"هو استفهام إنكاري توبيخي؛ ينكر عليهم ترك الاعتبار بما علموه من مصارع الأمم، وينبههم إلى أن آثار الهلاك بمنزلة المشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص255، تحت عنوان «دلالة الاستفهام الإنكاري التوبيخي»","url":""}]},{"id":"s6-32","number":32,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما دلالة تسمية الأمم الماضية ﴿قرنًا﴾؟","answer":"القرن جماعة من الناس اقترنت في زمن واحد أو تعاقبت فيه، فالتعبير يصور كل أمة وحدة تاريخية لها تمكينها ثم تنقضي ويأتي بعدها غيرها؛ وهو أنسب بسياق تعاقب الهلاك والإنشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص252–253، تحت «شرح المفردات: ﴿قرن﴾»","url":""}]},{"id":"s6-33","number":33,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما الفرق بين قوله تعالى: ﴿مكناهم في الأرض﴾ وقوله: ﴿ما لم نمكن لكم﴾؟","answer":"عُدّي الأول بنفسه لإبراز قوة تمكين الأمم السابقة ورسوخه، وجاء الثاني باللام لبيان ما جعل للمخاطبين من أسباب الانتفاع؛ والمقابلة تهددهم بأن من هلك كان أشد تمكينًا منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص258–259، تحت عنوان «الفرق بين (مكّنه) و(مكّن له)، وأثر ذلك في السياق»","url":""}]},{"id":"s6-34","number":34,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما دلالة تقديم السماء في قوله تعالى: ﴿وأرسلنا السماء عليهم مدرارًا﴾؟","answer":"قُدّم إرسال السماء على جعل الأنهار تجري لأن تتابع المطر سبب لجريانها، وفيه اتساع الرزق وخصب الأرض؛ فالجملة الأولى سبب للثانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص263، تحت «بلاغة تقديم إرسال السماء على جعل الأنهار تجري»","url":""}]},{"id":"s6-35","number":35,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما دلالة قوله تعالى: ﴿وأرسلنا السماء﴾ مع أن المنزل هو المطر؟","answer":"أطلق المحل وأريد ما ينزل منه، أي المطر، حتى صارت السماء نفسها كأنها مرسلة عليهم بكثرة مائها؛ وفي ذلك مبالغة في وفرة النعمة واتصالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص260–261، تحت «بلاغة المجاز المرسل في قوله: ﴿وأرسلنا السماء﴾»","url":""}]},{"id":"s6-36","number":36,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما دلالة وصف السماء بقوله تعالى: ﴿مدرارًا﴾؟","answer":"﴿مدرارًا﴾ صيغة مبالغة من الدر، تدل على مطر كثير متتابع غزير لا دفعة عابرة؛ فتلائم تعداد قوة تمكين تلك الأمم وسعة رزقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص261، تحت «وجه صيغة المبالغة على زنة «مفعال» في قوله: ﴿مدرارًا﴾»","url":""}]},{"id":"s6-37","number":37,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿وجعلنا الأنهار تجري من تحتهم﴾؟","answer":"تفيد ابتداء جريان الأنهار من تحتهم، فتصف قرب منابعها. وهذا أبلغ في بيان النعمة من مجرد مرور ماء يأتي من مكان بعيد؛ إذ يدل على سهولة وصولهم إلى مطلعها وانتفاعهم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص263، تحت «دلالة دخول ﴿من﴾ على الظرف ﴿تحتهم﴾»","url":""}]},{"id":"s6-38","number":38,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما دلالة عطف الإهلاك على جريان الأنهار في قوله تعالى: ﴿تجري من تحتهم الأنهار فأهلكناهم﴾؟","answer":"أفادت الفاء حصول الإهلاك عقب التمكين والإنعام، مع تقدير ما دل عليه السياق: فكفروا وعصوا؛ فظهر أن سبب الهلاك ذنوبهم لا النعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص263، تحت عنوان «دلالة عطف الإهلاك على جعل الأنهار تجري»","url":""}]},{"id":"s6-1044","number":1044,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما سر التعبير عن الكفر بالذنوب في قوله تعالى: ﴿فأهلكناهم بذنوبهم﴾؟","answer":"أدخل كفرهم وتكذيبهم في جنس الذنوب ليقرر أن الجناية هي سبب الهلاك، وليحذر من الذنوب كلها لأنها طريق العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص263–264، تحت عنوان «سر التعبير عن الكفر بالذنب في ﴿فأهلكناهم بذنوبهم﴾»","url":""}]},{"id":"s6-39","number":39,"surah":6,"verses":[6],"references":[{"surah":6,"verses":[6]}],"verseLabel":"الأنعام: 6","question":"ما الذي تضيفه كلمة ﴿آخرين﴾ في قوله تعالى: ﴿وأنشأنا من بعدهم قرنًا آخرين﴾؟","answer":"تؤكد أن الذين أنشأهم الله بعد المهلكين جماعة أخرى غيرهم؛ فلا يلتبس القرن الجديد بالقرن السابق، وفي ذلك بيان قدرته على إهلاك قوم وإقامة غيرهم مقامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص265، تحت «نكتة وصف ﴿قرنًا﴾ بـ﴿آخرين﴾»","url":""}]},{"id":"s6-40","number":40,"surah":6,"verses":[7],"references":[{"surah":6,"verses":[7]}],"verseLabel":"الأنعام: 7","question":"ما دلالة تقييد الكتاب بقوله تعالى: ﴿في قرطاس﴾؟","answer":"ذُكر القرطاس ليبلغ الدليل غاية الحس: كتاب في صحيفة ثابتة مكتوبة يرونه عيانًا ويلمسونه بأيديهم؛ ومع ذلك يخبر الله أنهم لا يؤمنون به، بل يصفونه بالسحر والتمويه والخيال، فينكشف أن المانع عنادهم لا خفاء الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص268–269، تحت عنوان «شرح المفردات: ﴿قرطاس﴾»","url":""}]},{"id":"s6-41","number":41,"surah":6,"verses":[7],"references":[{"surah":6,"verses":[7]}],"verseLabel":"الأنعام: 7","question":"ما دلالة التصريح بالأيدي في قوله تعالى: ﴿فلمسوه بأيديهم﴾ مع أن اللمس يكون بها غالبًا؟","answer":"ذكر الأيدي توكيدًا للمباشرة الحسية وقطعًا لاحتمال أن يكون المراد نظرًا متخيلًا أو لمسًا مجازيًا؛ فقد جمع الفرض رؤية القرطاس ولمسه بأداة اللمس نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص272–273، تحت «فائدة ذكر الأيدي بعد اللمس»","url":""}]},{"id":"s6-42","number":42,"surah":6,"verses":[7],"references":[{"surah":6,"verses":[7]}],"verseLabel":"الأنعام: 7","question":"ما دلالة افتراض لمس الكتاب وعدم الاكتفاء بمشاهدته؟","answer":"لأنهم قد يزعمون أن المرئي تخييل أو سحر للأبصار، فبلغ بهم البرهان إلى مباشرة القرطاس باليد؛ ليقرر أن عنادهم سيبقى ولو اجتمعت حاستا البصر واللمس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص272، تحت «دلالة التعبير باللمس دون المعاينة»","url":""}]},{"id":"s6-43","number":43,"surah":6,"verses":[7],"references":[{"surah":6,"verses":[7]}],"verseLabel":"الأنعام: 7","question":"ما دلالة القصر في قولهم: ﴿إن هذا إلا سحر مبين﴾؟","answer":"حصروا الكتاب المحسوس في السحر توكيدًا لحكمهم الباطل، ففضح الأسلوب غاية عنادهم؛ إذ جعلوا الدليل المشاهد عين السحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص273، تحت عنوان «دلالة القصر في قول الله تعالى: ﴿إن هذا إلا سحر مبين﴾»","url":""}]},{"id":"s6-1045","number":1045,"surah":6,"verses":[7],"references":[{"surah":6,"verses":[7]}],"verseLabel":"الأنعام: 7","question":"ما دلالة وصف السحر بكونه ﴿مبينًا﴾؟","answer":"زعموا أنه ظاهر واضح في السحر، فبلغت مكابرتهم أن قلبوا وضوح الآية إلى وضوح في تهمتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص273–274، تحت عنوان «دلالة وصف السحر بكونه مبينًا في الآية الكريمة»","url":""}]},{"id":"s6-44","number":44,"surah":6,"verses":[8],"references":[{"surah":6,"verses":[8]}],"verseLabel":"الأنعام: 8","question":"ما دلالة تقديم ﴿عليه﴾ في قولهم: ﴿لولا أنزل عليه ملك﴾؟","answer":"قدموا ﴿عليه﴾ لإفادة الاختصاص؛ فهم يطلبون أن ينزل الملك على الرسول ﷺ خاصة ليشهد له بالرسالة. ويتوجه اقتراحهم إلى نزول الملك عليه الذي لم يشاهدوه، مع أن الغرض منه محاولة تعجيزه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص277، تحت «بلاغة تقديم المتعلق على نائب الفاعل»","url":""}]},{"id":"s6-45","number":45,"surah":6,"verses":[8],"references":[{"surah":6,"verses":[8]}],"verseLabel":"الأنعام: 8","question":"ما وجه مجاز الحذف في قوله تعالى: ﴿ولو أنزلنا ملكًا لقضي الأمر﴾؟","answer":"حذف ما دل عليه السياق، أي: ولو أنزلنا ملكًا فكذبوا به لقضي أمر إهلاكهم؛ فالإيجاز يسرع إلى النتيجة المخيفة لمقترحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص278، تحت عنوان «وجه مجاز الحذف في قوله تعالى: ﴿ولو أنزلنا ملكًا لقضي الأمر﴾»","url":""}]},{"id":"s6-1046","number":1046,"surah":6,"verses":[8],"references":[{"surah":6,"verses":[8]}],"verseLabel":"الأنعام: 8","question":"ما فائدة ﴿ثم﴾ في قوله تعالى: ﴿ثم لا ينظرون﴾؟","answer":"تفيد التراخي الرتبي؛ فعدم الإمهال بعد قضاء الأمر نتيجة شديدة، وتقرر أنهم إذا عاينوا الملك ثم كذبوا لم يؤخر عنهم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص278–279، تحت عنوان «فائدة التعبير بـ«ثم» في قوله: ﴿ثم لا ينظرون﴾»","url":""}]},{"id":"s6-46","number":46,"surah":6,"verses":[8],"references":[{"surah":6,"verses":[8]}],"verseLabel":"الأنعام: 8","question":"ما دلالة حذف الأمر المقضي في قوله تعالى: ﴿لقضي الأمر﴾؟","answer":"الحذف هنا في تفصيل ما يترتب على إنزال الملك: فإما أن يصدقوا فينجوا، وإما أن يكذبوا فيقضى عليهم بعذابهم وهلاكهم؛ و﴿الأمر﴾ هو أمر عذابهم، حُذف مضافه إليه وعُوّضت عنه اللام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص278–279، تحت «وجه مجاز الحذف في قوله تعالى: ﴿ولو أنزلنا ملكًا لقضي الأمر﴾».","url":""}]},{"id":"s6-47","number":47,"surah":6,"verses":[8],"references":[{"surah":6,"verses":[8]}],"verseLabel":"الأنعام: 8","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم لا ينظرون﴾ دون الفاء؟","answer":"تفيد ﴿ثم﴾ الترتيب مع التراخي الرتبي: فنفي الإمهال أشد من قضاء أمر العذاب؛ لأن مفاجأة الشدة وعدم منحهم مهلة أشد وقعًا من نفس وقوع العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص279، تحت «فائدة التعبير بـ«ثم» في قوله: ﴿ثم لا ينظرون﴾»","url":""}]},{"id":"s6-48","number":48,"surah":6,"verses":[9],"references":[{"surah":6,"verses":[9]}],"verseLabel":"الأنعام: 9","question":"كيف يُفهم قوله تعالى: ﴿ولو جعلناه ملكًا لجعلناه رجلًا﴾؟","answer":"لا يطيق البشر عادة رؤية الملك على صورته، فلو كان الرسول ملكًا لجعله الله في صورة رجل ليتمكنوا من رؤيته والتلقي عنه؛ وعندئذ يعود الاشتباه نفسه الذي اتخذوه حجة على الرسول البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص282–283، تحت عنوان «نكتة تفصيل الحكمة في جعل المرسل بالوحي رجلًا لا ملكًا»","url":""}]},{"id":"s6-49","number":49,"surah":6,"verses":[9],"references":[{"surah":6,"verses":[9]}],"verseLabel":"الأنعام: 9","question":"ما دلالة تكرار ﴿جعلناه﴾ في قوله تعالى: ﴿ولو جعلناه ملكًا لجعلناه رجلًا﴾؟","answer":"تعلق الجعل الأول باختيار جنس الرسول المفترض، أي ملكًا، وتعلق الثاني بالصورة التي لا بد أن يظهر بها للناس، أي رجلًا؛ فكل فعل ينشئ مرحلة مختلفة من الفرض والنتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص284، تحت «سر ترتيب الضميرين وتكرير ﴿جعلناه﴾ في سياق الآية الكريمة»","url":""}]},{"id":"s6-50","number":50,"surah":6,"verses":[9],"references":[{"surah":6,"verses":[9]}],"verseLabel":"الأنعام: 9","question":"ما التشبيه الضمني في قوله تعالى: ﴿وللبسنا عليهم ما يلبسون﴾؟","answer":"شُبّه ما ينشأ عن تمثل الملك رجلًا من التباس بما يصنعونه هم من خلط الحق بالباطل؛ فدل التركيب على أن مقترحهم يعيد العلة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص284–285، تحت عنوان «بلاغة التعبير بالتشبيه الضمني في قوله تعالى: ﴿وللبسنا عليهم﴾»","url":""}]},{"id":"s6-1047","number":1047,"surah":6,"verses":[9],"references":[{"surah":6,"verses":[9]}],"verseLabel":"الأنعام: 9","question":"ما بلاغة الاحتباك في قوله تعالى: ﴿وللبسنا عليهم ما يلبسون﴾؟","answer":"ذُكر في الأول من يقع عليه اللبس، وحذف متعلقه، وذُكر في الثاني ما يلبسونه وحذف من يلبسون عليه؛ فدل كل طرف على محذوف الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص285–286، تحت عنوان «بلاغة الاحتباك في قوله تعالى: ﴿وللبسنا عليهم ما يلبسون﴾»","url":""}]},{"id":"s6-51","number":51,"surah":6,"verses":[9],"references":[{"surah":6,"verses":[9]}],"verseLabel":"الأنعام: 9","question":"ما دلالة ﴿ما﴾ في قوله تعالى: ﴿وللبسنا عليهم ما يلبسون﴾؟","answer":"تحتمل المصدرية، أي: مثل لبسهم، وتحتمل الموصولية، أي: الأمر الذي يلبسونه؛ فتتسع لما يخلطونه من الحق وبما يوقعونه من التباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص286–287، تحت عنوان «معنى ﴿ما﴾ في قوله: ﴿ما يلبسون﴾»","url":""}]},{"id":"s6-52","number":52,"surah":6,"verses":[10],"references":[{"surah":6,"verses":[10]}],"verseLabel":"الأنعام: 10","question":"ما دلالة البناء للمجهول في قوله تعالى: ﴿ولقد استهزئ برسل من قبلك﴾؟","answer":"وجه البناء العناية إلى وقوع الاستهزاء بالرسل بوصفه سنة متكررة، لا إلى أسماء المستهزئين؛ وفيه تسلية للنبي ﷺ بأن ما لقيه قد لقيه رسل قبله ثم كانت العاقبة للمكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص291–292، تحت «سر بناء الفعل للمفعول في قوله تعالى: ﴿استهزئ﴾»","url":""}]},{"id":"s6-53","number":53,"surah":6,"verses":[10],"references":[{"surah":6,"verses":[10]}],"verseLabel":"الأنعام: 10","question":"ما دلالة تنكير ﴿رسل﴾ في قوله تعالى: ﴿برسل من قبلك﴾؟","answer":"يفيد تنكير ﴿رسل﴾ أن كثيرًا من الرسل من قبلك قد استهزأت بهم أقوامهم، فيتسع بذلك معنى التسلية ويظهر أن الاستهزاء سنة متكررة؛ ولم يُعرّف اللفظ لأن بعض الرسل لم يتعرض لهذا الاستهزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص292، تحت «بلاغة التنكير في قوله تعالى: ﴿برسل﴾»","url":""}]},{"id":"s6-54","number":54,"surah":6,"verses":[10],"references":[{"surah":6,"verses":[10]}],"verseLabel":"الأنعام: 10","question":"ما الفرق الدلالي بين ﴿حاق﴾ و﴿أحاط﴾ في تصوير الجزاء؟","answer":"الحَيْق نزول المكروه بصاحبه ولزومه إياه، أما الإحاطة فأعم في تطويق الشيء من جوانبه؛ فاختيار ﴿حاق﴾ يصور حلول العذاب بالساخرين والتصاقه بهم جزاء استهزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص296–297، تحت عنوان ««حاق» و«أحاط»»","url":""}]},{"id":"s6-55","number":55,"surah":6,"verses":[10],"references":[{"surah":6,"verses":[10]}],"verseLabel":"الأنعام: 10","question":"ما دلالة التنويع بين ﴿استهزئ﴾ و﴿سخروا﴾ و﴿يستهزئون﴾؟","answer":"الاستـهزاء أخف ويكون أولًا، ثم تأتي السخرية مرحلةً أشد فيها مبالغة وتسخير للجهد؛ لذلك بدأ بـ﴿استهزئ﴾ ثم قال ﴿سخروا﴾، وعاد إلى ﴿يستهزئون﴾ لأنه أخف ولأن تركيب «يسخرون منه» أثقل في هذا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص297–299، تحت «(سخروا) و(استهزؤوا)».","url":""}]},{"id":"s6-56","number":56,"surah":6,"verses":[10],"references":[{"surah":6,"verses":[10]}],"verseLabel":"الأنعام: 10","question":"ما دلالة قوله تعالى: ﴿فحاق بالذين سخروا منهم ما كانوا به يستهزئون﴾، فكأن المستهزأ به هو الذي حاق بهم؟","answer":"أُسند الحيق إلى ما كانوا يستهزئون به لأن استهزاءهم بما أنذرت به الرسل هو السبب المؤدي إلى العقاب، فصُوّر السبب كأنه المعاقِب؛ ويصح أن يكون المراد أن العذاب الذي استهزؤوا به قد أحاط بهم حقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص295، تحت «بلاغة المجاز العقلي في سياق الآية الكريمة»","url":""}]},{"id":"s6-57","number":57,"surah":6,"verses":[11],"references":[{"surah":6,"verses":[11]}],"verseLabel":"الأنعام: 11","question":"ما المقصود بالسير في قوله تعالى: ﴿قل سيروا في الأرض﴾، وما صلته بالاعتبار؟","answer":"السير هو الانتقال من مكان إلى مكان، والمقصود أن ينتقلوا في الأرض، ولا سيما فيما قرب من ديار المهلكين، ليعاينوا آثارهم ويتخذوا منها العظة؛ فالأمر ليس انتقالًا مجردًا، بل سير اعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص300، تحت «معنى قوله تعالى: ﴿سيروا﴾ وقوله: ﴿انظروا﴾ في الآية الكريمة»","url":""}]},{"id":"s6-58","number":58,"surah":6,"verses":[11],"references":[{"surah":6,"verses":[11]}],"verseLabel":"الأنعام: 11","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم انظروا﴾ دون الفاء؟","answer":"تفيد ﴿ثم﴾ التباعد الرتبي: فالسير في ذاته مباح، أما النظر للتدبر والاعتبار فواجب، ورتبة التأمل والنظر أعلى من رتبة مجرد السير؛ لذلك لم يعطفه بالفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص303–304، تحت «التشابه اللفظي ووجه العطف بالحرف ﴿ثم﴾»","url":""}]},{"id":"s6-59","number":59,"surah":6,"verses":[11],"references":[{"surah":6,"verses":[11]}],"verseLabel":"الأنعام: 11","question":"ما دلالة قوله تعالى: ﴿كيف كان عاقبة المكذبين﴾ دون: ماذا كانت عاقبتهم؟","answer":"﴿كيف﴾ تسأل عن هيئة النهاية وفظاعتها، لا عن اسمها أو مجرد وقوعها؛ فتدعو إلى تأمل صور الهلاك وآثاره وتفاصيله التي يشاهدها السائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص302–303، تحت «سر تعليق ﴿كيف﴾ بفعل النظر».","url":""}]},{"id":"s6-60","number":60,"surah":6,"verses":[11],"references":[{"surah":6,"verses":[11]}],"verseLabel":"الأنعام: 11","question":"ما سرّ وصف الهالكين بـ﴿المكذبين﴾ بعد ذكر الاستهزاء؟","answer":"وصفهم بالمكذبين لأن التكذيب أعم: يجمع المستهزئين والساخرين ويشمل كل من كذب ولو لم يسخر أو يستهزئ؛ وفي السياق دلالة على أن كلًا من التكذيب والاستهزاء كاف في استحقاق تلك العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص305، تحت «التكذيب والاستهزاء»","url":""}]},{"id":"s6-61","number":61,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما دلالة أن يسأل النبي ﷺ: ﴿قل لمن ما في السماوات والأرض﴾ ثم يتولى الجواب: ﴿قل لله﴾؟","answer":"لأن الخصم لا يملك جوابًا صحيحًا إلا الإقرار بملك الله أو المكابرة بما تعرف الفطرة بطلانه، فتولى الوحي الجواب ليقرر الحجة سريعًا ولا يترك للمراوغة مجالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص309، تحت «سر المبادرة بالجواب عن السؤال دون انتظار جوابهم في ﴿قل لله﴾»","url":""}]},{"id":"s6-62","number":62,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما دلالة تقديم ﴿لله﴾ في جواب قوله تعالى: ﴿قل لله﴾؟","answer":"تقديم الجار والمجرور يفيد قصر ملك ما في السماوات والأرض على الله وحده، وهو المقصود من السؤال والحجة على بطلان ولاية غيره وعبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص308–309، تحت «إفادة الحصر في قوله تعالى: ﴿قل لله﴾»","url":""}]},{"id":"s6-63","number":63,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما دلالة الفعل ﴿كتب﴾ بين الحقيقة والمجاز في قوله تعالى: ﴿كتب على نفسه الرحمة﴾؟","answer":"الكتابة استعارة للعهد المؤكد الثابت الذي تفضل الله به، فصورت الرحمة حكمًا محققًا من غير أن يوجب عليه ذلك مخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص309–310، تحت عنوان «دلائل الفعل ﴿كتب﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s6-1048","number":1048,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما وجه التعميم في ذكر الرحمة في قوله تعالى: ﴿كتب على نفسه الرحمة﴾؟","answer":"أطلق الرحمة لتشمل أنواعها وآثارها في الدنيا والآخرة، فدل اللفظ العام على سعة فضل الله بخلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص310، تحت عنوان «وجه التعميم في ذكر الرحمة»","url":""}]},{"id":"s6-1049","number":1049,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما بلاغة اعتراض قوله تعالى: ﴿كتب على نفسه الرحمة﴾؟","answer":"جاءت الجملة معترضة لتطمئن السامع إلى سعة الرحمة بين تقرير الملك والوعيد بالجمع، فجمعت الترغيب بالترهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص310–311، تحت عنوان «بلاغة الاعتراض بقوله تعالى: ﴿كتب على نفسه الرحمة﴾»","url":""}]},{"id":"s6-64","number":64,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما سر تقديم الجار والمجرور في قوله تعالى: ﴿كتب على نفسه الرحمة﴾؟","answer":"قدم ﴿على نفسه﴾ للاهتمام بتفضله سبحانه بإلزام ذاته بالرحمة، ولبيان اختصاصه بهذا الوعد المؤكد من غير إيجاب أحد عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص309–310، تحت عنوان «سر تقديم الجار والمجرور في الآية الكريمة»","url":""}]},{"id":"s6-65","number":65,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما مناسبة الانتقال من كتابة الرحمة إلى التهديد بالجمع يوم القيامة؟","answer":"بعد بيان أن رحمته تقتضي عدم تعجيل العقوبة وقبول الإنابة والتوبة، قابل ذلك بالجمع ليوم القيامة الذي يقتضي المحاسبة والعقاب؛ فجمعت الآية الوعد والوعيد، وقدمت الوعد بالرحمة قبل التهديد بالجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص311، تحت «بلاغة الاعتراض بقوله تعالى: ﴿كتب على نفسه الرحمة﴾»","url":""}]},{"id":"s6-66","number":66,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما دلالة اجتماع اللام والنون في قوله تعالى: ﴿ليجمعنكم﴾؟","answer":"اللام موطئة لقسم مقدر، ونون التوكيد الثقيلة تثبت وقوع الجمع تثبيتًا قويًا؛ فاجتمعتا لمواجهة إنكار البعث وإزالة كل ريب في مجيئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص311–312، تحت «تحقيق الوعيد باللام والنون في قوله تعالى: ﴿ليجمعنكم﴾».","url":""}]},{"id":"s6-67","number":67,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما دلالة قوله تعالى: ﴿إلى يوم القيامة﴾ دون: في يوم القيامة؟","answer":"تحتمل ﴿إلى﴾ أن تكون بمعنى ﴿في﴾، أي: ليجمعنكم في يوم القيامة؛ وتحتمل بقاءها على انتهاء الغاية، أي يجمعكم في الدنيا بموتكم ويستمر هذا الجمع إلى يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص312، تحت «معنى ﴿إلى﴾ في قوله تعالى: ﴿إلى يوم القيامة﴾»","url":""}]},{"id":"s6-68","number":68,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما الاستعارة في قوله تعالى: ﴿الذين خسروا أنفسهم﴾؟","answer":"شُبه تفويتهم الإيمان وما يترتب عليه من النجاة بخسارة التاجر رأس ماله؛ بل خسروا ذواتهم كلها بالعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص313–314، تحت عنوان «دلالة الاستعارة في قوله تعالى: ﴿خسروا أنفسهم﴾»","url":""}]},{"id":"s6-1050","number":1050,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما دلالة التعبير عن الذات بالنفس في قوله تعالى: ﴿خسروا أنفسهم﴾؟","answer":"يقرر أن الخسارة أصابت أعز ما يملكون، وهي ذواتهم، لا مالًا أو منفعة خارجة عنهم؛ فاشتد الترهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص314، تحت عنوان «وجه التعبير عن الذات بالنفس»","url":""}]},{"id":"s6-1051","number":1051,"surah":6,"verses":[12],"references":[{"surah":6,"verses":[12]}],"verseLabel":"الأنعام: 12","question":"ما سر الفصاحة بذكر السبب بعد المسبب في قوله: ﴿الذين خسروا أنفسهم فهم لا يؤمنون﴾؟","answer":"قدّم خسران النفس لأنه النتيجة الأشد والأجدر بالتخويف، ثم ذكر عدم الإيمان سببًا له؛ فلفت أولًا إلى العاقبة ثم كشف منشأها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص314–315، تحت عنوان «سر الفصاحة بذكر السبب بعد المسبب»","url":""}]},{"id":"s6-69","number":69,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما دلالة قوله تعالى: ﴿وله ما سكن في الليل والنهار﴾ بعد تقرير ملك ما في السماوات والأرض؟","answer":"انتقل من استيعاب المكان إلى استيعاب الزمان؛ فما في السماوات والأرض ملكه أينما كان، وما حل في الليل والنهار ملكه في كل وقت، فتتكامل إحاطة الملك بالمكان والزمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص320–321، تحت «بلاغة تقديم المكان على الزمان في السياق»","url":""}]},{"id":"s6-70","number":70,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما دلالة الفعل الماضي ﴿سكن﴾ وسر البدء به في قوله تعالى: ﴿وله ما سكن في الليل والنهار﴾؟","answer":"يفيد تحقق استقرار الموجودات في سلطان الله، وبدأ بالسكون لأنه أغلب أحوالها ولأنه أدل على خضوعها وقرارها في ملكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص319–320، تحت عنوان «دلالة الفعل الماضي ﴿سكن﴾ وسر البدء به»","url":""}]},{"id":"s6-1052","number":1052,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما بلاغة الاكتفاء بـ﴿سكن﴾ وحذف المقدر؟","answer":"اكتفى بذكر الساكن لأن المتحرك مفهوم بالمقابلة وبطريق الأولى، أو لأن السكون بمعنى الحلول والاستقرار فيشمل ما يحتويه الليل والنهار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص321، تحت عنوان «بلاغة الاكتفاء بـ﴿سكن﴾ وحذف المقدر في الآية»","url":""}]},{"id":"s6-71","number":71,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"كيف يدل الجمع بين ﴿الليل والنهار﴾ على شمول ملك الله لكل وقت؟","answer":"يشمل الليل والنهار جميع الأوقات، فكل كائن يوجد أو يسكن في وقت من أوقاتهما؛ وبالجمع بينهما يقرر التعبير إحاطة ملك الله بالمخلوقات على اختلاف أزمنتها وأحوالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص321، تحت «دلالة الطباق في لفظي ﴿الليل والنهار﴾»","url":""}]},{"id":"s6-72","number":72,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما دلالة تقديم ﴿له﴾ في قوله تعالى: ﴿وله ما سكن﴾؟","answer":"يفيد التقديم اختصاص الملك الحقيقي بالله لكل ما يحتويه الليل والنهار؛ فلا يخرج موجود في أي وقت عن سلطانه، وهو استمرار لقصر الملك في الآية السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص319، تحت «وجه تقديم الجار والمجرور على المسند إليه».","url":""}]},{"id":"s6-73","number":73,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما بلاغة ختم قوله تعالى: ﴿وله ما سكن في الليل والنهار﴾ بقوله: ﴿وهو السميع العليم﴾؟","answer":"ربطت الخاتمة ملكه للموجودات بإحاطته بها؛ فهو يسمع أقوالها ويعلم ظاهرها وخفيها، وفي ذلك وعيد لمن يخالفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص322، تحت عنوان «بلاغة ختم الآية بما يناسب الوعيد والتهديد»","url":""}]},{"id":"s6-1053","number":1053,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما دلالة وجهي السمع في وصف الله تعالى بـ﴿السميع﴾؟","answer":"يدل على إحاطة الله بكل مسموع، كما يدل على إجابة من دعاه؛ فاجتمع كمال العلم بأصوات الخلق وكمال القرب ممن يسأله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص322–323، تحت عنوان «دلالة وجهي السمع في الآية الكريمة»","url":""}]},{"id":"s6-1054","number":1054,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما وجه المبالغة في صفتي ﴿السميع العليم﴾؟","answer":"جاء الوصفان على صيغتي مبالغة للدلالة على كمال الإحاطة بالمسموعات والمعلومات، فلا يخفى عليه صوت ولا حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص323، تحت عنوان «وجه المبالغة في صفتي ﴿السميع العليم﴾»","url":""}]},{"id":"s6-74","number":74,"surah":6,"verses":[13],"references":[{"surah":6,"verses":[13]}],"verseLabel":"الأنعام: 13","question":"ما سرّ تقديم ﴿السميع﴾ على ﴿العليم﴾؟","answer":"قُدّم ﴿السميع﴾ لمناسبة ذكر الليل أولًا، فالسمع حاسة تعمل في الظلام؛ ثم جاء ﴿العليم﴾ لمناسبة ذكر النهار، إذ يكون فيه نشاط المخلوقات وحركتها واكتساب العلم والخبرة، فحُفظ ترتيب ألفاظ الآية في خاتمتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص322، تحت «بلاغة اللف والنشر في الآية الكريمة»","url":""}]},{"id":"s6-75","number":75,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما دلالة تقديم ﴿غير الله﴾ في قوله تعالى: ﴿أغير الله أتخذ وليًا﴾؟","answer":"قدم المفعول لأن إنكار اتخاذ غير الله هو محور السؤال، ويفيد السياق القصر: لا أتخذ وليًا مستحقًا للعبادة والنصرة من دون الله؛ فالمرفوض ذات البديل قبل فعل الاتخاذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص326–327، تحت «بلاغة التقديم في قوله تعالى: ﴿أغير الله أتخذ وليًا﴾»","url":""}]},{"id":"s6-76","number":76,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما دلالة وصف الله بأنه ﴿فاطر السماوات والأرض﴾ دون: خالق السماوات والأرض؟","answer":"الفاطر هو المبتدئ للخلق؛ فالوصف يذكر بأنه سبحانه أصل وجود السماوات والأرض. وناسب ذلك إنكار اتخاذ ولي غيره: فالذي أوجد الخلق ويدبر أمرهم هو المستحق للولاية والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص324–325، تحت عنوان «شرح المفردات: ﴿فاطر﴾»","url":""}]},{"id":"s6-77","number":77,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما المجاز في قوله تعالى: ﴿وهو يطعم ولا يطعم﴾؟","answer":"جعل الإطعام كناية عن الإنعام والرزق والتدبير؛ فمن يرزق الخلق ويقوم بأمرهم هو المستحق للولاية والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص326–327، تحت عنوان «بلاغة المجاز في قوله تعالى: ﴿وهو يطعم ولا يطعم﴾»","url":""}]},{"id":"s6-1055","number":1055,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما وجه التعريض في قوله تعالى: ﴿وهو يطعم ولا يطعم﴾؟","answer":"فيه تعريض بعجز آلهتهم وافتقارها؛ فالله يرزق ولا يحتاج، وما سواه محتاج لا يملك لنفسه ولا لغيره رزقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص327، تحت عنوان «وجه التعريض»","url":""}]},{"id":"s6-1056","number":1056,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما بلاغة طباق السلب في قوله تعالى: ﴿يطعم ولا يطعم﴾؟","answer":"قابل بين إثبات الإطعام لله ونفي أن يطعمه غيره، فبرز كمال غناه مع تمام إنعامه على خلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص327–328، تحت عنوان «بلاغة طباق السلب»","url":""}]},{"id":"s6-1057","number":1057,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما سر بناء الفعل للمفعول في قوله تعالى: ﴿ولا يطعم﴾؟","answer":"حذف الفاعل لأن المقصود نفي الحاجة عن الله من أي جهة كانت؛ فلا يطعمه أحد ولا يفتقر إلى مطعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص328–329، تحت عنوان «سر بناء الفعل للمفعول في قوله: ﴿ولا يطعم﴾»","url":""}]},{"id":"s6-78","number":78,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما دلالة تكرار الأمر ﴿قل﴾ في الآية؟","answer":"جدد ﴿قل﴾ كل إعلان مستقل: إنكار اتخاذ ولي غير الله، ثم التصريح بأمره أن يكون أول من أسلم والتحذير من الشرك؛ فتكراره يفصل مقامات الحجة ويؤكد أن كل جواب وحي مأمور بإبلاغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص329، تحت «بلاغة إعادة الأمر ﴿قل﴾ في الآية الكريمة»","url":""}]},{"id":"s6-79","number":79,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"كيف يُفهم قوله تعالى: ﴿أمرت أن أكون أول من أسلم﴾ مع سبق الأنبياء والمؤمنين؟","answer":"أي أول من أسلم من هذه الأمة ومن المخاطبين برسالته، أو أولهم مبادرةً وامتثالًا فيما كُلّف بتبليغه؛ فلا ينفي إسلام الأنبياء وأتباعهم في الأمم السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص329–330، تحت «بلاغة التعبير بالأولية في قوله تعالى: ﴿أول من أسلم﴾»","url":""}]},{"id":"s6-80","number":80,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما دلالة الانتقال من قوله تعالى: ﴿إني أمرت﴾ إلى الخطاب المباشر: ﴿ولا تكونن من المشركين﴾؟","answer":"حكى أولًا الأمر الذي تلقاه بالإسلام، ثم جاء النهي موجهًا إليه مباشرةً ليشتد وقعه ويبلغ الأمة من ورائه؛ فالانتقال من الخبر عن التكليف إلى خطاب التحذير يجعل البراءة من الشرك حاضرة مؤكدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص330–331، تحت «بلاغة الالتفات من المتكلم إلى المخاطب في الآية الكريمة»","url":""}]},{"id":"s6-81","number":81,"surah":6,"verses":[14],"references":[{"surah":6,"verses":[14]}],"verseLabel":"الأنعام: 14","question":"ما دلالة قوله تعالى: ﴿من المشركين﴾ دون: مشركًا؟","answer":"النهي عن أن يكون منتميًا إلى جماعة المشركين أو مجتمعهم، لا عن مجرد اتصافه بالشرك؛ وهو أبلغ لأن طرق الشرك كثيرة، ومن عاشر أهلها خيف عليه الوقوع فيها، أما سبيل الإيمان فواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص332–333، تحت عنوان «دلالة معنى ﴿من﴾ في قوله تعالى: ﴿من المشركين﴾»","url":""}]},{"id":"s6-82","number":82,"surah":6,"verses":[15],"references":[{"surah":6,"verses":[15]}],"verseLabel":"الأنعام: 15","question":"ما دلالة قول النبي ﷺ: ﴿إني أخاف إن عصيت ربي عذاب يوم عظيم﴾ مع عصمته؟","answer":"الشرط فرض للتعليم والتعريض بالمشركين؛ فإذا كان الرسول ﷺ، مع عصمته واستحالة المعصية منه، يعلن خوفه على سبيل الفرض، فغيره أولى بالخوف. وفيه أن لا محاباة لأحد مهما عظم، وأن الحكم منوط بالأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص335–336، تحت عنوان «بلاغة التعبير بـ﴿إن﴾ الشرطية دون «إذا»»","url":""}]},{"id":"s6-83","number":83,"surah":6,"verses":[15],"references":[{"surah":6,"verses":[15]}],"verseLabel":"الأنعام: 15","question":"ما دلالة الماضي في قوله تعالى: ﴿إن عصيت﴾ مع أن الشرط مفترض؟","answer":"يأتي الماضي بعد أداة الشرط لتصوير الفعل المفروض كأنه تحقق واستحضر أثره، وللدلالة على جدية الملازمة بين العصيان والعذاب؛ فلا يعني أن المعصية وقعت من النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص336، تحت «فائدة صيغة الماضي في قوله تعالى: ﴿عصيت﴾»","url":""}]},{"id":"s6-84","number":84,"surah":6,"verses":[15],"references":[{"surah":6,"verses":[15]}],"verseLabel":"الأنعام: 15","question":"ما دلالة قوله تعالى: ﴿عصيت ربي﴾ دون: عصيت الله؟","answer":"عُدل عن اسم الجلالة إلى ﴿ربي﴾ للإيماء إلى قبح العصيان؛ فكيف يُعصى الرب؟ وفي لفظ ﴿ربي﴾ كناية عن الولاء لله والاستسلام إليه سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص336، تحت «وجه الكناية في العدول عن اسم الجلالة إلى ﴿ربي﴾»","url":""}]},{"id":"s6-85","number":85,"surah":6,"verses":[15],"references":[{"surah":6,"verses":[15]}],"verseLabel":"الأنعام: 15","question":"ما بلاغة الإطناب والإيغال في لفظ ﴿يوم﴾ في قوله: ﴿عذاب يوم عظيم﴾؟","answer":"زاد ذكر اليوم تهويلًا؛ لأنه يستحضر ظرفًا جامعًا لأهوال البعث والحساب والجزاء، فلا يقف التصوير عند ألم واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص336، تحت عنوان «بلاغة الإطناب والإيغال في لفظ ﴿يوم﴾»","url":""}]},{"id":"s6-1058","number":1058,"surah":6,"verses":[15],"references":[{"surah":6,"verses":[15]}],"verseLabel":"الأنعام: 15","question":"ما الوجه البلاغي في وصف العذاب بالعظمة في قوله تعالى: ﴿عذاب يوم عظيم﴾؟","answer":"عظم العذاب بعظمة اليوم الذي يقع فيه وما يضم من أهوال متعددة، فانتقل الذهن من عقوبة جزئية إلى مشهد القيامة كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص336–337، تحت عنوان «الوجه البلاغي في وصف ﴿عذاب﴾ بأنه ﴿عظيم﴾»","url":""}]},{"id":"s6-86","number":86,"surah":6,"verses":[16],"references":[{"surah":6,"verses":[16]}],"verseLabel":"الأنعام: 16","question":"ما دلالة البناء للمجهول في قوله تعالى: ﴿من يصرف عنه يومئذ فقد رحمه﴾؟","answer":"بُني ﴿يُصرف﴾ للمفعول لأن الصارف معلوم، وهو الله تعالى، فحُذف للعلم به والإيجاز، وقد تقدم ذكر ﴿الرب﴾ فدل عليه؛ وفي قراءة أخرى جاء الفعل مبنيًا للفاعل: ﴿يصرف﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص340، تحت «بلاغة الإيجاز في قوله تعالى: ﴿من يصرف عنه﴾»","url":""}]},{"id":"s6-87","number":87,"surah":6,"verses":[16],"references":[{"surah":6,"verses":[16]}],"verseLabel":"الأنعام: 16","question":"لم أعيد ذكر اليوم في ﴿من يصرف عنه يومئذ﴾ بعد قوله: ﴿عذاب يوم عظيم﴾؟","answer":"أعيد ذكره لتأكيد عظم شأنه وتحقيق وقوعه؛ فهو يوم ليس كسائر الأيام، بل توزن فيه أعمال الدنيا كلها. لذلك كان صرف العذاب فيه هو الرحمة والفوز العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص340–341، تحت «وجه الإطناب في تكرير ذكر اليوم في قوله تعالى: ﴿يومئذ﴾»","url":""}]},{"id":"s6-88","number":88,"surah":6,"verses":[16],"references":[{"surah":6,"verses":[16]}],"verseLabel":"الأنعام: 16","question":"ما دلالة التعبير عن النجاة من العذاب بقوله تعالى: ﴿فقد رحمه﴾ دون: فقد نجا؟","answer":"عُبر عن صرف العذاب بالرحمة لأن الرحمة هي النجاة والفلاح، ولأن دفع عذاب القيامة يعقبه دخول الجنان؛ فصرف العذاب نفسه دخول في رحمة الله الشاملة، واتحاد معنى الشرط والجزاء يعظم شأن هذه الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص341، تحت عنوان «حسن اختيار الفعل مع الضمير في ﴿رحمه﴾»","url":""}]},{"id":"s6-89","number":89,"surah":6,"verses":[16],"references":[{"surah":6,"verses":[16]}],"verseLabel":"الأنعام: 16","question":"ما بلاغة اسم الإشارة في قوله تعالى: ﴿وذلك الفوز المبين﴾؟","answer":"أشير بالبعيد إلى صرف العذاب والرحمة لتعظيم منزلتهما ورفع قدر هذا الفوز.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص342، تحت عنوان «بلاغة التعبير باسم الإشارة ﴿وذلك﴾»","url":""}]},{"id":"s6-1059","number":1059,"surah":6,"verses":[16],"references":[{"surah":6,"verses":[16]}],"verseLabel":"الأنعام: 16","question":"ما وجه التعريف في قوله تعالى: ﴿الفوز المبين﴾؟","answer":"عرّف الفوز لأنه الفوز الكامل المعهود الذي لا يدانيه غيره: النجاة من العذاب ودخول الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص342–343، تحت عنوان «وجه التعريف في ﴿الفوز المبين﴾»","url":""}]},{"id":"s6-1060","number":1060,"surah":6,"verses":[16],"references":[{"surah":6,"verses":[16]}],"verseLabel":"الأنعام: 16","question":"ما سر تذييل الآية بقوله تعالى: ﴿وذلك الفوز المبين﴾؟","answer":"لخصت الجملة نتيجة صرف العذاب، وقررت أن النجاة يوم القيامة هي الفوز الواضح الكامل الذي يستلزم الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص343، تحت عنوان «سر التذييل في قوله تعالى: ﴿وذلك الفوز المبين﴾»","url":""}]},{"id":"s6-90","number":90,"surah":6,"verses":[17],"references":[{"surah":6,"verses":[17]}],"verseLabel":"الأنعام: 17","question":"ما دلالة اختيار المس في قوله تعالى: ﴿وإن يمسسك الله بضر﴾؟","answer":"استُعير المس للإصابة بالضر، وفيه تصوير لقرب أثره من الإنسان ولو كان قليلًا؛ فالمس أخف من الإصابة الشديدة. والمعنى أن أدنى ما يصيب الإنسان من ضر لا يملك كشفه إلا الله، فكيف بما هو أشد؟","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص346–347، تحت عنوان «دلالة الاستعارتين التبعيتين في قوله تعالى: ﴿وإن يمسسك الله بضر﴾»","url":""}]},{"id":"s6-91","number":91,"surah":6,"verses":[17],"references":[{"surah":6,"verses":[17]}],"verseLabel":"الأنعام: 17","question":"ما دلالة مقابلة ﴿بضر﴾ بقوله تعالى: ﴿بخير﴾ دون: بنفع؟","answer":"الضر ضد النفع، لكن النظم قابل ﴿الضر﴾ بـ﴿الخير﴾ لأن الخير أعم من النفع، كما أن الشر أعم من الضر؛ فشمل الخير الغنى والصحة وغيرهما، ودلت المقابلة على أن كل ما يصيب الإنسان من خير أو شر فمن عند الله","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص347–348، تحت «وجه الطباق بين الضر والخير»","url":""}]},{"id":"s6-92","number":92,"surah":6,"verses":[17],"references":[{"surah":6,"verses":[17]}],"verseLabel":"الأنعام: 17","question":"ما بلاغة الحصر في قوله تعالى: ﴿فلا كاشف له إلا هو﴾؟","answer":"قصر كشف الضر على الله قصرًا حقيقيًا؛ فلا يملك أحد رفع ما أنزله، وفيه إبطال التعلق بغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص348، تحت عنوان «بلاغة الحصر في قوله تعالى: ﴿فلا كاشف له إلا هو﴾»","url":""}]},{"id":"s6-1061","number":1061,"surah":6,"verses":[17],"references":[{"surah":6,"verses":[17]}],"verseLabel":"الأنعام: 17","question":"ما فائدة صيغة المبالغة ﴿قدير﴾ في قوله تعالى: ﴿فهو على كل شيء قدير﴾؟","answer":"دلت على كمال القدرة وعمومها، فشملت إيصال الخير وكشف الضر وسائر الممكنات من غير عجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص349، تحت عنوان «فائدة التعبير بصيغة المبالغة في ﴿قدير﴾»","url":""}]},{"id":"s6-93","number":93,"surah":6,"verses":[17],"references":[{"surah":6,"verses":[17]}],"verseLabel":"الأنعام: 17","question":"ما دلالة اختيار ﴿كاشف﴾ لإزالة الضر؟","answer":"الكشف هو رفع ما يواري الشيء ويغطيه، كرفع الغطاء عنه؛ فاستعمل مجازًا في إزالة الضر والغم، وصُوّر الضر كأنه غطاء لا يرفعه عن المصاب إلا الله","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص344، تحت «شرح المفردات: ﴿كاشف﴾»","url":""}]},{"id":"s6-94","number":94,"surah":6,"verses":[17],"references":[{"surah":6,"verses":[17]}],"verseLabel":"الأنعام: 17","question":"ما دلالة الانتقال في جانب الخير إلى قوله تعالى: ﴿فهو على كل شيء قدير﴾؟","answer":"انتقل من ذكر إصابة الخير إلى عموم القدرة؛ فدل قوله ﴿فهو على كل شيء قدير﴾ على الجواب المحذوف: إن يمسسك بخير فلا مانع له، لأنه قدير على الضر والنفع جميعًا، ومهّد بذلك لقوله ﴿وهو القاهر فوق عباده﴾ إذ الأقدار كلها بيده","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص349، تحت «فائدة التعبير بصيغة المبالغة في ﴿قدير﴾»","url":""}]},{"id":"s6-95","number":95,"surah":6,"verses":[18],"references":[{"surah":6,"verses":[18]}],"verseLabel":"الأنعام: 18","question":"ما دلالة تعريف ﴿القاهر﴾ في قوله تعالى: ﴿وهو القاهر فوق عباده﴾؟","answer":"يفيد تعريف طرفي الجملة القصر: لا قاهر على الحقيقة إلا الله؛ فلا يغلبه أحد ولا يعجزه شيء، وعباده داخلون تحت قدرته وتدبيره. فالوصف يقرر انفراده بالغلبة المطلقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص352–353، تحت «دلالة القصر في قوله تعالى: ﴿وهو القاهر فوق عباده﴾»","url":""}]},{"id":"s6-96","number":96,"surah":6,"verses":[18],"references":[{"surah":6,"verses":[18]}],"verseLabel":"الأنعام: 18","question":"كيف يُفهم قوله تعالى: ﴿وهو القاهر فوق عباده﴾، وهل المراد فوقية مكان تحيط به؟","answer":"تصور ﴿فوق عباده﴾ قهر الله وغلبته تصويرًا تمثيليًا بحال من يأخذ المغلوب من أعلاه فلا يجد مهربًا؛ والفوقية هنا فوقية قدرة وغلبة، وتأتي كذلك للمنزلة والشرف، والله فوق كل شيء على الوجه اللائق به دون تشبيه بالمخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص353–354، تحت «بلاغة الاستعارة التمثيلية في قوله تعالى: ﴿وهو القاهر فوق عباده﴾».","url":""}]},{"id":"s6-97","number":97,"surah":6,"verses":[18],"references":[{"surah":6,"verses":[18]}],"verseLabel":"الأنعام: 18","question":"ما دلالة قوله تعالى: ﴿فوق عباده﴾ دون: فوق خلقه؟","answer":"وصف العباد يبرز خضوعهم وافتقارهم وكونهم مملوكين له، فيناسب القهر والسيادة، كما يذكر المكلفين بأنهم عبيد لا يملكون الاستقلال عن حكم ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص354، تحت «علّة ذكر الخاص وإرادة العام في قوله تعالى: ﴿فوق عباده﴾».","url":""}]},{"id":"s6-98","number":98,"surah":6,"verses":[18],"references":[{"surah":6,"verses":[18]}],"verseLabel":"الأنعام: 18","question":"ما دلالة تذييل ما سبق بقوله تعالى: ﴿وهو القاهر فوق عباده﴾؟","answer":"قرر التذييل أن تصرف الله في الضر والخير ناشئ عن قهر شامل وسلطان لا يخرج عنه أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص352، تحت عنوان «دلالة تذييل الآية ﴿وهو القاهر﴾ لما قبلها»","url":""}]},{"id":"s6-1062","number":1062,"surah":6,"verses":[18],"references":[{"surah":6,"verses":[18]}],"verseLabel":"الأنعام: 18","question":"ما وجه ذكر العام بعد الخاص في الانتقال إلى قوله: ﴿وهو القاهر فوق عباده﴾؟","answer":"بعد ذكر قدرته على الضر والخير عُمم الحكم بقهره لعباده، فدخلت تلك الصور وغيرها في سلطان واحد شامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص352، تحت عنوان «وجه ذكر العام بعد الخاص»","url":""}]},{"id":"s6-99","number":99,"surah":6,"verses":[18],"references":[{"surah":6,"verses":[18]}],"verseLabel":"الأنعام: 18","question":"ما مناسبة الجمع بين ﴿الحكيم﴾ و﴿الخبير﴾ بعد ذكر القهر؟","answer":"جاء ﴿الحكيم الخبير﴾ بعد القهر ليقترن كمال القدرة بكمال العلم؛ فالله يقهر عباده بقدرته وحكمته، وهو خبير بما يحتاج إليه خلقه وما يلائمهم، فيجري تدبيره على الحكمة البالغة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص354–355، تحت «بلاغة اقتران الاسمين الكريمين: ﴿الحكيم الخبير﴾».","url":""}]},{"id":"s6-100","number":100,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما سرّ الاستفهام بـ﴿أي شيء أكبر شهادة﴾، دون: مَن أكبر الشهداء؟","answer":"لفظ ﴿شيء﴾ من أعم الألفاظ، فوسّع دائرة المفاضلة لتشمل كل ما يمكن أن تُتصوّر له شهادة، ثم جاء الجواب بأن الله أكبر شهادة؛ فلا تبقى شهادة تقابل شهادته أو تدانيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص362–363، تحت «دلالة إيثار لفظ ﴿شيء﴾ دون لفظ «شهيد» في قوله: ﴿قل أي شيء﴾»","url":""}]},{"id":"s6-101","number":101,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما الغرض من الاستفهام بـ﴿أي﴾ في قوله تعالى: ﴿أي شيء أكبر شهادة﴾؟","answer":"يوقظ السامع ويهيئه للنظر في أكبر شهادة، ويلزمه الإقرار بأن شهادة الله لا تعلوها شهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص360، تحت عنوان «الغرض من استعمال الاستفهام ﴿أي﴾»","url":""}]},{"id":"s6-1063","number":1063,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة المبادرة بالجواب في قوله تعالى: ﴿قل أي شيء أكبر شهادة قل الله﴾؟","answer":"حسم الوحي النتيجة التي لا تحتمل جوابًا آخر، وأعلن أن الله هو الأكبر شهادة قبل أن يجد المكذبون سبيلًا للمماراة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص365–366، تحت عنوان «دلالة المبادرة بالجواب عن السؤال في قوله: ﴿قل أي شيء أكبر شهادة﴾»","url":""}]},{"id":"s6-102","number":102,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة التعبير باسم ﴿شهيد﴾ في قوله تعالى: ﴿قل الله شهيد بيني وبينكم﴾؟","answer":"﴿شهيد﴾ صيغة تدل على ثبوت الشهادة وقوتها وإحاطتها؛ وشهادة الله منزّهة عن الكذب والخطأ والسهو، وتظهر فيما أقامه من آيات وبراهين على صدق رسوله ﷺ. فناسب الاسم مقام الاحتكام الفاصل بين الرسول والمكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص366، تحت عنوان «دلالة التعبير بقوله ﴿شهيد﴾ دون شاهد»","url":""}]},{"id":"s6-103","number":103,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة تكرار ﴿بين﴾ في قوله تعالى: ﴿بيني وبينكم﴾؟","answer":"أعيدت ﴿بين﴾ مع الطرف الثاني لإظهار طرفي الخصومة مستقلين في مقام الاحتكام: الرسول ﷺ من جهة، والمكذبون من جهة أخرى. والتكرار هو الأسلوب العربي المبين للعلاقة بين جانبين، وفيه تقوية لصورة الفصل بالشهادة بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص366، تحت «دلالة تكرار ﴿بين﴾ في قوله تعالى: ﴿بيني وبينكم﴾ بدلًا من قوله: بيننا».","url":""}]},{"id":"s6-104","number":104,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة بناء الفعل للمفعول في قوله تعالى: ﴿وأوحي إلي هذا القرآن﴾؟","answer":"حُذف فاعل الوحي للعلم به؛ فالسياق قد عيّن أن الله هو الشهيد وهو موحي القرآن، وتوجه الاهتمام إلى نفس الوحي الواصل إلى الرسول ﷺ وإلى الكتاب الذي صار حجةً وإنذارًا. فالحذف لا يُجهّل المصدر، بل يبرز موضع الاستدلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص369، تحت «دلالة بناء الفعل ﴿أوحي﴾ في قوله تعالى: ﴿وأوحي إلي هذا القرآن﴾».","url":""}]},{"id":"s6-105","number":105,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة اسم الإشارة في قوله تعالى: ﴿وأوحي إلي هذا القرآن﴾؟","answer":"استحضر القرآن المعلوم المتلو عليهم وعيّن الحجة الحاضرة، فكأنهم يواجهون الشاهد على صدق الرسول مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص368، تحت عنوان «دلالة التعبير باسم الإشارة في قوله: ﴿هذا القرآن﴾»","url":""}]},{"id":"s6-1064","number":1064,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة اختيار لفظ ﴿القرآن﴾ دون ﴿الكتاب﴾؟","answer":"اختير القرآن لإبراز الوحي المتلو المسموع الذي بلغهم به الرسول، وتمييزه من الكتب السابقة التي يشملها اسم الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص368–369، تحت عنوان «دلالة اختيار لفظ القرآن دون الكتاب»","url":""}]},{"id":"s6-106","number":106,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"لم جعل قوله تعالى: ﴿لأنذركم به﴾ الإنذار غايةً لإيحاء القرآن هنا مع أنه يتضمن البشارة أيضًا؟","answer":"لأن المقام خطاب للمكابرين المعاندين، فناسبه التحذير مما يترتب على كفرهم. والاقتصار على الإنذار هنا لا ينفي البشارة؛ فالقرآن يجمعهما، والغاية المذكورة تناسب حال المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص369–370، تحت «سر التعبير بالنذارة دون البشارة في قوله: ﴿لأنذركم به﴾»","url":""}]},{"id":"s6-107","number":107,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة الإيجاز بالحذف في قوله تعالى: ﴿ومن بلغ﴾؟","answer":"حذف مفعول ﴿بلغ﴾ لاتضاحه، أي: ومن بلغه القرآن، وأوجز الحذف مع تعميم كل من وصل إليه الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص369، تحت عنوان «دلالة الإيجاز بالحذف في قوله تعالى: ﴿ومن بلغ﴾»","url":""}]},{"id":"s6-1065","number":1065,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة اختيار لفظ البلاغ في قوله تعالى: ﴿ومن بلغ﴾؟","answer":"يشمل اللفظ كل من وصل إليه القرآن أو معناه على وجه تقوم به الحجة، في أي لسان وزمان ومكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص371، تحت عنوان «دلالة اختيار لفظ البلاغ دون غيره في قوله: ﴿ومن بلغ﴾»","url":""}]},{"id":"s6-108","number":108,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة عطف ﴿ومن بلغ﴾ على المخاطبين في قوله تعالى: ﴿لأنذركم به ومن بلغ﴾؟","answer":"نقل العطف الإنذار من المخاطبين الأولين في مكة إلى كل إنسان يبلغه القرآن؛ فمن بلغه بعد الرسول ﷺ فكأنما سمعه منه ما دام قد وصل إليه بلا زيادة ولا نقصان. وبذلك دلّ التركيب على عموم الرسالة واستمرار حجتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص370، تحت «دلالة عطف ﴿ومن بلغ﴾ على ضمير المخاطبين ﴿لأنذركم﴾».","url":""}]},{"id":"s6-109","number":109,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما بلاغة التعبير بالاستفهام في قوله: ﴿أئنكم لتشهدون أن مع الله آلهة أخرى﴾ بدل الخبر؟","answer":"واجههم الاستفهام إنكارًا وتوبيخًا بعد قيام شهادة الله، وكشف أن دعواهم لا يمكن أن تقوم على شهادة معتبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص372، تحت عنوان «بلاغة التعبير بالأسلوب الإنشائي دون الخبري»","url":""}]},{"id":"s6-1066","number":1066,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما علة التوكيد في قوله تعالى: ﴿أئنكم لتشهدون﴾؟","answer":"اجتمع الاستفهام و﴿إن﴾ واللام لاستقصاء الحجة وإبراز فظاعة شهادتهم بالشرك مع وضوح بطلانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص372–373، تحت عنوان «علة التوكيد بقوله تعالى: ﴿أئنكم لتشهدون﴾»","url":""}]},{"id":"s6-110","number":110,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما سرّ وصف جمع ﴿آلهة﴾ بالمفرد المؤنث ﴿أخرى﴾؟","answer":"﴿آلهة﴾ جمع لغير العاقل، ووصف جمع غير العاقل يجري مجرى المفردة المؤنثة؛ فقيل ﴿أخرى﴾. وفي ذلك أيضًا جمع لهذه المعبودات في وصف واحد، والتنبيه على ضعفها وهوان أمرها وبطلان تسميتها آلهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص373–374، تحت «دلالة وصف الآلهة بالتأنيث في قوله: ﴿آلهة أخرى﴾»","url":""}]},{"id":"s6-111","number":111,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة تكرار الأمر ﴿قل﴾ أربع مرات في الآية؟","answer":"تكرر ﴿قل﴾ أربع مرات لأن كل مقولة بعدها رسالة مستقلة عظيمة يجب إعلانها: طرح الحجة، وتعيين الله شهيدًا، ورفض شهادة الشرك، وإعلان التوحيد والبراءة منه. وفي التكرار تلقين للنبي ﷺ وتثبيت وعناية، وتنبيه إلى أهمية كل جواب ومبادرة تبليغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص374، تحت عنوان «علة تكرار الأمر بـ﴿قل﴾ في قوله تعالى: ﴿قل لا أشهد قل إنما هو إله واحد﴾»","url":""}]},{"id":"s6-112","number":112,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة الجواب الموجز الحاسم: ﴿قل لا أشهد﴾؟","answer":"جاء النفي مباشرًا ليقطع كل احتمال لموافقتهم على شهادة الشرك؛ فلا يدخل الرسول ﷺ معهم في أصل الدعوى ولا يطيل مناقشة شهادة لا برهان لها. ثم أعقب الرفض بإثبات الحق: ﴿قل إنما هو إله واحد﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص375، تحت «دلالة الفصل بين قوله: ﴿قل لا أشهد﴾ وقوله: ﴿قل إنما هو إله واحد﴾»","url":""}]},{"id":"s6-113","number":113,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة القصر في قوله تعالى: ﴿إنما هو إله واحد﴾؟","answer":"قصر الألوهية على الله وحده، فنفى أن يكون معه إله آخر يستحق العبادة. وجاء الضمير عائدًا إلى الله المذكور قبلُ، فاستغنى به عن تكرار الاسم، وانتقل الكلام من نفي شهادة الشرك إلى تقرير حقيقة التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص375–376، تحت «دلالة القصر في قوله تعالى: ﴿قل إنما هو إله واحد﴾»","url":""}]},{"id":"s6-114","number":114,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة التعبير بالاسم ﴿بريء﴾ في قوله تعالى: ﴿وإنني بريء مما تشركون﴾؟","answer":"الاسم يدل على ثبوت البراءة واستقرارها، لا على فعل عارض يقع مرة؛ والبراءة في أصلها تخلّص ومفارقة وتباعد مما يُكره. فالصيغة إعلان دائم قاطع بمفارقة الشرك وما يُعبد من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص377، تحت عنوان «دلالة اختيار ﴿بريء﴾ دون غيرها في قوله: ﴿وإنني بريء مما تشركون﴾»","url":""}]},{"id":"s6-115","number":115,"surah":6,"verses":[19],"references":[{"surah":6,"verses":[19]}],"verseLabel":"الأنعام: 19","question":"ما دلالة عموم قوله تعالى: ﴿مما تشركون﴾؟","answer":"الموصول ﴿ما﴾ يعم كل ما يجعلونه شريكًا لله، والتعبير بالفعل يستحضر فعل الإشراك المتجدد ولا يقتصر على أسماء أصنام بعينها. فالبراءة شاملة للمعبودات الباطلة وللمنهج الذي يسوّيها بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص377–378، تحت «دلالة التعبير بـ«ما» في قوله تعالى: ﴿مما تشركون﴾؛ ودلالة التعبير بالفعل المضارع في قوله: ﴿تشركون﴾»","url":""}]},{"id":"s6-116","number":116,"surah":6,"verses":[20],"references":[{"surah":6,"verses":[20]}],"verseLabel":"الأنعام: 20","question":"إلى مَن يعود الضمير في قوله تعالى: ﴿يعرفونه كما يعرفون أبناءهم﴾؟","answer":"يعود الضمير إلى النبي محمد ﷺ؛ أي إن علماء أهل الكتاب يعرفونه بحليته ونعته الثابت في كتبهم كما يعرفون أبناءهم. وجاءت الآية حجة على المكذبين بمعرفة أهل الكتاب بصدق نبوته، مع أن بعض المفسرين وسّع مرجع الضمير إلى القرآن أو الحق المتقدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص387–388، تحت عنوان «تعدد أقوال المفسرين في عود الضمير في قوله تعالى: ﴿يعرفونه﴾»","url":""}]},{"id":"s6-117","number":117,"surah":6,"verses":[20],"references":[{"surah":6,"verses":[20]}],"verseLabel":"الأنعام: 20","question":"ما دلالة التعبير بالموصول في قوله تعالى: ﴿الذين آتيناهم الكتاب﴾؟","answer":"عرّفهم بالصلة التي هي موضع الحجة: إيتاؤهم الكتاب ودراستهم له. فالمقصود خاصة علماؤهم الذين عرفوا ما في التوراة والإنجيل من صفة النبي ﷺ، لا كل منتسب إلى أهل الكتاب؛ وبذلك صار علمهم سببًا للاحتجاج بشهادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص384، تحت «دلالة التعريف بالاسم الموصول في قوله: ﴿الذين آتيناهم الكتاب﴾»","url":""}]},{"id":"s6-118","number":118,"surah":6,"verses":[20],"references":[{"surah":6,"verses":[20]}],"verseLabel":"الأنعام: 20","question":"ما دلالة تعريف ﴿الكتاب﴾ في قوله تعالى: ﴿آتيناهم الكتاب﴾؟","answer":"التعريف للعهد؛ أي الكتاب المعروف الذي أوتيته كل طائفة، وهو التوراة لليهود والإنجيل للنصارى. وفي التعريف استحضار المرجع الذي قامت به معرفتهم، فلا تصدر شهادتهم عن ظن بل عما وجدوه في الوحي الذي بأيديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص386–387، تحت «دلالة دخول «أل» على لفظ ﴿الكتاب﴾ في قوله: ﴿الذين آتيناهم الكتاب﴾»","url":""}]},{"id":"s6-119","number":119,"surah":6,"verses":[20],"references":[{"surah":6,"verses":[20]}],"verseLabel":"الأنعام: 20","question":"ما دلالة التعبير بـ﴿يعرفونه﴾، دون: يعلمونه؟","answer":"المعرفة تتعلق بذات الشيء وتمييزه من آثاره وصفاته، أما العلم فيتسع للحكم على أحواله ونِسَبه؛ فناسبت ﴿يعرفونه﴾ معرفتهم شخص النبي ﷺ بصفته ونعته، كما تُعرف ذات الابن معرفة لا اشتباه فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص387، تحت «سر اختيار التعبير القرآني لكلمة ﴿يعرفونه﴾ دون يعلمونه»","url":""}]},{"id":"s6-120","number":120,"surah":6,"verses":[20],"references":[{"surah":6,"verses":[20]}],"verseLabel":"الأنعام: 20","question":"ما دلالة التشبيه في قوله تعالى: ﴿يعرفونه كما يعرفون أبناءهم﴾؟","answer":"قرر التشبيه أن معرفتهم بالنبي ﷺ واضحة متمكنة لا يشوبها التباس، كمعرفة المرء بأقرب الناس إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص388، تحت عنوان «دلالة التشبيه في قوله تعالى: ﴿كما يعرفون أبناءهم﴾»","url":""}]},{"id":"s6-1067","number":1067,"surah":6,"verses":[20],"references":[{"surah":6,"verses":[20]}],"verseLabel":"الأنعام: 20","question":"ما سر اختيار الأبناء في قوله تعالى: ﴿كما يعرفون أبناءهم﴾؟","answer":"الابن ألصق الناس بأبيه وأكثرهم حضورًا بين يديه، فتتميز صورته وصفاته لديه بلا اشتباه؛ فناسبه تمثيل المعرفة اليقينية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص388–389، تحت عنوان «سر اختيار لفظ الأبناء دون غيرهم في قوله تعالى: ﴿كما يعرفون أبناءهم﴾»","url":""}]},{"id":"s6-121","number":121,"surah":6,"verses":[20],"references":[{"surah":6,"verses":[20]}],"verseLabel":"الأنعام: 20","question":"ما دلالة عدم عطف قوله تعالى: ﴿الذين خسروا أنفسهم فهم لا يؤمنون﴾ على ما قبله؟","answer":"جاءت الجملة مستأنفة لتبين مآل من عرف الحق ثم لم يؤمن به، فكأنها جواب عن سؤال يثيره إثبات معرفتهم: فما حال من كتمها؟ حاله أنه خسر نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص389–390، تحت عنوان «دلالة عدم عطف جملة ﴿الذين خسروا أنفسهم﴾ على ما قبلها»","url":""}]},{"id":"s6-122","number":122,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"ما فائدة العدول من النفي إلى الاستفهام في قوله تعالى: ﴿ومن أظلم ممن افترى على الله كذبًا﴾؟","answer":"الاستفهام إنكاري يفيد أنه لا أحد أبلغ ظلمًا ممن اختلق على الله أو كذب بآياته؛ لأن الجريمتين تفسدان أصل الهداية: إحداهما تنسب إلى الله ما لم يقل، والأخرى ترد ما أقام عليه حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص397–398، تحت عنوان «فائدة العدول من النفي إلى الاستفهام في قوله: ﴿ومن أظلم ممن افترى﴾»","url":""}]},{"id":"s6-123","number":123,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"ما دلالة صيغة أفعل التفضيل في قوله تعالى: ﴿أظلم﴾؟","answer":"تدل ﴿أظلم﴾ على بلوغ المفترين والمكذبين أعلى درجات الظلم؛ لعظم جرأتهم على الله بنسبة الشريك أو الولد إليه، ولتكذيبهم بآياته وإنكار رسوله. والاستفهام المصاحب ينفي أن يوجد من هو أشد منهم ظلمًا في هذا الباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص398، تحت عنوان «سر التعبير بـ«أفعل» التفضيل في قوله: ﴿ومن أظلم ممن افترى على الله﴾»","url":""}]},{"id":"s6-124","number":124,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"ما دلالة الجمع بين ﴿افترى﴾ و﴿كذبًا﴾ في قوله تعالى: ﴿افترى على الله كذبًا﴾؟","answer":"الافتراء هو الكذب المتعمد المختلق، وجاء ﴿كذبًا﴾ مصدرًا مؤكدًا له يصرح بقبح حقيقته ويزيل كل احتمال أن يكون خطأً أو وهمًا. وفي التقارب الاشتقاقي مع ﴿كذّب﴾ بعده إبراز لوجهي الجريمة: اختلاق الباطل وردّ الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص400، تحت «تقديم الافتراء على الكذب»","url":""}]},{"id":"s6-125","number":125,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"ما دلالة العطف بـ﴿أو﴾ بين الافتراء على الله والتكذيب بآياته؟","answer":"تفيد ﴿أو﴾ أن كل واحد من الفعلين مستقل في بلوغ غاية الظلم، سواء اختلق المرء على الله باطلًا أم رد آياته الثابتة؛ وقد يجتمعان في شخص واحد، فيجمع بين صناعة الكذب ومحاربة الحق. فهي تمنع توهم أن الحكم لا يثبت إلا باجتماعهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص400–401، تحت «دلالة ﴿أو﴾ في قوله تعالى: ﴿أو كذب بآياته﴾»","url":""}]},{"id":"s6-126","number":126,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"ما دلالة دخول الباء على ﴿آياته﴾ في قوله تعالى: ﴿أو كذب بآياته﴾؟","answer":"وصلت الباء فعل التكذيب بالآيات وصورت تلبس المكذب بإنكارها وملازمته له؛ فكلما واجه آية تصدى لردها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص401–402، تحت عنوان «دلالة دخول حرف الجر على قوله تعالى: ﴿بآياته﴾»","url":""}]},{"id":"s6-1068","number":1068,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"لماذا قيل: ﴿بآياته﴾ دون «بالقرآن»؟","answer":"لأن الآيات أعم؛ فتشمل آيات الوحي ودلائل الكون وما أقامه الله من براهين، فيعم الوعيد كل تكذيب بحججه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص401–402، تحت عنوان «دلالة التعبير بـ﴿بآياته﴾ دون القرآن في قوله: ﴿أو كذب بآياته﴾»","url":""}]},{"id":"s6-127","number":127,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"ما دلالة وضع الظاهر موضع المضمر في قوله تعالى: ﴿لا يفلح الظالمون﴾؟","answer":"أظهر وصف الظلم بدل أن يقال «لا يفلحون» ليصرح بعلة الحرمان من الفلاح، وهي ظلمهم بالافتراء والتكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص403–404، تحت عنوان «دلالة التعبير بوضع الظاهر موضع المضمر في قوله: ﴿لا يفلح الظالمون﴾»","url":""}]},{"id":"s6-1069","number":1069,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"لماذا قيل: ﴿الظالمون﴾ دون «الأظلمون»؟","answer":"لئلا يوهم وصف الأظلم أن من كان أقل ظلمًا قد يفلح بظلمه؛ فنفى الفلاح عن جنس الظالمين كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص404، تحت عنوان «سر التعبير بلفظ ﴿الظالمون﴾ دون الأظلمون»","url":""}]},{"id":"s6-128","number":128,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما دلالة قوله تعالى: ﴿ويوم نحشرهم جميعًا﴾؟","answer":"أكد ﴿جميعًا﴾ استيعاب الحشر للعابدين ومعبوداتهم من غير تخلف، لتقع المواجهة على رؤوس الأشهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص411–412، تحت عنوان «دلالة التعبير بقوله ﴿جميعًا﴾ في قوله تعالى: ﴿ويوم نحشرهم جميعًا﴾»","url":""}]},{"id":"s6-1070","number":1070,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"لماذا قيل: ﴿جميعًا﴾ دون «كل» في آية الحشر؟","answer":"لأن ﴿جميعًا﴾ تصور ضم الأفراد بعضهم إلى بعض في موقف واحد، أما ﴿كل﴾ فتركز على استغراق الأفراد ولو متفرقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص412، تحت عنوان «سر التعبير بلفظ ﴿جميعًا﴾ دون (كل) في الآية»","url":""}]},{"id":"s6-129","number":129,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم نقول للذين أشركوا﴾؟","answer":"تفيد ﴿ثم﴾ التراخي بين الحشر وبين سؤال التقريع؛ فيُجمعون أولًا في هول الموقف، ثم تأتي المواجهة التي تكشف سقوط شركائهم. ويصلح التراخي هنا للزمن ولرتبة ما بعده من شدة التوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص412–413، تحت «سر التعبير بحرف العطف ﴿ثم﴾ في قوله تعالى: ﴿ثم نقول للذين أشركوا﴾»","url":""}]},{"id":"s6-130","number":130,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما دلالة وصفهم بالصلة في قوله تعالى: ﴿للذين أشركوا﴾، دون: للمشركين؟","answer":"الصلة تستحضر الفعل الذي صار سببًا للسؤال والعقوبة: هم الذين أحدثوا الشرك وجعلوا لله أندادًا. وفي الفعل الماضي تسجيل للجريمة التي وقعت منهم، تمهيدًا لتبكيتهم على الشركاء الذين زعموهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص413، تحت «دلالة التعبير بقوله ﴿للذين أشركوا﴾ بدلًا من المشركين»","url":""}]},{"id":"s6-131","number":131,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"لماذا أوثر الاستفهام في قوله تعالى: ﴿أين شركاؤكم﴾ بدل الخبر؟","answer":"للتقريع والتعجيز؛ إذ يلزمهم أن يطلبوا شركاءهم فلا يجدوهم، فيظهر بطلان اعتقادهم في صورة مواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص413–414، تحت عنوان «إيثار الاستفهام بدلًا من الخبر في قوله تعالى: ﴿أين شركاؤكم﴾»","url":""}]},{"id":"s6-1071","number":1071,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما المجاز في قوله تعالى: ﴿أين شركاؤكم الذين كنتم تزعمون﴾؟","answer":"استعمل سؤال المكان وأريد به نفي وجود الشركاء ونفعهم؛ فعدم العثور على مكانهم كناية عن تلاشي دعواهم وعجز معبوداتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص414، تحت عنوان «بلاغة المجاز في قوله تعالى: ﴿أين شركاؤكم الذين كنتم تزعمون﴾»","url":""}]},{"id":"s6-132","number":132,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما دلالة إضافة الشركاء إليهم في قوله تعالى: ﴿شركاؤكم﴾؟","answer":"أضيفوا إلى المشركين لأنهم شركاء في زعمهم واختراعهم وحدهم، لا شركاء لله في الحقيقة؛ فالإضافة تتبرأ من إقرار تسميتهم، وتحملهم تبعة ما صنعوه من نسبة الشريك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص414–415، تحت «علة الإضافة في قوله تعالى: ﴿أين شركاؤكم﴾»","url":""}]},{"id":"s6-133","number":133,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما دلالة حذف معمولي ﴿تزعمون﴾ في قوله تعالى: ﴿الذين كنتم تزعمون﴾؟","answer":"حذف المفعولان لدلالة السياق عليهما، والتقدير: تزعمونهم شركاء. وفي هذا الإيجاز تحقير للدعوى وأصحابها، وإيحاء بضياع ما تعلقوا به وانقطاع الصلات التي توهموها بينهم وبين معبوداتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص416، تحت «دلالة حذف مفعولي زعم في قوله تعالى: ﴿الذين كنتم تزعمون﴾»","url":""}]},{"id":"s6-134","number":134,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما سر التعبير بالزعم في قوله تعالى: ﴿الذين كنتم تزعمون﴾؟","answer":"الزعم قول لا يقوم على برهان ويُتهم صاحبه فيه، فسمى اعتقادهم زعمًا ليكشف أنه دعوى باطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص416، تحت عنوان «سر التعبير بالزعم في قوله: ﴿الذين كنتم تزعمون﴾»","url":""}]},{"id":"s6-1072","number":1072,"surah":6,"verses":[22],"references":[{"surah":6,"verses":[22]}],"verseLabel":"الأنعام: 22","question":"ما دلالة المضارع في قوله تعالى: ﴿الذين كنتم تزعمون﴾؟","answer":"استحضر تجدد زعمهم واستمرارهم عليه في الدنيا، فزاد سؤالهم عنه يوم القيامة تقريعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص416–417، تحت عنوان «دلالة التعبير بالفعل المضارع في قوله: ﴿الذين كنتم تزعمون﴾»","url":""}]},{"id":"s6-135","number":135,"surah":6,"verses":[23],"references":[{"surah":6,"verses":[23]}],"verseLabel":"الأنعام: 23","question":"ما دلالة تسمية جوابهم يوم القيامة ﴿فتنتهم﴾؟","answer":"الفتنة هنا ما انتهى إليه افتتانهم بالشرك من معذرة وجواب مضطرب؛ فلم يجدوا عند الامتحان إلا أن ينكروا ما كانوا عليه. وتسميته فتنتهم تصل مبدأ الضلال في الدنيا بعاقبته الفاضحة في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص420–421، تحت «التعبير بلفظ الفتنة في قوله تعالى: ﴿ثم لم تكن فتنتهم﴾»","url":""}]},{"id":"s6-136","number":136,"surah":6,"verses":[23],"references":[{"surah":6,"verses":[23]}],"verseLabel":"الأنعام: 23","question":"ما دلالة القصر في قوله تعالى: ﴿ثم لم تكن فتنتهم إلا أن قالوا﴾؟","answer":"حصر القصر كل ما استطاعوا تقديمه من معذرة في قول واحد هو إنكار شركهم؛ فلم تبق لهم حجة ولا دفاع سوى الكذب. وفي ذلك تصوير لإفلاسهم بعد أن كانوا يجادلون ويزعمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص422، تحت «دلالة أسلوب القصر في قوله: ﴿ثم لم تكن فتنتهم إلا أن قالوا﴾»","url":""}]},{"id":"s6-137","number":137,"surah":6,"verses":[23],"references":[{"surah":6,"verses":[23]}],"verseLabel":"الأنعام: 23","question":"ما دلالة قسمهم يوم القيامة: ﴿والله ربنا ما كنا مشركين﴾؟","answer":"أكدوا إنكارهم بالقسم لشعورهم بأن دعواهم لا تصدق؛ فهم يعلمون ما كانوا عليه من الشرك، ومع ذلك يحاولون نفيه بين يدي الله. فيكشف القسم شدة مكابرتهم، ويجعل كذبهم على أنفسهم أظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص423، تحت «دلالة توكيد الخبر بالقسم في قوله تعالى: ﴿والله ربنا ما كنا مشركين﴾»","url":""}]},{"id":"s6-138","number":138,"surah":6,"verses":[23],"references":[{"surah":6,"verses":[23]}],"verseLabel":"الأنعام: 23","question":"ما دلالة ذكر الربوبية بعد الألوهية في قولهم: ﴿والله ربنا﴾؟","answer":"اعترفوا بأن المقسم به ربهم المالك لأمرهم؛ فجاء إقرار الربوبية في قلب إنكار الشرك ليكشف تناقضهم ويزيد كذبهم ظهورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص423، تحت عنوان «دلالة ذكر الربوبية بعد ذكر الألوهية في قوله تعالى: ﴿والله ربنا﴾»","url":""}]},{"id":"s6-1073","number":1073,"surah":6,"verses":[23],"references":[{"surah":6,"verses":[23]}],"verseLabel":"الأنعام: 23","question":"ما أثر القراءات في معنى قوله تعالى: ﴿والله ربنا ما كنا مشركين﴾؟","answer":"على نصب ﴿ربنا﴾ يكون نداءً أو مدحًا، وعلى جره يكون وصفًا لاسم الجلالة؛ وفي الوجهين إقرار بأن الله ربهم مع قسمهم الكاذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص423، تحت عنوان «أثر القراءات في تفسير قوله تعالى: ﴿والله ربنا ما كنا مشركين﴾»","url":""}]},{"id":"s6-139","number":139,"surah":6,"verses":[23],"references":[{"surah":6,"verses":[23]}],"verseLabel":"الأنعام: 23","question":"ما دلالة ﴿ثم﴾ في الانتقال من سؤالهم عن الشركاء إلى قوله: ﴿ثم لم تكن فتنتهم إلا أن قالوا﴾؟","answer":"تفيد انتقالًا إلى حال أعجب وأشد استحقاقًا للتعجيب: بعد افتتانهم بالشرك واستقرارهم عليه في الدنيا، يتبرؤون منه ويحلفون أنهم لم يكونوا مشركين. فالتراخي في رتبة الخبر يبرز انقلابهم وتناقضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص420، تحت «إيثار التعبير بـ﴿ثم﴾ في قوله تعالى: ﴿ثم لم تكن فتنتهم﴾»","url":""}]},{"id":"s6-140","number":140,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"ما المجاز في قوله تعالى: ﴿انظر كيف كذبوا على أنفسهم﴾؟","answer":"أطلق النظر وأريد التأمل في هيئة كذبهم وتناقضهم، وعرض مشهد القيامة المستقبل كأنه حاضر منظور لتحقق وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص426–427، تحت عنوان «دلالة المجاز المرسل في قوله: ﴿انظر كيف كذبوا على أنفسهم﴾»","url":""}]},{"id":"s6-1074","number":1074,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"ما القيمة الدلالية للفعل ﴿انظر﴾ في قوله تعالى: ﴿انظر كيف كذبوا﴾؟","answer":"الأمر للتعجيب والاعتبار، ويوجه إلى تأمل كيفية الكذب ونتيجته لا إلى مجرد سماع خبره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص427، تحت عنوان «القيمة الدلالية للفعل ﴿انظر﴾ في قوله تعالى: ﴿انظر كيف كذبوا﴾»","url":""}]},{"id":"s6-141","number":141,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"ما دلالة الاستفهام بـ﴿كيف﴾ في قوله تعالى: ﴿انظر كيف كذبوا﴾؟","answer":"﴿كيف﴾ توجه النظر إلى هيئة الكذب العجيبة وشدته: أقسموا على نفي أمر عاشوه وظهرت حقيقته. فالمقصود التعجب من الكيفية المتناقضة، لا مجرد نقل مضمون ما قالوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص427، تحت «دلالة الاستفهام بالأداة ﴿كيف﴾ من قوله: ﴿انظر كيف كذبوا﴾»","url":""}]},{"id":"s6-142","number":142,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"ما دلالة تعدية الكذب بـ﴿على﴾ في قوله تعالى: ﴿كذبوا على أنفسهم﴾؟","answer":"صرح بـ﴿على أنفسهم﴾ ليظهر سوء قولهم وضلال تفكيرهم: فهم ينفون عن أنفسهم شركًا تعلم حقيقته، فكذبهم يناقض ما عاشوه وعرفوه. وفيه تعجيب من إنكارهم أمرًا لا يخفى عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص428، تحت «دلالة ذكر الجار والمجرور في قوله: ﴿على أنفسهم﴾»","url":""}]},{"id":"s6-143","number":143,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"ما الاستعارة في قوله تعالى: ﴿وضل عنهم ما كانوا يفترون﴾؟","answer":"صور معبوداتهم ودعاواهم بأشياء سلكت طريقًا ثم ضلت عنهم، فاختفت وقت حاجتهم ولم تنفعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص428، تحت عنوان «بلاغة الاستعارة التصريحية التبعية في قوله: ﴿وضل عنهم ما كانوا يفترون﴾»","url":""}]},{"id":"s6-1075","number":1075,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"لماذا عُبر بالضلال دون الغيبة في قوله تعالى: ﴿وضل عنهم ما كانوا يفترون﴾؟","answer":"الضلال يصور فقدان الطريق والانفصال التام، فيجعل غياب المعبودات جزاءً ساخرًا لتعلقهم بها في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص428–429، تحت عنوان «التعبير بالضلال دون الغيبة في قوله: ﴿وضل عنهم ما كانوا يفترون﴾»","url":""}]},{"id":"s6-144","number":144,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"ما دلالة ﴿ما﴾ في قوله تعالى: ﴿ما كانوا يفترون﴾؟","answer":"جاء الموصول عامًا فشمل المعبودات وما ألحقوه بها من دعاوى الشفاعة والنفع والقرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص429، تحت عنوان «دلالة ﴿ما﴾ في قوله تعالى: ﴿ما كانوا يفترون﴾»","url":""}]},{"id":"s6-1076","number":1076,"surah":6,"verses":[24],"references":[{"surah":6,"verses":[24]}],"verseLabel":"الأنعام: 24","question":"لماذا قيل: ﴿ما كانوا يفترون﴾ بدل «ما كانوا يعبدون»؟","answer":"سماها بحقيقتها: افتراءً صنعوه، فلم يقر لها باسم الشريك أو الإله إلا على جهة حكاية زعمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص430، تحت عنوان «دلالة التعبير بقوله: ﴿ما كانوا يفترون﴾ بدلًا من (ما كانوا يعبدون)»","url":""}]},{"id":"s6-145","number":145,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة الإفراد في قوله تعالى: ﴿ومنهم من يستمع إليك﴾ مع أن المستمعين جماعة؟","answer":"روعي لفظ ﴿من﴾ المفرد، فجاء ﴿يستمع﴾ بالإفراد، مع أن معناها يعم أفرادًا متعددين؛ فجمع التركيب بين إيجاز اللفظ وشمول الحكم. ثم عادت الضمائر جمعًا في ﴿قلوبهم﴾ و﴿آذانهم﴾ مراعاةً للمعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص436، تحت «دلالة التعبير بصيغة الإفراد في قوله تعالى: ﴿من يستمع إليك﴾»","url":""}]},{"id":"s6-146","number":146,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة قوله تعالى: ﴿يستمع إليك﴾، دون: يستمع إلى القرآن؟","answer":"صوّرهم وهم يقصدون مجلس النبي ﷺ ويسمعون تلاوته منه مباشرة، فتقوم عليهم الحجة بقربهم من المبلّغ والبلاغ معًا. ومع ذلك لم يكن قصدهم الاهتداء، بل انتهى استماعهم إلى المجادلة والطعن في القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص437، تحت «إيثار كاف الخطاب في «إليك» من قوله: ﴿ومنهم من يستمع إليك﴾»","url":""}]},{"id":"s6-147","number":147,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما مناسبة جعل ﴿أكنة﴾ على القلوب و﴿وقرًا﴾ في الآذان؟","answer":"الأكنة أغطية تحجب القلب عن فقه المعنى، والوقر ثقل يصمّ الأذن عن الانتفاع بالمسموع؛ فناسب كل مانع آلته. واجتماعهما يمثل فرط بُعدهم عن الحق: لا السماع الظاهر أوصل، ولا القلب الباطن فقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص440–441، تحت «سر الجمع بين الوقر والأكنة في الآية الكريمة».","url":""}]},{"id":"s6-148","number":148,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما الذي تضيفه كلمة ﴿أكنة﴾ إلى صورة الحاجز على القلوب، بدل كلمة «أغطية»؟","answer":"الأكنة أبلغ في تصوير الستر؛ فهي توحي بأن القلب مستور داخل ما يحجبه، بينما لا يلزم من الغطاء هذا المعنى. وتناسب أيضًا الحاجز النفسي والمعنوي الذي يمنع فقه القرآن، فتقوى بها صورة الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص441، تحت «دلالة اختيار ﴿أكنة﴾ دون أغطية في قوله: ﴿وجعلنا على قلوبهم أكنة﴾»","url":""}]},{"id":"s6-149","number":149,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة التعبير بـ﴿أن يفقهوه﴾، دون: أن يفهموه؟","answer":"الفقه إدراك دقيق يصل إلى مراد الكلام وما وراء ظاهره، فهو أخص من مطلق الفهم؛ والآية لا تنفي وصول أصوات القرآن إلى آذانهم، بل تنفي نفاذ معانيه وحججه إلى قلوب أصرّت على الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص442، تحت «دلالة اختيار لفظ الفقه دون لفظ الفهم».","url":""}]},{"id":"s6-150","number":150,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة قوله تعالى: ﴿وإن يروا كل آية لا يؤمنوا بها﴾؟","answer":"علق عدم إيمانهم على رؤية كل آية ليبين أن العلة ليست نقص الدليل، بل إصرار القلب؛ فلو اجتمعت لهم الآيات كلها لم ينتفعوا بها. وفي ﴿كل﴾ بلوغ بالوصف أقصى درجات المكابرة بعد انسداد السمع والفقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص443–444، تحت «دلالة التعبير بـ«إن» في قوله تعالى: ﴿وإن يروا كل آية لا يؤمنوا بها﴾؛ ودلالة الجملة الشرطية في قوله تعالى: ﴿وإن يروا كل آية لا يؤمنوا بها﴾»","url":""}]},{"id":"s6-151","number":151,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"لم قيل: ﴿لا يؤمنوا بها﴾ بدل التصريح بوصفهم بالكفر؟","answer":"في نفي الإيمان مع قيام دلائله تشنيع على موقفهم، مع إبقاء باب الدعوة مفتوحًا؛ فالتعبير يدعوهم إلى ما فقدوه من التصديق والقبول، ولا يحول وصف حالهم الراهنة إلى حكم بأنهم لن يرجعوا إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص444، تحت «دلالة التعبير بنفي الإيمان بدلًا من الكفر في قوله: ﴿لا يؤمنوا بها﴾»","url":""}]},{"id":"s6-152","number":152,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة ﴿حتى﴾ في قوله تعالى: ﴿حتى إذا جاؤوك يجادلونك﴾؟","answer":"جعلت ﴿حتى﴾ مجيئهم للمجادلة غايةً لما قبلها: يستمعون، ولا يفقهون، ولا يؤمنون، ثم ينتهي أمرهم إلى الحضور لا لطلب الحق بل لمخاصمته. فهي تكشف المآل الذي بلغ إليه إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص444–445، تحت «دلالة التعبير بـ﴿حتى﴾ في قوله تعالى: ﴿حتى إذا جاؤوك يجادلونك﴾»","url":""}]},{"id":"s6-153","number":153,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما سر التعبير بالماضي ﴿جاؤوك﴾ دون «أتوك»؟","answer":"المجيء يدل على قصد المجلس والحضور إليه، فصور سعيهم إلى النبي ﷺ مع ما أضمروه من مجادلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص445، تحت عنوان «سر التعبير بالفعل الماضي ﴿جاؤوك﴾ دون أتوك»","url":""}]},{"id":"s6-1077","number":1077,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة قوله تعالى: ﴿يجادلونك﴾ في وصف مجيئهم؟","answer":"كشفت الحال أن غايتهم عند المجيء المنازعة والعناد لا الاسترشاد، فحوّلوا قربهم من الوحي إلى خصومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص445–446، تحت عنوان «المجادلة مطلق المنازعة من خلال قوله: ﴿حتى إذا جاؤوك يجادلونك﴾»","url":""}]},{"id":"s6-154","number":154,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة إظهار الفاعل في قوله تعالى: ﴿يقول الذين كفروا﴾؟","answer":"أظهر وصف ﴿الذين كفروا﴾ بدل الضمير ليسجل عليهم الكفر ويبين أن اتهامهم القرآن ناشئ عن الجحود والمكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص447–448، تحت عنوان «دلالة إظهار الفاعل في قوله: ﴿يقول الذين كفروا﴾»","url":""}]},{"id":"s6-155","number":155,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما مناسبة فاصلة قوله تعالى: ﴿إن هذا إلا أساطير الأولين﴾ لصدر الآية؟","answer":"بدأت الآية باستماع لا يفضي إلى الفهم وختمت بالقول الذي كشف أثره؛ فقد سمعوا القرآن ثم وصفوه بالأساطير.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص448، تحت عنوان «مناسبة الفاصلة لصدر الآية الكريمة»","url":""}]},{"id":"s6-1078","number":1078,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"لماذا كان اتهام القرآن بأنه ﴿أساطير الأولين﴾ كفرًا صريحًا؟","answer":"لأنه ينفي كونه وحيًا ويزعم أنه حكايات بشرية مختلقة، فيطعن في مصدره وصدقه معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص448، تحت عنوان «اتهام القرآن بأساطير الأولين كفر صراح»","url":""}]},{"id":"s6-156","number":156,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة القصر في قولهم: ﴿إن هذا إلا أساطير الأولين﴾؟","answer":"حصروا القرآن كله في أساطير السابقين، فنفوا عنه الوحي والحق والهداية نفيًا جازمًا. ويكشف هذا القصر شدة عنادهم؛ إذ لم يكتفوا بادعاء وجود قصص فيه، بل زعموا ألا حقيقة له وراء ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص447، تحت «بلاغة قصر القلب في قوله: ﴿يقول الذين كفروا إن هذا إلا أساطير الأولين﴾»","url":""}]}]);
